(window.GIM_TS=window.GIM_TS||{})["Chullin.10"]={"from":240,"a":[["ושואלים: \u0003אליבא דמאן\u0004 \u0005[לפי שיטתו של מי]\u0006 אמר רב הונא את דבריו, שהרי בפרקנו (להלן קכד,א) נחלקו ר' ישמעאל ור' עקיבא בדינו של עור שיש עליו שתי חתיכות בשר נבילה הנפרדות זו מזו, שלדעת ר' ישמעאל הנושא אותם נטמא (כיון שנשא כזית בשר נבילה), ואולם הנוגע בהם אינו נטמא (שהרי לא נגע בנגיעה אחת בכזית בשר שלם). ואילו לדעת ר' עקיבא הן הנוגע והן הנושא אינם נטמאים. ומעתה דברי רב הונא אינם לא כשיטת ר' ישמעאל ולא כשיטת ר' עקיבא.","שהרי \u0003אי\u0004 \u0005[אם]\u0006 תאמר שנאמרו הדברים \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003ר' ישמעאל\u0004 — \u0003האמר\u0004 \u0005[הרי אמר]\u0006 ר' ישמעאל כי \u0003לא מבטל\u0004 ה\u0003עור\u0004 את הבשר, ולכך הנושא את העור נטמא בטומאת נבילה. \u0003ואי אליבא\u0004 \u0005[ואם לשיטת]\u0006 \u0003ר' עקיבא\u0004 — לא נצרך רב הונא להשמיענו שהעור מבטל את הבשר, כי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, כי \u0003האמר\u0004 \u0005[הרי אמר]\u0006 ר' עקיבא ש\u0003מבטל\u0004 ה\u0003עור\u0004 את הבשר, ולכן אין הנושא נטמא.","ומשיבים: \u0003לעולם\u0004 אמר רב הונא את דבריו \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003ר' ישמעאל\u0004 הסבור שאין העור מבטל את הבשר, \u0003ו\u0004אולם \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' ישמעאל\u0004 ש\u0003לא מבטל\u0004 ה\u0003עור\u0004 את הבשר — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים רק בזמן \u0003שפלטתו חיה\u0004 לחתיכות בשר אלה שעל העור מן הבהמה (כגון שנשכה כלב ותלש עור עם חתיכות בשר עליו), \u0003אבל\u0004 בזמן ש\u0003פלטתו סכין\u0004 בידי אדם — \u0003בטיל\u0004 \u0005[בטל]\u0006 הבשר אצל העור.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 כי אין זה ההסבר בדברי רב הונא, שהרי שנינו במשנתנו ש\u0003ר' יהודה אומר\u0004 כי \u0003האלל המכונס, אם יש\u0004 בו \u0003כזית במקום אחד\u0004 — \u0003חייבין עליו. ו\u0004בהסבר דברי ר' יהודה הללו \u0003אמר רב הונא: והוא\u0004 (ובלבד) \u0003שכנסו\u0004 האדם את האלל לאחר הפשט העור, שבכך גילה דעתו כי מלכתחילה לא ביטל את האלל. ומתוך שהעמיד רב הונא את דברי ר' יהודה דווקא באופן זה שכנסו אדם, מוכח מכאן שמדובר בזמן שפלטתו הסכין בשנים ושלושה מקומות, ועמד האדם וכינסם. ומכאן יש ללמוד כי אם ביטל אותם האדם במכוון — הריהם בטלים, אבל העור אינו מבטלם. שהרי אם ביטלם העור שוב אין חוזרים לכלל טומאת נבילה.","ויש להקשות: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שחתיכות ש\u0003פלטתו סכין ל\u0004שיטת \u0003ר' ישמעאל נמי\u0004 \u0005[גם כן]\u0006 \u0003לא בטיל\u0004 \u0005[בטל]\u0006 אצל העור — מובן הדבר, שכן \u0003רב הונא\u0004 ש\u0003אמר\u0004 כי לפי ר' יהודה כינוס הדברים בידי אדם מחשיב את הדבר, ומטמא, הרי זה \u0003כ\u0004דעת \u0003ר' ישמעאל\u0004 הסבור שפליטת סכין אינה מבטלת.","\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 ש\u0003פלטתו סכין לר' ישמעאל בטיל\u0004 \u0005[בטל],\u0006 וגם כינוס בידי אדם אינו מחשיב את הדבר לכלל טומאה, דברי \u0003רב הונא\u0004 ש\u0003אמר\u0004 כי לשיטת ר' יהודה מועיל כינוס גם בזמן שפלטתו סכין, ואין העור מבטלם, \u0003כ\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 הם נאמרו?","\u0003אלא\u0004 יש לחזור מההסבר שנאמר מקודם בשיטת ר' ישמעאל ולומר כי \u0003לעולם\u0004 גם בזמן ש\u0003פלטתו סכין ל\u0004שיטת \u0003ר' ישמעאל לא בטיל\u0004 \u0005[לא בטל],\u0006 \u0003ו\u0004אילו \u0003רב הונא\u0004 האומר שהעור מבטל את שני חצאי זיתי בשר הנבילה שעליו, \u0003אמר\u0004 את דבריו \u0003כ\u0004שיטת \u0003ר' עקיבא.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך היא שיטת ר' עקיבא, ולא נצרך רב הונא להשמיע את דבריו!","ומשיבים: נצרך רב הונא לומר את דבריו, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר,\u0006 היה מקום לומר\u0005]:\u0006 \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' עקיבא\u0004 את שיטתו שהעור מבטל את חתיכות הבשר שעליו, \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים רק בזמן ש\u0003פלטתו סכין, אבל\u0004 בזמן ש\u0003פלטתו חיה\u0004 — \u0003לא בטיל\u0004 \u0005[אינו בטל],\u0006 לכך","\u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 ש\u0003טעמא\u0004 \u0005[טעם]\u0006 שיטת \u0003ר' עקיבא\u0004 הוא \u0003מפני שהעור מבטלן,\u0004 ומשום כך, \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם \u0003פלט חיה, ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם \u0003פלט סכין, כדקתני סיפא\u0004 \u0005[כמו ששנה בסופה]\u0006 של אותה ברייתא: \u0003מפני מה ר' עקיבא מטהר בעור? מפני שהעור מבטלן.\u0004","\u0003אלו\u0004 הם בעלי החיים \u0003ש\u0004דין \u0003עורותיהן כ\u0004דין \u0003בשרן\u0004 לענין הטומאה: \u0003עור\u0004 של \u0003האדם\u0004 המת, הריהו כבשר המת, ומטמא. \u0003ו\u0004כן \u0003עור חזיר של ישוב\u0004 (חזיר בית) שהוא רך ונאכל לגוים, הריהו נחשב כבשר החזיר, ומטמא טומאת נבילות כבשר החזיר. \u0003ר' יהודה אומר\u0004 כי \u0003אף עור חזיר הבר\u0004 נחשב כבשרו, ומטמא טומאת נבילות.","\u0003ועור חטרת\u0004 (חטוטרת, דבשת) \u0003של\u0004 ה\u0003גמל הרכה,\u0004 שעדיין לא התקשה, הריהו נחשב כבשר, ומטמא. \u0003ו\u0004כן \u0003עור הראש של עגל הרך, ועור הפרסות, ועור בית הבושת\u0004 (רחם) של הנקיבה, \u0003ועור השליל\u0004 (העובר שבמעי אמו), הנמצא בה בשעת שחיטה, \u0003ועור של תחת האליה\u0004 (זנב) הכבשה, \u0003ועור\u0004 של ארבעת השרצים הבאים (שמכלל שמונת השרצים המטמאים במותם, האמורים בתורה \"החולד והעכבר והצב למינהו. והאנקה והכח והלטאה והחומט והתנשמת\". ויקרא יא, כט—ל), שעורם רך: \u0003האנקה, והכח, והלטאה, והחומט.\u0004 שבכל אלה העורות שנמנו דינם כדין הבשר, ומטמאים. \u0003ר' יהודה אומר\u0004 כי עור \u0003הלטאה\u0004 דינו \u0003כ\u0004דין עור ה\u0003חולדה\u0004 (ה\"חולד\" האמור בתורה), שאינם נחשבים כבשר לענין טומאה.","\u0003וכולן,\u0004 כל העורות האלה שצויינו למעלה כמי שדינם כבשר, בזמן \u0003שעבדן\u0004 כדרך שמעבדים עור, \u0003או ש\u0004שטחם על הקרקע ו\u0003הילך בהן\u0004 (עליהם) שיעור זמן שיש בו \u0003כדי עבודה\u0004 (עיבוד העור) — הריהם \u0003טהורין,\u0004 שכן בכך יצאו מכלל בשר ונהיו לעורות גמורים. \u0003חוץ מעור האדם\u0004 שנשאר טמא אף באופנים הללו. \u0003ר' יוחנן בן נורי אומר\u0004 כי עורותיהם של כל \u0003שמונה\u0004 ה\u0003שרצים\u0004 הנזכרים בתורה, \u0003יש להן\u0004 דין \u0003עורות,\u0004 ולא דין בשר, ואין הם מטמאים.","שנינו בתחילת משנתנו כי עור אדם נחשב כבשרו לענין הטומאה, ועל כך \u0003אמר עולא: דבר\u0004 (מדין) \u0003תורה עור\u0004 של \u0003אדם\u0004 הריהו \u0003טהור, ומה טעם אמרו\u0004 חכמים שהוא \u0003טמא? גזירה\u0004 היא \u0003שמא יעשה אדם\u0004 מ\u0003עורות אביו ואמו\u0004 שמתו \u0003שטיחין,\u0004 ולכן חכמים גזרו עליהם טומאה כדי שלא יעשו כן.","\u0003ואיכא דמתני לה\u0004 \u0005[ויש ששונים אותה\u0006 הלכה של עולא\u0005]\u0006 לא על תחילת משנתנו אלא \u0003אסיפא\u0004 \u0005[על הסוף]\u0006 ששנינו בה: \u0003ו\u0004כל העורות \u0003כולן\u0004 שנמנו במשנתנו כמי שיש להם דין בשר, בזמן \u0003שעיבדן או ש\u0004שטחם על הקרקע ו\u0003הילך בהן\u0004 שיעור זמן \u0003כדי עבודה\u0004 — \u0003טהורין, חוץ מעור אדם,\u0004 שטמא אף באופנים אלה. ועל כך \u0003אמר עולא:\u0004 \u0003דבר תורה עור אדם שעבדו\u0004 — \u0003טהור, ומה טעם אמרו\u0004 חכמים שהוא \u0003טמא? גזירה שמא יעשה אדם עורות אביו ואמו שטיחין.\u0004","ומעירים: \u0003מאן דמתני לה ארישא\u0004 \u0005[מי ששונה אותה\u0006 הלכה \u0005על התחלת\u0006 משנתנו, שעניינה עור שלא עובד\u0005],\u0006 ולמדנו איפוא שגם עור דק טומאתו מדברי חכמים, ולא מדין תורה — \u0003כל שכן\u0004 שהוא שונה אותה הלכה \u0003אסיפא\u0004 \u0005[על סוף\u0006 משנתנו בעור שעובד\u0005],\u0006 שטומאתו של עור האדם מדברי חכמים ולא מדין תורה. \u0003ו\u0004אולם \u0003מאן דמתני אסיפא\u0004 \u0005[מי ששונה אותה על סוף\u0006 משנתנו\u0005],\u0006 נדייק מדבריו: דווקא עור אדם שעובד מקבל טומאה רק מדברי חכמים, \u0003אבל ארישא\u0004 \u0005[בראשה\u0006 של המשנה\u0005]\u0006 העוסקת בעור שלא עובד — הריהו טמא ב\u0003טומאה דאורייתא\u0004 \u0005[שמן התורה].\u0006","\u0003ו\u0004עוד שנינו במשנתנו שנחלקו תנאים בדינו של עור חזיר, שלדעת חכמים אין עור חזיר נחשב כבשר לענין הטומאה אלא \u0003עור חזיר\u0004 של ישוב, ואילו לדעת ר' יהודה אף עור חזיר הבר נחשב כבשר. ומבררים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 ומסבירים: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים \u0005סבור]\u0006 כי \u0003האי\u0004 \u0005[זה,\u0006 עור חזיר הבר\u0005]\u0006 הוא \u0003אשון\u0004 \u0005[קשה],\u0006 ולכן אין הוא נחשב כבשר, \u0003ו\u0004אילו \u0003האי\u0004 \u0005[זה,\u0006 עור של ישוב\u0005]\u0006 הוא \u0003רכיך\u0004 \u0005[רך],\u0006 ולכן הוא נחשב כבשר. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יהודה, \u0005סבור]\u0006 כי \u0003האי נמי רכיך\u0004 \u0005[זה,\u0006 עור חזיר הבר, \u0005גם כן רך],\u0006 ולכן הוא נחשב כבשר.","עוד שנינו במשנתנו כי \u0003עור חטרת\u0004 (חטוטרת, דבשת) \u0003של גמל הרכה\u0004 \u0003נחשב כבשר לענין הטומאה. ושואלים:\u0004 \u0003וכמה,\u0004 מה משך הזמן שנקרא הוא \u0003גמל הרכה,\u0004 ודין עורו כדין בשרו? \u0003אמר עולא, אמר ר' יהושע בן לוי: כל זמן שלא טענה\u0004 משא.","ובבירור דברי ר' יהושע בן לוי הללו \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 אם \u0003הגיע זמנה\u0004 של הגמל \u0003לטעון ו\u0004אולם עדיין \u0003לא טענה\u0004 בפועל, \u0003מהו\u0004 דין עורו של הגמל? ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אביי\u0004 בבירור דברי ר' יהושע בן לוי: גמל זה שעדיין \u0003לא הגיע זמנה לטעון, ו\u0004אולם \u0003טענה, מהו\u0004 דין עורו? ואומרים כי שאלות אלה לא נפתרו ו\u0003תיקו\u0004 \u0005[תעמודנה]\u0006 במקומן.","ועוד נמסר בענין זה של גמל הרכה, כי \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ריש לקיש וקמיבעיא ליה\u0004 \u0005[ונשאלה לו]:\u0006 \u0003כמה גמל הרכה? אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ישמעאל בר אבא: הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יהושע בן לוי: כל זמן שלא טענה. אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003תיב לקבלי\u0004 \u0005[שב למולי].\u0006 כלומר, אמרת לי דבר חשוב, ואני מכבד אותך שתשב לידי.","וכיוצא בזה נמסר כי בזמן אחר \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' זירא וקמיבעיא ליה\u0004 \u0005[ונשאלה לו]\u0006 השאלה: \u0003כמה גמל הרכה? אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבין בר חיננא: הכי\u0004 \u0005[כך]\u0006 \u0003אמר עולא, אמר ר' יהושע בן לוי: כל זמן שלא טענה. הוה קתני לה\u0004 \u0005[היה\u0006 רבין \u0005בר חיננא\u0006 \u0005שונה אותה,\u0006 את ההלכה הזו שוב לפני ר' זירא\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא: פעם \u0003חדא הויא\u0004 \u0005[אחת היה]\u0006 \u0003לך,\u0004 שכבר \u0003אמרת\u0004 אותה כבר, ואין צורך לחזור.","ומעירים: \u0003תא חזי\u0004 \u0005[בוא וראה]\u0006 מתוך השוואת המעשים \u0003מה בין תקיפי ארעא דישראל\u0004 \u0005[תקיפי ארץ ישראל]\u0006 כריש לקיש שהיה מפורסם בחומרתו ותקיפותו \u0003לחסידי\u0004 \u0005[לחסידי]\u0006 ארץ \u0003בבל\u0004 כר' זירא. שריש לקיש כיבד את זה שהשמיע דבר תורה, ואילו ר' זירא השיב בחריפות לאותו חכם שהשמיעו דבר תורה.","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003עור הראש\u0004 של עגל רך נחשב כבשר לענין הטומאה. \u0003ו\u0004מבררים: \u0003כמה\u0004 משך הזמן שהוא נקרא \u0003עגל הרך? עולא אמר: בן שנתו. ר' יוחנן אמר: כל זמן שיונק. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמי בית המדרש\u0005]:\u0006 \u0003היכי קאמר\u0004 \u0005[איך אמר]\u0006 \u0003עולא\u0004 בדיוק את דבריו, האם כוונתו לעגל שהוא \u0003בן שנתו והוא\u0004 גם עגל \u0003שיונק.\u0004"],["\u0003ו\u0004כנגד דעה זו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן\u0004 לעולא כי \u0003כל זמן ש\u0004העגל \u0003יונק\u0004 חלב הריהו נחשב כ\"עגל הרך\", גם אם העגל הוא בן למעלה משנה. ונמצא לפי הסבר זה של הבעיה כי עולא מצריך שיתקיימו בו שני תנאים, ולדעת ר' יוחנן די בכך שהעגל יונק.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \"עגל רך\" לדעת \u0003עולא,\u0004 הוא זה שהוא \u0003בן שנתו קאמר\u0004 \u0005[הוא\u0006 עולא \u0005אומר],\u0006 \u0003בין\u0004 שעגל זה \u0003יונק ובין שאינו יונק. ו\u0004כנגד דעה זו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן\u0004 לעולא כי אין \"עגל רך\" אלא זה שהוא גם \u0003בן שנתו והוא\u0004 גם \u0003שיונק.\u0004 ונמצא שלפי הסבר זה ר' יוחנן הוא שמצריך שיתקיימו בו שני תנאים, ואילו לדעת עולא די בכך שהוא בן שנתו?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ש\u0003ר' יוחנן אמר\u0004 בלשונו \u0003\"כל זמן שיונק\", ואם איתא\u0004 \u0005[יש]\u0006 מקום לצד השני, שלדעת ר' יוחנן צריכים אנו גם שיהא העגל בן שנתו, \u0003\"והוא שיונק\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 שהרי תנאי זה של יניקה בא כתוספת לתנאי הראשון שהוא בן שנתו. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא, ונפתרה בכך הבעיה.","ומביאים עוד בדין עור הראש של עגל הרך. \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ריש לקיש מר' יוחנן: עור הראש של עגל הרך\u0004 שעדיין הוא ראוי לאכילה, \u0003מהו שיטמא\u0004 טומאת אוכלים, האם רואים אנו אותו כעור או כבשר? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן בתשובה: \u0003אינו מטמא.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: והרי \u0003לימדתנו רבינו\u0004 את זו ששנינו במשנתנו \u0003אלו שעורותיהן כבשרן ו\u0004בכללם הוא גם \u0003עור הראש של עגל הרך! אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לריש לקיש: \u0003אל תקניטני\u0004 בקושיה זו, כי \u0003בלשון יחיד אני שונה אותה\u0004 את המשנה הזו, שהיא דעת תנא יחיד, ולא \"סתם משנה\" שהלכה כמותה.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדינו של \u0003השוחט את\u0004 קרבן \u0003העולה\u0004 על מנת \u0003להקטיר\u0004 (להקריב) \u0003כזית מעור שתחת האליה\u0004 (הזנב) של הכבש, אם כדי להקטירו \u0003חוץ למקומו\u0004 (חוץ לעזרה) — הרי זה הקרבן \u0003פסול, ו\u0004אולם \u0003אין בו\u0004 עונש \u0003כרת\u0004 לאוכלו. ואם שחט כדי להקטיר עור זה \u0003חוץ לזמנו\u0004 (למחרת) — הרי זה הקרבן הוא \u0003פיגול וחייבין עליו,\u0004 על אכילתו, עונש \u0003כרת.\u0004 מפני שעור זה הוא רך, ודינו כבשר, שמחשבה בו פוסלת. זו היא דעת חכמים.","\u0003אלעזר בן יהודה איש אבלום אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' יעקב, וכן היה ר' שמעון בן יהודה איש כפר עיכום אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון: אחד\u0004 (בין) \u0003עור\u0004 בית \u0003ה\u0004\u0003פרסות, ואחד\u0004 (ובין) \u0003עור הראש של עגל הרך, ואחד\u0004 (ובין) \u0003עור של תחת האליה, וכל שמנו חכמים גבי\u0004 \u0005[אצל]\u0006 \u0003טומאה \"\u0004אלו \u0003שעורותיהן כבשרן\",\u0004 והרי לשון זו באה \u0003להביא\u0004 (לרבות) \u0003עור של בית הבושת\u0004 של הנקיבה, שכל אלה נידונים כבשר.","שאם בשעת עבודת הקרבן חשב להקטירו \u0003חוץ למקומו\u0004 — \u0003פסול, ו\u0004אם אכלו \u0003אין בו כרת.\u0004 ואם חשב להקטירו \u0003חוץ לזמנו,\u0004 למחרת — הרי זה הקרבן \u0003פיגול, וחייבין עליו כרת,\u0004 על אכילתו. משמע ששיטת משנתנו היא כשיטת יחיד (אלעזר בן יהודה), ואילו חכמים באותה ברייתא סבורים שאין העור נחשב כבשר מלבד העור שתחת האליה.","\u0003ו\u0004עוד שנינו במשנתנו כי אף \u0003עור בית הפרסות\u0004 נחשב כבשר לענין הטומאה. ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בית הפרסות\"? רב אמר:\u0004 הכוונה לעור שעל \u0003בית הפרסות ממש,\u0004 החלק שמתחת לקרסולים. \u0003ר' חנינא אמר:\u0004 הכוונה היא לעור ה\u0003רכובה\u0004 (הארכובה, הברך) \u0003הנמכרת עם הראש,\u0004 הוא הפרק התחתון של הרגל, שהקצבים מוכרים עם הפרסה (\"הראש\"), עצם השוק מן הברכים ותחתיהן, שעור זה נחשב כבשר.","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003עור האנקה\u0004 והכח והלטאה והחומט (שהם ארבעה שרצים מן השמונה הכתובים בפרשת השרצים המטמאים), נחשב כבשר לענין טומאה. ומביאים עוד בענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]\u0006 על הכתוב בפרשת השרצים \"וזה לכם הטמא בשרץ השורץ על הארץ החולד והעכבר והצב למינהו. והאנקה והכח והלטאה והחומט והתנשמת. אלה הטמאים לכם בכל השרץ כל הנוגע בהם יטמא עד הערב\" (ויקרא יא, כט—לא): המלה \u0003\"הטמאים\"\u0004 באה \u0003לרבות\u0004 שאף \u0003עורותיהן\u0004 של אלה (אנקה, כח, לטאה, חומט) נחשבים \u0003כבשרן\u0004 לענין הטומאה.","\u0003יכול\u0004 יהא כן הדין \u0003אפילו\u0004 בכל השרצים \u0003כולן,\u0004 שיהיו עורותיהם נחשבים כבשרם? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"אלה\"\u0004 — שרק באלה נוהג דין זה, ולא באחרים.","ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 המלה \u0003\"אלה\" אכולהו כתיבי\u0004 \u0005[על\u0006 שמונת השרצים \u0005כולם\u0006 היא \u0005כתובה]!\u0006 \u0003אמר רב:\u0004 במה שנאמר \u0003\"למינהו\"\u0004 אחר החולד והעכבר והצב \u0003הפסיק הענין,\u0004 ללמדנו שאין הריבוי הנלמד מהמלה \"הטמאים\" מתייחס גם אליהם.","ומקשים: \u0003וליחשוב נמי\u0004 \u0005[ושימנה גם כן]\u0006 את ה\u0003תנשמת\u0004 בכלל אלה שעורותיהם כבשרם, שהרי המלה \"הטמאים\" מתייחסת לכל הנאמר בפסוק שקדם לה, ואף התנשמת נזכרת שם! \u0003אמר רב שמואל בר יצחק:\u0004 אכן \u0003רב\u0004 שדרש כן מן הכתוב, \u0003תנא הוא, ותני\u0004 \u0005[ושנה]\u0006 גם \u0003תנשמת\u0004 בין אלה שעורותיהם כבשרם, שלא כמשנתנו.","ושואלים: \u0003והא תנא דידן לא תני\u0004 \u0005[והרי התנא שלנו לא שנה]\u0006 \u0003תנשמת,\u0004 ומדוע לדעתו התנשמת אין עורה כבשרה?","\u0003אמר רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: תנא דידן סבר לה\u0004 \u0005[התנא שלנו סבור]\u0006 \u0003כ\u0004דעת \u0003ר' יהודה\u0004 הסבור שדין הלטאה (אף שהיא כתובה בתורה באותו פסוק בו נכתבו האנקה והכח והחומט) כדין החולד (הכתוב בפסוק הקודם), שאין עורם כבשרם, וטעמו של ר' יהודה אינו מדרשת הכתוב \"הטמאים\" (כדרך שאמר רב) אלא משום \u0003דאזיל בתר גישתא\u0004 \u0005[שהולך אחר המישוש],\u0006 שבכל אחד מן השרצים הללו על פי מישוש עורם יש לקבוע אם הריהו כבשר. ולכך סבור התנא של משנתנו כי עורם של האנקה והכח והלטאה והחומט מישוש עורם מוכיח שדין עורם כדין בשרם.","\u0003ובגישתא\u0004 \u0005[ובמישוש]\u0006 שעל \u0003הלטאה קמיפלגי\u0004 \u0005[הם חלוקים]\u0006 האם יש בו כדי לקבוע שזה עור קשה (כדעת ר' יהודה) או עור רך (כדעת התנא הראשון).","\u0003ו\u0004עוד שנינו במשנתנו כי כל העורות \u0003כולן\u0004 הנחשבים \u0003כבשר,\u0004 \u0003שעיבדן\u0004 או ששטחם על הקרקע והילך עליהם — יצאו מכלל בשר, והריהם עור לכל דבר, ואינם טמאים. ושואלים: מדיוק הדברים ניתן ללמוד כי דווקא אם \u0003הילך\u0004 עליהם — \u0003אין\u0004 \u0005[כן]\u0006 ואין הם עוד נחשבים בשר. ואולם אם \u0003לא הילך\u0004 עליהם — \u0003לא\u0004 פסקו מלהיחשב כבשר. \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא\u0004 בדינו של \u0003אוזן חמור שטלאה\u0004 (שעשאה לשימוש כטלאי) \u0003לקופתו\u0004 (סל) שבטלה בכך מתורת בשר, והיא בכלל עור, ולכך היא \u0003טהורה\u0004 מטומאת נבילה. הרי שבעצם זה ש\u0003טלאה\u0004 התבטלה מדין בשר. ונאמר כן גם לענייננו, שבעצם זה ששטח את העור על הקרקע לפני ההולכים, או שכרכו סביב רגלו, ביטלו מתורת בשר, ו\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 שעדיין \u0003לא הילך\u0004 בפועל על העור, שיידחה בכך מתורת בשר!","ודוחים: \u0003לא,\u0004 אין זו קושיה. שכן \u0003טלאה\u0004 — הרי זה מעשה שנעשה בעור, ובא המעשה וביטלו מתורת בשר. ואולם פרישת העור על הקרקע או כריכתו על הרגל אינם נחשבים כמעשה המבטל, אלא ההילוך בפועל על העור. ולכך אם \u0003הילך\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 התבטל העור מכלל בשר, \u0003ואם\u0004 \u0003לא הילך\u0004 — \u0003לא\u0004 התבטל מכלל בשר. ובדין זה של ביטול עור מתורת בשר אם הילך עליו, שנינו שצריך שיהלך על העור כדי עיבוד. ומבררים:","\u0003כמה\u0004 זמן הוא \u0003\"כדי עבוד\"? אמר רב הונא\u0004 שכך \u0003אמר ר' ינאי:\u0004 הרי זה משך זמן הליכה של \u0003ארבעת מילין.\u0004","כיון שהוזכר למעלה שיעור הזמן של הילוך ארבעה מילין, מביאים עוד הלכות שיש בהן בענין שיעור זמן זה. \u0003ר' אבהו משום\u0004 \u0005[בשם]\u0006 \u0003ריש לקיש אמר\u0004 כי \u0003לגבל\u0004 (מי שמקצועו ללוש עיסה) המקפיד ללוש את עיסתו בטהרה, והריהו שכיר לבעל הבית, ונצרך הוא למי מקוה כדי לטהר בהם את כליו, מה יעשה? עד מרחק ארבעה מילים — יטריח עצמו ויטביל, ואולם מעבר לכך — אין לו לטרוח, אלא אם כן בעל הבית נותן לו שכר הליכה. \u0003ו\u0004כיוצא בדבר \u0003ל\u0004ענין \u0003תפלה,\u0004 באדם המהלך בדרך \u0003וצריך להתפלל. אם יש בית\u0004 כנסת לפניו במרחק שעד ארבעה מילין — יטריח עצמו, וילך שם, כדי להתפלל בבית הכנסת. ואולם מעבר לכך, לא הצריכוהו לטרוח כל כך.","וכן \u0003ל\u0004ענין \u0003נטילת ידים\u0004 לאכילה, למי שאין לו מים לנטילה. שאם יש מים לפניו בסוף \u0003ארבעת מילין\u0004 — ימתין מלאכול עד שיבוא לשם.","ובענין דברי ר' אבהו הללו \u0003אמר רב נחמן בר יצחק:\u0004"],["לא ר' אבהו הוא שאמר דברים אלה של ריש לקיש, אלא החכם \u0003איבו\u0004 הוא זה ש\u0003אמרה\u0004 להלכה זו של ריש לקיש. \u0003ו\u0004לא שלושה דברים בלבד (גבל, תפילה, ונטילת ידים) הם שנאמרו בהלכה זו, כדרך שאמר ר' אבהו, אלא \u0003ארבעי\u0004 \u0005[ארבעה]\u0006 דברים \u0003אמר בה, וחדא מינייהו\u0004 \u0005[ואחד מהם]\u0006 הנוסף על השלושה שאמר ר' אבהו הוא משך זמן \u0003עבודה\u0004 (עיבוד) העור, שאם הלך על העורות במשך זמן זה, הריהם בטלים מתורת בשר.","ועוד מעירים בהלכה זו שנאמרה מפי ריש לקיש, \u0003אמר ר' יוסי בר' חנינא: לא שנו\u0004 שצריך להמתין מעשיית הדבר, מפני המים ומפני בית הכנסת, הנמצאים במרחק הפחות מארבעה מילים, \u0003אלא\u0004 כאשר הם נמצאים \u0003לפניו\u0004 בדרך הליכתו. \u0003אבל\u0004 כאשר הם נמצאים \u0003לאחריו\u0004 — \u0003אפילו מיל אחד אינו חוזר. רב אחא בר יעקב אמר: ומינה\u0004 \u0005[וממנה]\u0006 מלשון הדברים יש לדייק כי דווקא בשיעור \u0003מיל הוא\u0004 ש\u0003אינו חוזר\u0004 לאחוריו, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003פחות ממיל\u0004 — \u0003חוזר\u0004 לאחוריו.","מתוך שהובאו דברים בדינו של ההולך בדרך לענין טהרתו, מביאים עוד בענין דומה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003ליגיון\u0004 (חיל צבא) \u0003העובר ממקום למקום\u0004 במלחמותיו, \u0003ו\u0004בתוך כך אחד מאנשיו \u0003נכנס לבית\u0004 — \u0003הבית טמא,\u0004 מפני \u0003שאין לך כל ליגיון וליגיון שאין לו כמה קרקפלין\u0004 (קרקפות, עורות ראשיהם של מתים) הנישאים בידי החיילים. \u0003ואל תתמה\u0004 שכן הוא, \u0003שהרי קרקפלו\u0004 (עור ראשו) \u0003של ר' ישמעאל\u0004 כהן גדול, מעשרה הרוגי מלכות, שנפשט מעליו בחייו, הריהו \u0003מונח בראש מלכים.\u0004","עור הבהמה והחיה לאחר שהופשט מהן, אינו מיטמא ומטמא כבשרן. ואולם \u0003המפשיט\u0004 את העור, בין \u0003בבהמה ו\u0004בין \u0003בחיה,\u0004 ועדיין העור עליה בחלקו, בין \u0003ב\u0004עורה של ה\u0003טהורה\u0004 (שנשחטה כדין) והמפשיט הוא אדם טמא, \u0003ו\u0004בין \u0003ב\u0004עורה של ה\u0003טמאה\u0004 (נבילה, הטמאה בטומאת נבילות), והמפשיט הוא טהור. בין \u0003ב\u0004עור בהמה ה\u0003דקה ו\u0004בין \u0003ב\u0004עור בהמה ה\u0003גסה\u0004 — בכל אלה, אם התכוון בהפשטת העור","\u0003ל\u0004שמש לו כ\u0003שטיח\u0004 (להציעו על מיטתו לישיבה, או לפורשו על הקרקע להליכה, או לפורשו על שולחנו לאכילה). כיון שהפושט לצורך זה הריהו פושט באופן הפשוט, שבתחילה הוא חותך את העור לאורך גוף הבהמה והחיה, מראשה ועד זנבה, ואחר כך פושט את העור משני הצדדים — אם יש בעור זה שהופשט שיעור \u0003כדי אחיזה,\u0004 הריהו נחשב עדיין כמחובר לבשר, וכל הנוגע בו נחשב כנוגע בבשר. ולכך אין הוא נטמא (מן האדם הטמא) ואין (עור בהמת הנבילה) מטמאת את הנוגע בו (אם הוא טהור).","\u0003ו\u0004אולם אם התכוון בפשיטת העור \u0003ל\u0004עשות ממנו \u0003חמת\u0004 (נאד, כלי לאיחסון נוזלים), ולצורך זה אין הוא חותך לאורך גוף הבהמה אלא בתחילה הוא חותך כעין עיגול בצד צוואר הבהמה, ופושט את עור הבהמה כלפי מטה — נחשב העור כמחובר לבשר, \u0003עד שיפשיט את החזה.\u0004 ומשעה שפשט את עור החזה, שוב אין עור הבהמה והחיה נחשב כמחובר לבשר.","ואילו זה \u0003המרגיל,\u0004 הפושט את העור גם כן לצורך עשיית חמת ממנו, אלא שבתחילה הוא חותך באיזור הרגלים, ומשם הוא פושט את העור כלפי מעלה — כל עוד לא הופשט העור \u0003כולו\u0004 מן הגוף הריהו נחשב \u0003חבור\u0004 לבשר \u0003ל\u0004ענין ה\u0003טומאה,\u0004 וכל הנוגע בו הריהו נחשב כנוגע בבשר, בין \u0003ליטמא\u0004 על ידי העור (שכל שנגעה טומאה בעור המופשט של בהמה טהורה, נטמא בכך אף בשר הבהמה), \u0003ו\u0004בין \u0003לטמא\u0004 (שעור בהמת נבילה המחובר לבשר, מטמא את הנוגע בו כדרך שהבשר מטמא). ואם הפשיט את העור לחמת, מן הרגלים כלפי מעלה הגוף (\"המרגיל\"), ועדיין לא הפשיט את ה\u0003עור שעל הצואר\u0004 — נחלקו חכמים בדבר, ש\u0003ר' יוחנן בן נורי אומר\u0004 כי מעתה העור \u0003אינו\u0004 נחשב עוד כ\u0003חבור\u0004 לבשר, \u0003ו\u0004אילו \u0003חכמים אומרים\u0004 כי אף בזה נחשב העור \u0003חבור\u0004 לבשר, \u0003עד שיפשיט את\u0004 העור \u0003כולו\u0004 מעל הגוף.","שנינו במשנתנו כי באופן הפשטה הרגיל של עור הבהמה והחיה, נחשב העור המופשט כמחובר לבשר כל עוד שיעורו הוא כדי אחיזה. ושואלים: \u0003מכאן ואילך\u0004 (והלאה), כאשר הפשיט יותר מזה, \u0003מאי\u0004 \u0005[מה]\u0006 דינו של העור?","\u0003אמר רב: טהור\u0004 כל חלק העור \u0003המופשט,\u0004 שהרי שוב אין הוא משמש כ\"יד\" לבשר, ואילו חלק העור שלא הופשט עדיין נחשב כ\"שומר\" לבשר, ולכך הוא מכניס טומאה לבשר ומוציא ממנה טומאה, וכן מצטרף לבשר להשלים לשיעור כביצה, לענין שיקבל הבשר טומאת אוכלים. ו\u0003ר' אסי אמר\u0004 כי \u0003טפח\u0004 מן העור שהופשט \u0003הסמוך לבשר\u0004 הוא \u0003טמא\u0004 כ\"יד\" לבשר, שכן האדם הפושט את העור אוחז בטפח זה לצורך הפשטת העור","\u0003.\u0004 \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי ר' אסי ממה ששנינו בברייתא: \u0003המפשיט כשיעור הזה\u0004 (\"כדי אחיזה\"), \u0003מכאן ואילך,\u0004 לאחר שחתך לאורך הגוף כולו והפשיט כדי אחיזה סביב מקום החתך, \u0003הנוגע ב\u0004חלק העור \u0003ה\u0004\u0003מופשט\u0004 של גוף בהמת הנבילה, הריהו \u0003טהור,\u0004 שאין טומאת הנבילה יוצאת דרך עור זה שנגע בו. ומציעים: \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 המדובר בכל העור המופשט, ו\u0003אפילו בטפח הסמוך לבשר,\u0004 שלא כר' אסי! ודוחים: \u0003לא,\u0004 אין להוכיח מכאן, שכן אפשר לומר כי הכוונה היא לעור המופשט, \u0003לבד מטפח הסמוך לבשר.\u0004","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה כנגד שיטת ר' אסי ממה ששנינו בברייתא בזה שהפשיט יותר מכדי אחיזה, ונגע \u0003בעור שכנגד\u0004 (שעל) \u0003הבשר,\u0004 שטרם הופשט ממנו — הריהו \u0003טמא.\u0004 ונדייק: דווקא זה שנגע \u0003ב\u0004\u0003עור שכנגד הבשר\u0004 — הריהו \u0003טמא\u0004 בכך, \u0003הא\u0004 \u0005[הרי]\u0006 מכאן נלמד כי זה שנגע בעור המופשט \u0003בטפח הסמוך לבשר\u0004 — הריהו \u0003טהור,\u0004 ושלא כר' אסי! ומשיבים: אין זו ראיה, שכן ה\u0003תנא\u0004 לעור הנמצא ב\u0003כל\u0004 ה\u0003טפח הסמוך לבשר\u0004 — \u0003\"עור שכנגד הבשר\" קרי ליה\u0004 \u0005[קורא לו].\u0006","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה שלא כשיטת רב אסי ממה ששנינו בברייתא: \u0003המפשיט בבהמה ובחיה, בטהורה ובטמאה, בדקה ובגסה,\u0004 אם היתה זו הפשטה שנועדה \u0003ל\u0004עשיית \u0003שטיח\u0004 מן העור — העור שהופשט מן הבשר בשיעור \u0003כדי אחיזה\u0004 נחשב כ\"יד\" ומכניס ומוציא טומאה על ידו. \u0003ו\u0004אולם העור שב\u0003טפח הסמוך לבשר\u0004 — הנוגע בו הריהו \u0003טהור,\u0004 ושלא כר' אסי!","ומתרצים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003בטפח\u0004 ה\u0003ראשון\u0004 מהעור שב\"כדי אחיזה\". וכגון שפשט שני טפחים בלבד, שבאופן זה אין אוחזים באותו הטפח הסמוך ל\"כדי אחיזה\", שכן נוח יותר לאחוז בשפת העור ולמשוך. ואולם הדרך הטובה ביותר היא להמשיך לחתוך בסכין, בלא לאחוז בעור המופשט. ובטפח זה אכן מודה ר' אסי שאין הוא נחשב כ\"יד\". ואולם לאחר מכן כשהופשטו כבר שלושה וארבעה טפחים מן העור, אוחזים באותו טפח הסמוך ל\"כדי אחיזה\", לצורך ההפשטה, ולכך הריהו נחשב כ\"יד\".","במשנתנו שנינו דינו של העור, ששיעורו הוא עד \"כדי אחיזה\" כדי שייחשב כמחובר עדיין לבשר, לענין טומאה. ובענין שיעור זה \u0003תנא\u0004 \u0005[שנה\u0006 החכם בברייתא\u0005]:\u0006 \u0003כמה\u0004 הוא שיעור \u0003\"כדי אחיזה\"? טפח.\u0004 ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא אחרת\u0005]\u0006 האומרת כי שיעור \"כדי אחיזה\" הוא","\u0003טפחיים! אמר אביי:\u0004 כוונת הברייתא הראשונה היא ל\u0003טפח כפול\u0004 שמחזיק אותו מקופל בידו, ובכללו הריהו טפחיים. ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה ברייתא גם כן כך,\u0006 כהסברו של אביי\u0005]:\u0006 \u0003כמה \"כדי אחיזה\"? טפח כפול.\u0004","מתוך שנידון עניינו של עור שהופשט בחלקו מגוף הבהמה, מביאים כיוצא בזה. \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]\u0006 בדינה של \u0003טלית\u0004 (בגד) טמאה \u0003שהתחיל בה לקורעה\u0004 (שכאשר תיקרע תצא בכך מכלל \"בגד\", ותיטהר מטומאתה), ש\u0003כיון שנקרע רובה\u0004 של הטלית — \u0003שוב אינו חבור\u0004 בחלקיה השונים, ששוב אינה ראויה לתשמישה הקודם, וסר מעליה בכך שם \"טלית\", \u0003וטהורה.\u0004","\u0003אמר רב נחמן אמר רבה בר אבוה: לא שנו אלא בטלית\u0004 שהיתה \u0003טבולת יום\u0004 (שכבר נטבלה במקוה טהרה באותו יום, ואולם יש להמתין עד הערב שמש, כדי לאכול בה טהרות).","שלענין אכילת טהרות מועילה קריעת הטלית, \u0003דמיגו\u0004 \u0005[שמתוך]\u0006 שרואים ש\u0003לא חס עלה ואטבלה\u0004 \u0005[עליה והטביל אותה],\u0006 על אף שהטבלתה במים מקלקלת אותה, אומרים אנו כי \u0003לא חייס עלה וקרע לה רובה\u0004 \u0005[לא יחוס עליה ויקרע אותה ברובה],\u0006 שהוא האופן הראוי לביטולו של בגד. \u0003אבל טלית שאינה טבולת יום\u0004 — \u0003לא\u0004 נטהרת בקריעת רובה, אלא רק בקריעת כולה. וטעם הדבר: \u0003גזרה דלמא לא אתי למיקרעה\u0004 \u0005[שמא לא יבוא לקרוע את]\u0006 \u0003רובה,\u0004 אלא רק מחציתה.","\u0003אמר רבה: שתי תשובות\u0004 (דחיות) יש \u0003בדבר\u0004 זה, על האופן בו העמיד רבה בר אבוה את דברי המשנה: \u0003חדא\u0004 \u0005[האחת],\u0006 אין מקום לומר שמדובר במשנה בטלית טבולת יום, שנטהרת בקריעה, כיון שיש לגזור עליה טומאה אף באופן זה, מפני החשש \u0003שמא יאמרו\u0004 האנשים הרואים שמשתמשים בטלית זו לטהרות, כי \u0003טבילה בת יומא\u0004 \u0005[יומה,\u0006 בטרם הערב שמש\u0005]\u0006 \u0003עולה\u0004 (נחשבת) כטבילה לענין שיוכל להשתמש בה עוד באותו יום, קודם הערב שמש. \u0003ועוד\u0004 טעם שאין לומר כהסברו זה של רבה בר אבוה, שגזרו חכמים בטלית שאינה טבולת יום על קריעת רובה, שלא תטהר משום החשש שגיבואו לקרוע רק מחציתה,"],["שכן מעתה, אמור כן אף ב\u0003עולת העוף ל\u0004שיטת \u0003ר' אלעזר בר' שמעון,\u0004 שאמר כי מולקים את רוב שני הסימנים (קנה וושט), ואין מולקים את כולם, \u0003ליגזר דילמא לא אתי למעבד\u0004 \u0005[שיגזור שמא לא יבוא לעשות]\u0006 \u0003רוב שנים\u0004 אלא מחציתם בלבד!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף\u0004 לרבה בדחיית שתי קושיותיו: \u0003דקא אמרת\u0004 \u0005[זה שאתה אומר]\u0006 שאין מקום להתיר טלית שנקרעה ברובה לטהרות, ומשום \u0003גזירה שמא יאמרו\u0004 הרואים כי \u0003טבילה בת יומא\u0004 \u0005[יומה]\u0006 הריהי \u0003עולה\u0004 (נחשבת) — אין מקום לחשש זה, שהרי \u0003קרעה\u0004 של הטלית \u0003מוכיח עליה\u0004 שהיא טהורה משום הקריעה ולא משום שאין צורך בהערב שמש לטהרות.","\u0003ודקא אמרת\u0004 \u0005[וזה שאתה אומר]\u0006 כי מעתה אף ב\u0003עולת העוף ל\u0004שיטת \u0003ר' אלעזר בר' שמעון ליגזר\u0004 \u0005[שיגזרו]\u0006 מפני החשש שיבואו למליקה של מחצית הסימנים ולא רובם — אין מקום לחשש זה, שהרי המולקים הם הכהנים, וה\u0003כהנים זריזים הן\u0004 והם מדקדקים בדבר ואינם באים לידי טעות.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה שלא כשיטת רבה בר אבוה, שכן שנינו במשנתנו כי \u0003המפשיט\u0004 את העור \u0003בבהמה ובחיה, בטמאה ובטהורה, בדקה ובגסה, ל\u0004צורך עשייתו \u0003שטיח\u0004 — נחשב העור המופשט כבשר עד שהפשיט מן הגוף עור שיש בו \u0003כדי אחיזה.\u0004","ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם היה העור בשיעור שיש בו \u0003יתר מכדי אחיזה\u0004 — הוא \u0003טהור,\u0004 ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003ליגזר\u0004 \u0005[שיגזרו]\u0006 חכמים אף על עור שיש בו יתר מכדי אחיזה שיטמא מפני החשש \u0003דילמא לא אתי למעבד\u0004 \u0005[שמא לא יבוא\u0006 זה שרוצה לפשוט עור בשיעור יותר מכדי אחיזה \u0005לעשות,\u0006 לפשוט, עור בפועל\u0005]\u0006 \u0003אלא כדי אחיזה, וקא נגע\u0004 \u0005[והרי הוא נוגע]\u0006 \u0003בטומאה, וקא מטהרינן ליה\u0004 \u0005[ואנו מטהרים אותו]\u0006 שלא כדין!","ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003בטומאה דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003הכי נמי\u0004 \u0005[כך הוא גם כן]\u0006 שהיה מקום לגזירה זו, ואולם \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003בטומאה דרבנן\u0004 \u0005[מדברי סופרים],\u0006 ובטומאה כזו, אין גוזרים טומאה על עור שיש בו יותר מכדי אחיזה בשל עור שיש בו כדי אחיזה.","ושואלים על הסבר זה: \u0003תינח\u0004 \u0005[נוח,\u0006 מובן הדבר\u0005]\u0006 במה ששנינו במשנתנו \"המפשיט בטהורה\" שהכוונה היא לאדם \u0003טמא\u0004 מדברי חכמים, והוא מפשיט עור \u0003ב\u0004בהמה \u0003טהורה,\u0004 והרי זו טומאה מדברי חכמים, ובכך אין גוזרים גזירה זו. ואולם אדם \u0003טהור\u0004 המפשיט עור \u0003ב\u0004בהמה \u0003טמאה,\u0004 שכל בהמה טמאה שנשחטה הריהי נבילה שטומאתה \u0003טומאה דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא,\u0004 ונגזור בכגון זה! ומשיבים: מה שנאמר במשנה \"בטמאה\" הכוונה היא לבהמה טהורה שנשחטה כדין, ואולם \u0003ב\u0004בדיקתה נמצא שהיא \u0003טרפה,\u0004 וטומאתה של זו היא מדברי חכמים בלבד.","ושואלים: והאם בהמה טהורה \u0003טרפה בת טמויי\u0004 \u0005[טומאה]\u0006 \u0003היא?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003כדאבוה\u0004 \u0005[כ\u0006שיטת \u0005אביו]\u0006 של \u0003שמואל,\u0004 שכן \u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל: טרפה ששחטה\u0004 — \u0003מטמאה ב\u0004בהמות ה\u0003מוקדשין,\u0004 שאם היתה זו מן הקדשים, נוהגת בה טומאה מדברי חכמים, ואף משנתנו עוסקת בבהמת קדשים שנטרפה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה שלא כדברי רבה בר אבוה ממה ששנינו ש\u0003ר' דוסתאי בן יהודה משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון אומר\u0004 כי \u0003המפשיט\u0004 את העור \u0003בשרצים\u0004 — העור נחשב כ\u0003חבור\u0004 לגוף השרץ, שמשמש לו כ\"יד\", ויוצאת טומאת השרץ על ידו לנוגע בעור זה, \u0003עד שיפשיט את\u0004 העור \u0003כולו\u0004 מעל השרץ.","ונדייק מכאן: דין זה נוהג רק בעורם של שרצים, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בגמל\u0004 או בשאר בהמה טמאה — העור המופשט מעליו שיש בו שיעור יותר מכדי אחיזה \u0003אינו\u0004 נחשב \u0003חבור,\u0004 והריהו טהור. ואילו עור שהופשט בכדי אחיזה, הריהו טמא. הרי איפוא שאין אנו גוזרים במפשיט יותר מכדי אחיזה מפני המפשיט בכדי אחיזה, ושלא כדברי רבה בר אבוה!","ודוחים: \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 כדרך שדייקת \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בגמל אינו חבור,\u0004 \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך בדיוק הדברים: דווקא בעור של שרצים נחשב העור כמחובר לבשר עד שיפשיט את העור כולו. אבל בגמל, ובשאר בהמה טמאה, כאשר מפשיט את העור לחמת ובאופן שמפשיט מלמטה כלפי מעלה (\"מרגיל\"), אם מפשיט עד הצוואר, אף שנשאר עדיין \u0003בעור שעל הצואר\u0004 — \u0003אינו חבור, ו\u0004כשיטת \u0003ר' יוחנן בן נורי היא,\u0004 שסבור כי משעה שהופשט עור בית החזה, הרי זה נחשב \u0003כאינו מחובר לבשר, אף שעדיין לא פשט את עור הצוואר.\u0004","למעלה הובאו דברי המשנה במסכת כלים בדין טלית טמאה שנקרעה ברובה שהיא טמאה. ומביאים עוד דברים המסייגים את דברי המשנה. שכן \u0003אמר רב הונא משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בר' יוסי: לא שנו\u0004 שהטלית הטמאה הריהי טהורה לאחר שנקרעה ברובה, \u0003אלא\u0004 בזמן \u0003שלא שייר בה\u0004 בטלית חלק שלם שיש בו שיעור \u0003כדי מעפורת\u0004 (חלוק עליון), \u0003אבל\u0004 אם \u0003שייר בה\u0004 בטלית חלק שלם שיש בו שיעור \u0003כדי מעפורת\u0004 — הרי זה \u0003חבור.\u0004","ועוד דברים המסייגים את דברי המשנה \u0003אמר ריש לקיש: לא שנו\u0004 שדבר טמא הנקרע ברובו שנטהר בכך \u0003אלא\u0004 ב\u0003טלית, אבל עור\u0004 טמא שנקרע, אף שנקרע ברובו — אין הוא נטהר בכך, כיון שהוא \u0003חלים\u0004 \u0005[מתרפא,\u0006 ושב ומתחבר\u0005].\u0006 \u0003ו\u0004אילו \u0003ר' יוחנן אמר: אפילו עור נמי\u0004 \u0005[גם כן]\u0006 כיון שנקרע ברובו הריהו נטהר בכך, כיון שהעור שנקרע \u0003לא חלים\u0004 \u0005[אינו מתרפא].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו: \u0003עור\u0004 שהוא \u0003טמא\u0004 בטומאת \u0003מדרס,\u0004 אם \u0003חישב עליו\u0004 בעליו \u0003ל\u0004חותכו כדי שיעשה ממנו \u0003רצועות וסנדלים, כיון שנתן בו איזמל\u0004 להתחיל לחותכו — הרי הוא \u0003טהור\u0004 מטומאתו, אלו \u0003דברי ר' יהודה. וחכמים אומרים:\u0004 אין העור נטהר מטומאתו בנעיצת האיזמל בלבד, אלא רק \u0003עד שימעיטנו\u0004 את העור השלם לכדי פחות \u0003מחמשה טפחים.\u0004 ונדייק מכאן: \u0003כי ממעיט ליה מיהא\u0004 \u0005[כאשר ממעט אותו\u0006 את העור השלם משיעור חמישה טפחים \u0005על כל פנים]\u0006 \u0003טהור\u0004 הוא לכל הדעות, ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003לימא חלים\u0004 \u0005[אמור\u0006 שהוא אחר כך \u0005מתרפא\u0006 ומתחבר\u0005]\u0006 כשיטתך!","השיב ריש לקיש לר' יוחנן: \u0003כי קאמרי דחלים\u0004 \u0005[כאשר אמרתי ש\u0006העור שנחתך \u0005מתרפא]\u0006 הרי זה רק \u0003היכא דקא צרי ליה להדיא\u0004 \u0005[במקום שהוא חותך אותו\u0006 את העור, \u0005למישרין,\u0006 בקו ישר לאורכו או לרוחבו\u0005],\u0006 ואילו \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 במשנה זו \u0005במה אנו עוסקים]?\u0006 \u0003במקצע\u0004 (מחתך) \u0003ובא לו דרך סביבותיו\u0004 (בקו מעגלי), ועור שנחתך באופן שכזה אכן אינו יכול להתרפא.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' ירמיה\u0004 על שיטת ריש לקיש ממה ששנינו במשנתנו כי \u0003המפשיט בבהמה ובחיה, בטהורה ובטמאה, בדקה ובגסה, לשטיח\u0004 — נחשב העור כחיבור לבשר עד שיש בו שיעור \u0003כדי אחיזה.\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם יש בעור שנפשט שיעור \u0003יתר מכדי אחיזה\u0004 — הריהו \u0003טהור, ו\u0004יש לשאול לשיטת ריש לקיש: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003לימא חלים\u0004 \u0005[אמור\u0006 שהוא אחר כך \u0005מתרפא\u0006 ומתחבר\u0005]!\u0006 \u0003תרגמה\u0004 \u0005[תרגם,\u0006 פירש, \u0005אותה\u0006 את משנתנו\u0005]\u0006 \u0003ר' אבין\u0004 שמדובר בה באופן הפשטה ש\u0003ראשון ראשון\u0004 (חלק אחר חלק) מן העור שנפשט \u0003עושה ניפול,\u0004 פורש לגמרי מן הבשר, ואין דרך שיחזור ויתחבר עם החלקים האחרים שנפשטו. ועוד","\u0003מתיב\u0004 \u0005[מקשה]\u0006 ע ל שיטת ריש לקיש \u0003רב יוסף\u0004 ממה ששנינו במשנתנו כי ה\u0003עור שעל הצואר\u0004 הרופף בחיבורו לגוף, \u0003ר' יוחנן בן נורי אומר\u0004 ש\u0003אינו\u0004 נחשב \u0003חבור\u0004 לבשר, והריהו טהור. ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003הא חלים וקאי\u0004 \u0005[הרי\u0006 הוא \u0005מתרפא ועומד],\u0006 בהיותו במקומו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף בתשובה לקושייתו על ריש לקיש: עד שמקשה אתה על ריש לקיש מדברי ר' יוחנן בן נורי שבמשנתנו, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 משנתנו\u0005]:\u0006 \u0003וחכמים אומרים:\u0004 אין זה נחשב \u0003חבור,\u0004 ומעתה הרי זו ראיה לשיטת ריש לקיש!","\u0003אלא אמר אביי:\u0004 אין מחלוקתם של ר' יוחנן בן נורי וחכמים עוסקת בענין רפואתו של עור הצוואר, אלא \u0003ב\u0004דינו של הדבר המוגדר \u0003כ\u0004\u0003שומר\"\u0004 (כעור זה של הצואר) ואולם הריהו \u0003העשוי לנתק מאליו קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003הוי\u0004 \u0005[הריהו\u0006 נחשב\u0005]\u0006 כ\u0003\"שומר\",\u0004 אף על פי שעשוי להינתק. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יוחנן בן נורי, \u0005סבור]:\u0006 \u0003לא הוי\u0004 \u0005[אין הוא\u0006 נחשב\u0005]\u0006 ל\u0003\"שומר\".\u0004","ועוד \u0003מתיב\u0004 \u0005[מקשה]\u0006 ע ל שיטת ריש לקיש \u0003ר' ירמיה\u0004 ממה ששנינו: \u0003תנור שנטמא, כיצד מטהרין אותו\u0004 מטומאתו? \u0003חולקו,\u0004 כלומר, חותך אותו את חרס התנור \u0003לשלשה, וגורר\u0004 (מסיר) \u0003את הטפילה\u0004 (שכבת הטיט),"],["\u0003עד שיהא בארץ,\u0004 כלומר, עד שהוא מגיע בגירור הטפילה עד הקרקע, ובכך אין התנור נחשב עוד ככלי, והריהו טהור. \u0003ר' מאיר אומר: אינו צריך לא לגרור את הטפילה\u0004 כלל, \u0003ו\u0004בוודאי \u0003לא עד שיהא בארץ\u0004 כדברי חכמים. \u0003אלא\u0004 די בכך שהוא \u0003ממעטו\u0004 (חותך את התנור, ומקטין אותו בכך ממידותיו) \u0003מבפנים\u0004 לטפילה, עד שיהא שיעורו של חלק התנור השלם פחות \u0003מארבעה טפחים.\u0004","ונדייק: לדעת ר' מאיר אמנם כאשר שבר רק מקצת התנור — אין התנור נטהר בכך, ואולם \u0003כי ממעט לה\u0004 \u0005[כאשר ממעט אותו]\u0006 לפחות \u0003מארבעה\u0004 טפחים — \u0003מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003טהור\u0004 הוא, ויש לשאול לשיטת ריש לקיש: \u0003אמאי\u0004 \u0005[מדוע]\u0006 טהור תנור שכזה, \u0003לימא: הא חלים וקאי\u0004 \u0005[אמור: הרי לרפואה,\u0006 לחיבור \u0005עומד]\u0006 תנור זה, ולשיטת ריש לקיש הריהו נחשב כמחובר, ואינו טהור!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לר' ירמיה: \u0003ו\u0004עד שאתה מקשה מדברי ר' מאיר על שיטת ריש לקיש, \u0003אימא\u0004 \u0005[אמור]\u0006 כהוכחה \u0003מ\u0004דבריהם של \u0003רבנן\u0004 \u0005[חכמים\u0006 החלוקים על ר' מאיר\u0005]\u0006 שאמרו כי טהרת התנור היא רק כשהוא \u0003גורר את הטפילה עד שיהא בארץ.\u0004 הרי שסבורים חכמים כי כל גרירה שאינה גמורה כמו זו, נחשבת כדבר העומד להתחבר, שדינו כמחובר, וכשיטת ריש לקיש.","\u0003אלא אמר רבא:\u0004 אחר שראינו כי אין שיטת ריש לקיש נסתרת מדברי המשנה (שהרי דעת חכמים הריהי כמותו), נוסיף כי שיטת ריש לקיש יכולה להיות אף כדעת ר' מאיר, שכן \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 התנא במשנה זו: \u0003תנור ש\u0004כבר \u0003נטמא כיצד מטהרין אותו?\u0004 ל\u0003דברי הכל\u0004 (ואף לדעת ר' מאיר) יש ל\u0003חולקו לשלשה\u0004 חלקים, \u0003ו\u0004כן צריך שיהא \u0003גורר את הטפילה עד שיהא בארץ. ו\u0004כל","\u0003הרוצה שלא יבא תנורו לידי טומאה, כיצד הוא עושה\u0004 שלא ייקרא שם \"תנור\" על הדבר, ולא ייחשב ככלי הנטמא? מתחילה יש ל\u0003חולקו לשלשה\u0004 חלקים \u0003ו\u0004כן צריך שיהא \u0003גורר את הטפילה עד שיהא בארץ.\u0004 וכדרך שנוהגים בתנור שכבר נטמא. ואילו \u0003ר' מאיר אומר\u0004 כי בתנור שטרם נטמא \u0003אינו צריך לא לגרור את הטפילה ולא עד שיהא בארץ, אלא\u0004 די בכך שיהא \u0003ממעטו מבפנים\u0004 עד שיהא שיעורו של חלק התנור השלם פחות \u0003מארבעה טפחים.\u0004 ונמצא מעתה כי יכול ריש לקיש לסבור אף כדעת ר' מאיר.","ומוסיפים ודנים בדברי המשנה במסכת כלים שהובאה למעלה. \u0003אמר מר\u0004 \u0005[החכם\u0006 במשנה\u0005]\u0006 בדינו של תנור שנטמא שיש ל\u0003חולקו\u0004 (דווקא) \u0003לשלשה\u0004 חלקים, ובכך הריהו נטהר. שדעת חכמים היא שהתנור נטהר בשבירתו רק כאשר אין רוב תנור בשברים. וכאשר נחלק התנור לשלושה חלקים, אין חלק אחד שהוא רוב התנור. ואולם אם ייחלק התנור לשנים, נמצא חלק אחד שיש בו רוב תנור.","\u0003ו\u0004על כך \u0003רמינהו\u0004 \u0005[משליכים,\u0006 מראים סתירה\u0005]\u0006 לדין זה ממה ששנינו במשנה אחרת במסכת כלים: \u0003תנור\u0004 של חרס \u0003תחלתו\u0004 לענין קבלת טומאה (שאינו מקבל טומאה לפני כן) כשיש בגובהו \u0003ארבעה\u0004 טפחים. \u0003ו\u0004אם נטמא התנור ונשבר, הריהו עדיין טמא כל עוד יש ב\u0003שיריו\u0004 (שבריו) שיעור \u0003ארבעה\u0004 טפחים, אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: במה דברים אמורים\u0004 שהשיעור הוא ארבעה טפחים — רק \u0003ב\u0004תנור העומד לאפיה, שהוא תנור \u0003גדול, אבל ב\u0004תנור \u0003קטן\u0004 — \u0003תחלתו\u0004 לענין קבלת טומאה הוא בשיעור \u0003כל שהוא, משתגמר מלאכתו,\u0004 ולענין טומאה בתנור כזה שנשבר — אין הוא נטהר אלא אם כן \u0003שיריו\u0004 (שבריו) הם \u0003ברובו\u0004 של התנור.","ומסבירים: \u0003וכמה\u0004 הוא שיעור זה המכונה \u0003\"כל שהוא\"? אמרי דבי\u0004 \u0005[אומרים\u0006 חכמי \u0005בית]\u0006 מדרשו של \u0003ר' ינאי:\u0004 שיעורו \u0003טפח, שכן עושים תנורים\u0004 עבור ה\u0003בנות\u0004 הקטנות ששיעורם הוא \u0003טפח.\u0004","ומעתה יש לשאול: סבורים חכמים במשנה זו שתנור גדול נחשב לענין קבלת טומאה כל עוד שיעור שבריו הוא ארבעה טפחים, ונדייק מכאן: \u0003טעמא דאיכא\u0004 \u0005[הטעם\u0006 הריהו רק \u0005כשיש]\u0006 ב\u0003שיריו\u0004 שיעור \u0003ארבעה\u0004 טפחים, \u0003הא ליכא\u0004 \u0005[הרי אם אין]\u0006 ב\u0003שיריו\u0004 שיעור \u0003ארבעה\u0004 טפחים — הריהו \u0003טהור\u0004 בכל אופן, וגם אם יש באחד מהשברים רוב תנור, ושלא כדברי חכמים במשנה הקודמת!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003התם\u0004 \u0005[שם],\u0006 במשנה המטהרת (לדעת חכמים) כל שאין בשיעור השבר ארבעה טפחים — מדובר בזמן \u0003דצלקיה מצלק\u0004 \u0005[שחתך אותו לגובהו],\u0006 ואז אין השברים עומדים באופן יציב זה על זה. ואילו \u0003הכא\u0004 \u0005[כאן],\u0006 במשנה האומרת שהתנור נטהר רק באופן שאין באחד השברים רוב תנור — מדובר בזמן \u0003דעבדיה גיסטרא\u0004 \u0005[שעשאו\u0006, שהפריד את התנור לגובהו, והניח את \u0005תחתית התנור].\u0006","ועוד בבירור אותה משנה. שנינו ש\u0003אמר\u0004 \u0003מר\u0004 \u0005[החכם]\u0006 כי תנור קטן מקבל טומאה אף בכל שהוא. ואם נשבר, הריהו טהור רק כאשר \u0003שיריו\u0004 (שבריו) הם \u0003ברובו\u0004 של תנור. ואולם אם נשאר רובו של התנור שלם, אין הוא נטהר בכך. ותוהים: והרי למדנו למעלה מדברי חכמי בית מדרשו של ר' ינאי כי שיעור \"כל שהוא\" הריהו טפח, ומעתה \u0003רובו\u0004 של \u0003טפח\u0004 (שהוא מידתו של תנור קטן) \u0003למאי הוי\u0004 \u0005[למה הוא\u0006 משמש\u0005],\u0006 ומדוע הריהו טמא?","\u0003אמר אביי\u0004 בתשובה: מה שנאמר \"שיריו ברובו\" אינו מתייחס לשברי תנור קטן, אלא ל\u0003שירי\u0004 (שברי) תנור \u0003גדול\u0004 שאינ ו נטהר עד שישבר \u0003ברובו.\u0004 ומקשים על כך: \u0003והאמרי רבנן\u0004 \u0005[והרי אומרים חכמים]\u0006 בטהרת תנור גדול שהיא כשאין בשבריו \u0003ארבעה\u0004 טפחים! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרו חכמים כי תנור גדול נטהר כששבריו הם ברובו — מדובר \u0003בתנורא בר\u0004 \u0005[בתנור בן]\u0006 \u0003תשעה\u0004 טפחים. שכאשר תנור כזה נשבר ברובו, אף שנשארו בו חלקים שגודלם ארבעה טפחים — הריהו טהור. ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמרו חכמים כי תנור גדול נטהר רק כשאין בשבריו ארבעה טפחים — מדובר \u0003בתנורא בר\u0004 \u0005[בתנור בן]\u0006 \u0003שבעה\u0004 טפחים, שכיון שלא נשאר בו שבר בן ארבעה טפחים, הריהו נטהר, אף שאותו שבר הוא רובו של התנור.","ושבים לבירור דברי המשנה (שהובאה לעיל קכג,א) בדין הטלית הטמאה שנקרעה ברובה, שנטהרת בכך, ובפירושה של המשנה הובאו (לעיל קכג,ב) דברי רב הונא בשם ר' שמעון בר' יוסי שמדובר במשנה דווקא כשלא שייר בטלית כדי מעפורת, אבל אם שייר בה כדי מעפורת — לא בטל מכך תורת בגד מן הטלית. ועתה מביאים כי \u0003לישנא\u0004 \u0003אחרינא אמרי לה\u0004 \u0005[בלשון אחרת אומרים אותה]\u0006 הלכה באופן שונה: \u0003אמר רב הונא משום\u0004 \u0005[בשם]\u0006 \u0003ר' ישמעאל בר' יוסי: ואפילו שייר בה כדי מעפורת.\u0004","ובהמשך לדברים הללו \u0003אמר ריש לקיש: לא שנו\u0004 חכמים במשנה שנטהרת הטלית בקריעת רובה, אף ששייר בה כדי מעפורת, \u0003אלא\u0004 דווקא \u0003טלית, אבל עור\u0004 טמא שנקרע ברובו ושייר בו כדי מעפורת — הריהו עדיין דבר \u0003חשיב\u0004 \u0005[חשוב],\u0006 ולא נטהר בכך מטומאתו. \u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 כי \u0003אפילו עור\u0004 שנקרע ברובו, אף שהשתייר בו כדי מעפורת, \u0003נמי לא חשיב\u0004 \u0005[גם כן אינו חשוב],\u0006 ונטהר בקריעה זו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו ש\u0003עור\u0004 ה\u0003טמא\u0004 בטומאת \u0003מדרס,\u0004 אם בעליו \u0003חישב עליו ל\u0004עשות ממנו \u0003רצועה וסנדלין\u0004 — \u0003כיון שנתן\u0004 (שנעץ) \u0003בו איזמל,\u0004 הריהו \u0003טהור,\u0004 אלו \u0003דברי ר' יהודה. וחכמים אומרים\u0004 שאין העור נטהר מטומאתו אלא \u0003עד שימעיטנו מחמשה טפחים.\u0004","ונדייק בדברי חכמים: אין חכמים מטהרים את העור בעצם נעיצת האיזמל בו, ואולם \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003ממעט\u0004 מחמישה טפחים, \u0003מיהא\u0004 \u0005[על כל פנים]\u0006 הריהו \u0003טהור\u0004 לדעת חכמים, ויש לשאול לשיטתך: \u0003אמאי\u0004 \u0005[מדוע]\u0006 הוא נטהר? \u0003לימא חשיב\u0004 \u0005[אמור\u0006 שהעור \u0005חשוב]\u0006 אף בזמן שהומעט מחמישה טפחים, ולא ייטהר! השיב ריש לקיש: אין זו קושיה, שכן \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003דקא בעי ליה\u0004 \u0005[שהוא צריך אותו,\u0006 את העור החתוך\u0005]\u0006 \u0003למושב\u0004 שישב עליו \u0003זב,\u0004 ועור שיש בו פחות מחמישה טפחים, אינו יכול לשמש למושב. ולכך אין הוא נחשב.","\u0003עור\u0004 של בהמת נבילה \u0003שיש עליו\u0004 במקום אחד שיעור \u0003כזית\u0004 של \u0003בשר,\u0004 כל \u0003הנוגע בציב\u0004 (חוט בשר דק) \u0003היוצא ממנו\u0004 מחתיכה זו שעל העור, או שנוגע \u0003בשערה ש\u0004נמצאת \u0003כנגדו\u0004 של אותו כזית בשר, בצידו האחר של העור — הריהו \u0003טמא,\u0004 אף שאין בציב ובשערה הללו שיעור כזית. שהציב הריהו כבשר לכל דבר, והנוגע בו כנוגע בבשר. ואילו השערה נחשבת כ\"שומר\" לבשר, וכל הנוגע ב\"שומר\" דינו כנוגע בבשר. אם \u0003היו עליו\u0004 על עור הנבילה במקומות שונים שתי חתיכות בשר, ששיעורן \u0003הוא\u0004","\u0003כשני חצאי זיתים\u0004 — הרי העור \u0003מטמא\u0004 את נושאו \u0003במשא\u0004 שהרי הוא נושא את שניהם יחד, \u0003ו\u0004אילו הנוגע בהם \u0003לא\u0004 נטמא \u0003במגע,\u0004 אם אין הוא נוגע בשתיהן כאחת, ואין שתי נגיעות זו אחר זו מצטרפות להיחשב כנגיעה אחת. אלו \u0003דברי ר' ישמעאל, ר' עקיבא אומר:\u0004 חתיכות בשר אלה אין מטמאות \u0003לא במגע ולא במשא,\u0004 וכפי שיוסבר בהמשך דברי המשנה. אבל \u0003מודה ר' עקיבא ב\u0004שתי חתיכות בשר נבילה שיש בשיעורן \u0003שני חצאי זיתים, שתחבן בקיסם, והסיטן\u0004 (הניע אותן) — \u0003שהוא טמא,\u0004 שכן נחשב הדבר כנושא\u0003.\u0004 \u0003ומפני מה ר' עקיבא מטהר ב\u0004נוגע ובנושא שתי חתיכות בשר נבילה שעל ה\u0003עור,\u0004 ואילו כשהן תחובות בקיסם הריהו מטמא? \u0003מפני ש\u0004לדעתו \u0003העור מבטלן\u0004 לשתי החתיכות, שכל אחת מהן מתבטלת אגב העור, ונמצא שאין על העור שיעור שלם של בשר המטמא.","שנינו במשנתנו שעור שיש עליו כזית בשר אינו בטל על ידי העור, ולכך הנוגע בציב היוצא ממנו הריהו טמא. ובענין זה \u0003אמר עולא, אמר ר' יוחנן: לא שנו\u0004 כן במשנתנו \u0003אלא\u0004 דווקא בזמן ש\u0003פלטתו חיה\u0004 לבשר זה מגוף הבהמה (וכגון שנשכה כלב), \u0003אבל\u0004 אם \u0003פלטתו סכין\u0004 לבשר זה — הרי הבשר (אף שיש בו שיעור כזית) \u0003בטיל\u0004 \u0005[בטל]\u0006 אצל העור, שכן ביטלו האדם במעשהו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לעולא\u0004 בשאלה: האם \u0003אמר\u0004 כן \u0003ר' יוחנן אפילו\u0004 בשיעור גדול של בשר \u0003כתרטא\u0004 \u0005[רובע הקב]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא בתשובה: \u0003אין\u0004 \u0005[כן].\u0006 הוסיף רב נחמן ושאל בתמיהה: \u0003ואפילו\u0004 היה הבשר \u0003כ\u0004גודלה של \u0003נפיא\u0004 \u0005[נפה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא בתשובה: \u0003אין\u0004 \u0005[כן],\u0006 \u0003אמר ליה\u0004 רב נחמן לעולא בלשון שבועה: \u0003האלהים!\u0004 גם \u0003אם אמר לי\u0004 דבר זה \u0003רבי יוחנן\u0004 ישירות \u0003מפומיה\u0004 \u0005[מפיו],\u0006 \u0003לא צייתנא ליה\u0004 \u0005[לא הייתי מקשיב לו,\u0006 מקבל את דבריו\u0005]!\u0006","ומסופר: \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003רב אושעיא\u0004 מבבל לארץ ישראל \u0003אשכחיה ליה\u0004 \u0005[מצא את]\u0006 \u0003ר' אמי\u0004 כשהוא \u0003אמרה לשמעתיה קמיה\u0004 \u0005[אמר את ההלכה\u0006 הזו \u0005לפניו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר עולא, והכי אהדר ליה\u0004 \u0005[וכך השיב לו]\u0006 \u0003רב נחמן. אמר ליה\u0004 \u0005[לו]\u0006 רב אושעיא לר' אמי: \u0003ומשום\u0004 ש\u0003רב נחמן חתניה דבי נשיאה\u0004 \u0005[חתנו של בית הנשיא]\u0006 \u0003הוא,\u0004 הרי הוא \u0003מזלזל בשמעתיה\u0004 \u0005[בהלכותיו]\u0006 של \u0003ר' יוחנן?!\u0004","ועוד מסופר כי \u0003זמנין\u0004 \u0005[פעם\u0006 אחרת\u0005]\u0006 \u0003אשכחיה\u0004 \u0005[מצאו]\u0006 רב אושעיא לר' אמי \u0003דיתיב וקאמר לה אסיפא\u0004 \u0005[שיושב ואומר אותה\u0006 ההלכה \u0005על סוף\u0006 המשנה\u0005]:\u0006 \u0003היו עליו שני חצאי זיתים\u0004 — \u0003מטמאים במשא, ולא במגע.\u0004 אלו \u0003דברי ר' ישמעאל.\u0004 ואילו \u0003ר' עקיבא אומר\u0004 שאין הם מטמאים \u0003לא במגע ולא במשא.\u0004","ועל כך \u0003אמר ר' יוחנן: לא שנו\u0004 את דעת ר' ישמעאל המטמא במשא \u0003אלא\u0004 בשני חצאי כזית בשר ש\u0003פלטתו חיה\u0004 מהבהמה, \u0003אבל\u0004 בשני חצאי כזית בשר ש\u0003פלטתו סכין\u0004 בידי אדם — \u0003בטיל\u0004 \u0005[בטל].\u0006 ואילו היה רב נחמן שומע שדברי ר' יוחנן מתייחסים למקרה של חצאי זית, לא היה תמה אם כך הדין גם בחתיכות בשר גדולות כתרטא וכנפיא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אושעיא לר' אמי: \u0003מר אסיפא מתני לה\u0004 \u0005[אדוני, על סוף\u0006 המשנה \u0005שונה אותה\u0006 אמירה של ר' יוחנן\u0005]\u0006, ולא על החלק הראשון שענינו בכזית בשר? שהרי בזה אין מקום לתמיהותיו של רב \u0003נחמן.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אמי: \u0003אין\u0004 \u0005[כן].\u0006 \u0003ואלא\u0004 האם \u0003עולא ארישא\u0004 \u0005[על ראש\u0006 המשנה\u0005]\u0006 \u0003אמרה\u0004 להלכה זו של ר' יוחנן \u0003ניהליכו\u0004 \u0005[אצלכם\u0006 בבבל\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אין\u0004 \u0005[כן].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אמי: אם כך צדק רב נחמן בתמיהתו על דברי ר' יוחנן, \u0003שכן\u0004 \u0003האלהים\u0004 (לשון שבועה), גם \u0003אי אמר\u0004 \u0005[אם היה אומר]\u0006 \u0003לי\u0004 הלכה שכזאת \u0003יהושע בן נון משמיה\u0004 \u0005[משמו,\u0006 מפיו\u0005]\u0006 — \u0003לא צייתנא ליה\u0004 \u0005[לא הייתי מקשיב לו]!\u0006","ונמסר, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין וכל נחותי\u0004 \u0005[היורדים]\u0006 מארץ ישראל לבבל \u0003אמרוה\u0004 להלכה זו של ר' יוחנן \u0003ארישא\u0004 \u0005[על ראש\u0006 המשנה\u0005].\u0006 ומקשים על כך: \u0003ואלא קשיא\u0004 \u0005[קשה]\u0006 הדבר, שמאחר וכזית בשר בטל, יהא הדין כן אפילו בשיעורים גדולים יותר! ומשיבים: לא נאמרו דברי ר' יוחנן \u0003אלא\u0004 \u0003כ\u0004מו ש\u0003אמר רב פפא\u0004 בענין אחר,"],["שמדובר בו דווקא \u0003ב\u0004זמן שהבשר \u0003מרודד\u0004 (שטוח ברדידות על פני העור), \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בהלכתו של ר' יוחנן מדובר דווקא \u0003ב\u0004בשר ה\u0003מרודד,\u0004 ובאופן זה אכן גם כזית \u0003בשר ויותר שנפלט על ידי סכין בטל אצל העור.\u0004","שנינו במשנתנו שאם \u0003היו עליו,\u0004 על העור, שתי חתיכות מבשר הנבילה, ששיעור כל אחת מהן הוא כחצי זית — לדעת ר' ישמעאל הרי אלה מטמאות במשאן, אבל לא במגען.","ובענין זה \u0003אמר בר פדא: לא שנו\u0004 לדעת ר' ישמעאל \u0003אלא\u0004 רק במגען \u0003מאחריו\u0004 של העור, שאין האדם נוגע בצד העור שיש בו חתיכות הבשר אלא בצד שמאחוריו. \u0003אבל\u0004 הנוגע \u0003מלפניו,\u0004 ונגע בכך בחתיכות הבשר הנמצאות שם — נטמא במגעו זה, אף שלא נגע בנגיעה אחת בכזית בשר, שכן כלל הוא: \u0003יש\u0004 נגיעה המטמאת גם את ה\u0003נוגע וחוזר ונוגע,\u0004 ששתי נגיעות מצטרפות להיחשב כנגיעה אחת.","\u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 כי \u0003אין נוגע וחוזר ונוגע,\u0004 ולכך לדעת ר' ישמעאל גם הנוגע בשתי חתיכות הבשר הללו אינו נטמא. \u0003ו\u0004מעירים: \u0003אזדא\u0004 \u0005[הלך]\u0006 \u0003ר' יוחנן\u0004 בדבריו אלה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שכן \u0003אמר ר' יוחנן\u0004 ש\u0003ר' ישמעאל ור' דוסא בן הרכינס אמרו\u0004 שניהם \u0003דבר אחד,\u0004 ומחזיקים בעיקרון אחד.","ומפרטים: שיטת \u0003ר' ישמעאל\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 עתה, שאין שתי נגיעות מצטרפות לענין הטומאה. ושיטת \u0003ר' דוסא בן הרכינס\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בדין טומאת אוהל, ש\u0003כל\u0004 הדברים \u0003ה\u0004באים מן המת והריהם \u0003מטמאין באהל, שנחלקו\u0004 שיעוריהם (וכגון שנחצה בשר המת משיעור כזית לשני חצאי זית), \u0003והכניסן\u0004 את שני החלקים הללו \u0003לתוך הבית,\u0004 והריהם עתה נתונים בתוך אוהל אחד — \u0003ר' דוסא בן הרכינס מטהר\u0004 את הנמצא בתוך הבית, שאין שני החלקים הללו מצטרפים לשיעור כזית. \u0003ו\u0004אילו \u0003חכמים מטמאים\u0004 את הנמצא בתוך הבית, שכן הם מצטרפים לשיעור כזית.","ובהסבר דעת ר' דוסא בן הרכינס יש לומר: \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003אמר\u0004 כן \u0003ר' דוסא בן הרכינס התם\u0004 \u0005[שם,\u0006 לענין טומאת אהל\u0005]\u0006 אלא משום שלשיטתו \u0003אין מאהיל וחוזר ומאהיל,\u0004 ומכאן נלמד כי \u0003הכא נמי\u0004 \u0005[כאן\u0006 לענין טומאת מגע, \u0005גם כן]\u0006 סבור ר' דוסא בן הרכינס ש\u0003אין נוגע וחוזר ונוגע.\u0004 הרי שר' ישמעאל ור' דוסא בן הרכינס סבורים כאותה שיטה.","ושואלים על דברי ר' יוחנן: \u0003ו\u0004כיון שלדבריו שיטת \u0003ר' דוסא בן הרכינס\u0004 בדין טומאת אוהל היא \u0003כ\u0004שיטת \u0003ר' ישמעאל\u0004 שבמשנתנו, נמצא ששיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' דוסא בן הרכינס בדין טומאת אוהל, הריהי \u0003כ\u0004שיטת \u0003ר' עקיבא\u0004 במשנתנו. \u0003ו\u0004על כך יש לתהות: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ר' עקיבא\u0004 במשנתנו מקל כנגד ר' ישמעאל, שכן \u0003טהורי קא מטהר\u0004 \u0005[לטהר הוא מטהר]\u0006 הן מטומאת מגע והן מטומאת משא, ואילו חכמים בדין טומאת אוהל מחמירים כנגד ר' דוסא בן הרכינס המטהר!","ומשיבים: \u0003עד כאן לא\u0004 שמענו כי \u0003קא מטהר\u0004 \u0005[הוא מטהר]\u0006 \u0003ר' עקיבא אלא ב\u0004חתיכות בשר שעל ה\u0003עור\u0004 בלבד, שאינן מצטרפות, ומשום טעם מיוחד שיש בעור דווקא. \u0003אבל בעלמא\u0004 \u0005[בכלל]\u0006 דברים אחרים לענין דינם בצירופם הריהו \u0003מטמא. כדקתני סיפא\u0004 \u0005[כמו ששנינו\u0006 ב\u0005סוף\u0006 משנתנו\u0005],\u0006 \u0003ומודה ר' עקיבא בשני חצאי זיתים שתחבן בקיסם והסיטן, שהוא טמא. ומפני מה ר' עקיבא מטהר בעור? מפני שהעור מבטלן.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב עוקבא בר חמא\u0004 על דברי בר פדא שאמר כי לדעת ר' ישמעאל מטמאות שתי חתיכות הבשר (שאין בכל אחת מהן שיעור כזית) במגען, כאשר נגע בהן עצמן, ממה ששנינו \u0003בברייתא על הכתוב בפרשת הטומאות \"ולאלה תטמאו כל הנוגע בנבלתם\u0004 יטמא עד הערב. וכל הנושא מנבלתם יכבס בגדיו וטמא עד הערב\" (ויקרא יא, כד—כה): באה המלה \u0003\"בנבלתם\"\u0004 כהדגשה, לומר שדווקא הנוגע בהם עצמם הוא הנטמא, \u0003ולא\u0004 זה הנוגע \u0003בעור שיש עליו\u0004 שתי חתיכות בשר הבא מן המת, ששיעורן הוא \u0003שני חצאי זיתים.\u0004","\u0003יכול\u0004 לא יטמא \u0003אף במשא\u0004 של שתי חתיכות בשר אלה? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בהמשך \"\u0003ו\u0004כל \u0003הנושא\u0004 מנבלתם יכבס בגדיו וטמא עד הערב\", שאף באופן זה \u0003יטמא.\u0004 אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר:\u0004 נאמר בכתוב \"כל \u0003הנוגע\"\u0004 וכן נאמר \u0003\"ו\u0004 כל \u0003הנושא\",\u0004 והרי זה בא להקישם זה לזה ולומר: \u0003את\u0004 זה \u0003שבא לכלל\u0004 טומאת \u0003מגע\u0004 — הריחו \u0003בא\u0004 גם \u0003לכלל\u0004 טומאת \u0003משא,\u0004 ואילו זה ש\u0003לא בא לכלל\u0004 טומאת \u0003מגע\u0004 — אף \u0003לא בא לכלל\u0004 טומאת \u0003משא.\u0004","\u0003ו\u0004מעתה יש להקשות לבר פדא: \u0003אם\u0004 אמנם \u0003איתא\u0004 \u0005[יש\u0006 מקום\u0005]\u0006 לומר שר' ישמעאל סבור שחתיכות הבשר הללו מטמאות במגען (כשנגע בהן מלפנים)\u0005,\u0006 \u0003הרי\u0004 אף זה \u0003בא לכלל מגע מלפניו,\u0004 ומה איפוא טען ר' עקיבא כלפי ר' ישמעאל שאין מקום לטומאת משא משום שאין כאן טומאת מגע?","\u0003אמר רבא\u0004 בתשובה: \u0003הכי קאמר\u0004 \u0005[כך הוא,\u0006 ר' עקיבא \u0005אמר],\u0006 כך צריך להבין את דבריו: \u0003את שבא לכלל\u0004 טומאת \u0003מגע בכל צד\u0004 של נגיעה, ולא רק בנגיעה מלפניו — הוא זה ש\u0003בא לכלל\u0004 טומאת \u0003משא,\u0004 וזה ש\u0003לא בא לכלל\u0004 טומאת \u0003מגע בכל צד\u0004 — \u0003לא בא לכלל\u0004 טומאת \u0003משא.\u0004","ודנים עוד בשיטת ר' ישמעאל. \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב אויא סבא מרבה בר רב הונא: קולית\u0004 (עצם הירך) שאין עליה בשר, ובתוכה יש מח, והיא \u0003סתומה\u0004 מכל צדדיה, ששנינו במשנתנו כי קולית נבילה וקולית השרץ הסתומות טהורות אף מטומאת המשא, שכן אין הן באות לכלל טומאת מגע. ומעתה יש לשאול \u0003ל\u0004שיטת \u0003ר' ישמעאל מהו\u0004 לענין \u0003שתטמא\u0004 בטומאת המשא.","וצדדי השאלה: האם \u0003אית ליה\u0004 \u0005[יש לו,\u0006 סבור\u0005]\u0006 \u0003ר' ישמעאל\u0004 את הכלל האומר כי \u0003את\u0004 זה \u0003שבא לכלל\u0004 טומאת \u0003מגע\u0004 — הוא זה שגם \u0003בא לכלל\u0004 טומאת \u0003משא,\u0004 ואולם זה ש\u0003לא בא לכלל\u0004 טומאת \u0003מגע\u0004 — \u0003לא בא לכלל\u0004 טומאת \u0003משא, ו\u0004מעתה \u0003הכא\u0004 \u0005[כאן]\u0006 שלמדנו כי ר' ישמעאל מטמא בטומאת משא שני חצאי זית מן המת הנמצאים על העור, אף שאין הם באים לכלל טומאת מגע, יש לומר כי \u0003היינו טעמא\u0004 \u0005[זהו הטעם]:\u0006 \u0003משום\u0004 שאף שאין הוא בא לכלל טומאת מגע מאחריו, מכל מקום הוא \u0003בא לכלל מגע מלפניו,\u0004 ומכאן נסיק כי בקולית סתומה, שאין כל אפשרות לבוא לכלל טומאת מגע, ואף לא מלפנים — סבור ר' ישמעאל שאין היא מטמאת במשא.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור\u0005]\u0006 ר' ישמעאל את הכלל הזה, שכן בשני חצאי זית היה מטמא ר' ישמעאל במשא, גם אם אין הם נטמאים במגע מלפניו. ומכאן נסיק כי בקולית סתומה, אף שאין כל אפשרות לבוא בא לכלל טומאת מגע — סבור ר' ישמעאל שמטמאה בטומאת משא?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר רב הונא לרב אויא סבא בהתעלמות משאלתו ופונה לענין אחר: הנה \u0003עורבא פרח\u0004 \u0005[עורב פורח]\u0006 באויר, שלא השיב כלל על שאלתו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של רבה בר רב הונא: \u0003ולאו היינו\u0004 \u0005[וכי אין זה]\u0006 אותו \u0003רב אויא סבא מ\u0004העיר \u0003פומבדיתא דמשבח לן מר בגויה דגברא רבה הוא\u0004 \u0005[שמשבח\u0006 אותו \u0005אדוני בפנינו עליו שאדם גדול הוא],\u0006 ומדוע אתה דוחה אותו ואינך עונה לו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר רב הונא לבנו בתשובה: \u0003אני היום\u0004 התקיים בי הכתוב \u0003\"סמכוני באשישות\u0004 רפדוני בתפוחים\" (שיר השירים ב, ה), שאני עייף וזקוק למנוחה ואין בכוחי להיכנס לעומקה של הלכה, ובא \u0003רב אויא סבא\u0004 \u0003ובעא מינאי מילתא דבעי טעמא\u0004 \u0005[ושאל ממני דבר שצריך טעם],\u0006 \u0003ולכן דחיתיו, ולא משום זלזול בו.\u0004","\u0003אמר עולא: שני חצאי זיתים שתחבן בקיסם, אפילו\u0004 הוא \u0003מוליך ומביא\u0004 אותם \u0003כל היום כולו\u0004 — הריהו \u0003טהור\u0004 מטומאת משא.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — שכן \u0003כתיב\u0004 \u0005[נאמר]\u0006 בטומאת המשא \"והנושא את נבלתה יכבס בגדיו וטמא עד הערב\" (ויקרא יא, מ), המלה כתובה \u0003\"ו\u0004 ה\u0003נשא\",\u0004 \u0003ו\u0004אולם \u0003קרינן\u0004 \u0005[קוראים אנו]\u0006 \"וה \u0003\"נושא\",\u0004 ומעתה יש לנו ללמוד כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 בדין טומאת משא שיהיה הדבר הנטמא \u0003\"נושא\"\u0004 את טומאת הנבילה (ששיעורה כזית ויותר), \u0003ו\u0004שיהא \u0003הוא\u0004 (הכזית מן המת) \u0003נישא בבת אחת.\u0004 מה שאין כן בנושא שני חצאי זיתים התחובים בקיסם. ומקשים על דברי \u0003עולא:\u0004","\u0003תנן\u0004 \u0005[שנינו]\u0006 במשנתנו שאם \u0003היו עליו\u0004 (על העור) \u0003שני חצאי זיתים\u0004 מן המת — הריהם \u0003מטמאין ב\u0004טומאת \u0003משא ולא ב\u0004טומאת \u0003מגע,\u0004 אלה הם \u0003דברי ר' ישמעאל,\u0004 ולשיטת עולא יש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 הם מטמאים לדעת ר' ישמעאל, \u0003והא לאו\u0004 \u0005[והרי לא]\u0006 מתקיים תנאי זה בטומאת המשא, שכן זה לא \u0003נישא\u0004 בבת אחת","\u0003הוא! אמר רב פפא:\u0004 מדובר כאן \u0003במרודד,\u0004 שמשוטח הבשר על פני העור, שאמנם אין כזית בשר שלם במקום אחד, אלא כחצי זית בשר במקום זה על העור וכחצי זית בשר במקום אחר, ואולם רצועת בשר שטוחה בין זה לזה, ומחברת אותם להחשיבם כנישאים בבת אחת.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה שלא כשיטת עולא, שהרי שנינו בסוף משנתנו ש\u0003מודה ר' עקיבא בשני חצאי זיתים שתחבן בקיסם והסיטן שהוא טמא,\u0004 ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 הוא נטמא בכך, \u0003והא לאו\u0004 \u0005[והרי לא]\u0006 \u0003\"נישא\u0004 בבת אחת\" \u0003הוא\u0004 זה! ודוחים: אין זו קושיה על עולא, שכן \u0003הכא נמי\u0004 \u0005[כאן,\u0006 בשיטת ר' עקיבא, \u0005גם כן]\u0006 יש לומר שמדובר \u0003במרודד.\u0004","ומציעים עוד: דעה זו של עולא הריהי \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים],\u0006 שכן שנינו בברייתא בדינן של שתי חתיכות בשר מן המת שאין בכל אחת מהן שיעור כזית, כי \u0003אחד\u0004 (בין) \u0003הנוגע\u0004 בהן \u0003ואחד\u0004 (ובין) \u0003המסיט\u0004 אותן — הריהם טמאים. \u0003ר' אליעזר אומר: אף הנושא\u0004 אותם — טמא. ויש לדון בדברי ר' אליעזר: \u0003אטו\u0004 \u0005[וכי]\u0006 ה\u0003נושא לאו\u0004 \u0005[לא]\u0006 \u0003מסיט הוא,\u0004 ומה איפוא הוסיף על דברי חכמים?","\u0003אלא לאו הכי קאמר\u0004 \u0005[האם לא כך הוא\u0006 התנא בברייתא \u0005אומר]:\u0006 \u0003אחד הנוגע ואחד המסיט בלא נישא, ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' אליעזר למימר\u0004 \u0005[לומר]:\u0006 \u0003והוא\u0004 דווקא כש\u0003נישא\u0004 בבת אחת, שהן בטומאת מגע והן בטומאת משא אין אלה מטמאות אלא כשהן מחוברות. \u0003ו\u0004יש להקשות על הסבר זה: \u0003מאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"אף\",\u0004 שהרי ר' אליעזר לא בא להוסיף על דברי התנא הראשון אלא לצמצם דבריו. אלא \u0003אימא\u0004 \u0005[אמור]\u0006 באופן שונה את דברי ר' אליעזר: שהריהו אומר \u0003והוא\u0004 ש\u0003נישא,\u0004 ומכאן נלמד שמחלוקת תנאים היא האם נדרש שיהא נישא בבת אחת אם לא.","\u0003קולית\u0004 (עצם הירך) של \u0003המת,\u0004"],["\u0003ו\u0004כן \u0003קולית\u0004 בהמות \u0003המוקדשין\u0004 (קרבנות שנתפגלו או שנותרו, והריהם מטמאים מגזירת חכמים), שיש בתוכם מוח, כל \u0003הנוגע בהן, בין\u0004 שהיו הקוליות \u0003סתומים\u0004 שאין אפשרות לגעת במוח שבהן, \u0003בין\u0004 שהיו \u0003נקובים\u0004 — הריהו \u0003טמא\u0004 במגען. שכן עצם (בשיעור כשעורה) הבאה מן המת, וכן עצם של הקרבנות שנפסלו, מטמאות בטומאת מגע. ואולם","\u0003קולית\u0004 בהמת ה\u0003נבלה ו\u0004כן \u0003קולית השרץ,\u0004 כל \u0003הנוגע בהם,\u0004 אם היו \u0003סתומים\u0004 — הנוגעים בהם \u0003טהורים,\u0004 כיון שאי אפשר לגעת במוח שבתוכן, ואילו עצמותיהן כשלעצמן אינן מטמאות. ואם היו העצמות הללו \u0003נקובים,\u0004 ואפילו היה זה נקב ששיעורו \u0003ב\u0004\u0003כל שהוא\u0004 — \u0003מטמא במגע,\u0004 שנחשבת הנגיעה בעצם כנגיעה במוח שבתוכן. \u0003מנין שאף ב\u0004טומאת \u0003משא\u0004 יש לחלק בין קולית סתומה לקולית נקובה? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בטומאת המשא בנבילה \u0003\"הנוגע\u0004 בנבלתה יטמא עד הערב... \u0003והנושא\u0004 את נבלתה יכבס בגדיו וטמא עד הערב\" (ויקרא יא, לט—מ), ללמד כי \u0003את\u0004 זה \u0003שבא לכלל\u0004 טומאת \u0003מגע\u0004 — הוא \u0003בא לכלל\u0004 טומאת \u0003משא,\u0004 ואילו זה ש\u0003לא בא לכלל\u0004 טומאת \u0003מגע\u0004 כעצמות הסתומות — \u0003לא בא לכלל\u0004 טומאת \u0003משא.\u0004","שנינו במשנתנו שהנוגע בקולית המת, בין זו שהיא נקובה ובין זו שהיא סתומה, נטמא במגע זה. ומדייקים: דווקא ה\u0003נוגע\u0004 בה — \u0003אין\u0004 \u0005[כן]\u0006 נטמא, \u0003אבל\u0004 ה\u0003מאהיל\u0004 על קולית המת — \u0003לא\u0004 נטמא, שאין העצם מטמאה בטומאת אהל.","ומעתה יש לברר: \u0003היכי דמי\u0004 \u0005[איך בדיוק היה הדבר]?\u0006 \u0003אי דאיכא\u0004 \u0005[אם\u0006 מדובר בקולית \u0005שיש]\u0006 עליה \u0003כזית בשר\u0004 מן המת — \u0003ב\u0004טומאת \u0003אהל נמי ליטמא\u0004 \u0005[גם כן שתטמא],\u0006 מפני הבשר שעליה! ומשיבים: מדובר בזמן \u0003דליכא\u0004 \u0005[שאין כאן]\u0006 \u0003כזית בשר\u0004 על הקולית.","\u0003ו\u0004ממשיכים לברר: \u0003אי\u0004 \u0005[אם]\u0006 מדובר בזמן \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003כזית מוח מבפנים\u0004 (בתוך הקולית) — הרי כלל הוא ש\u0003טומאה בוקעת\u0004 מבעד לעצם \u0003ועולה,\u0004 אם כן \u0003ב\u0004טומאת \u0003אהל נמי ליטמא\u0004 \u0005[גם כן תטמא]\u0006 הקולית! ומשיבים: מדובר כאן \u0003דליכא\u0004 \u0005[שאין כאן]\u0006 \u0003כזית מוח בפנים\u0004 הקולית.","וממשיכים לדון בדבר: \u0003ואי\u0004 \u0005[ואם]\u0006 סבורה משנתנו שה\u0003מוח מבפנים\u0004 לקולית הוא \u0003מעלה ארוכה\u0004 (מרפא, גורם לאיחוי לבשר) \u0003ש\u0004\u0003מבחוץ\u0004 לעצם, ואף הבשר יכול לחזור ולהבריא את מוח עצם שנפגם או שנחסר. מעתה הרי עצם זו היא \u0003אבר מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003היא,\u0004 אף שאין בה מוח, כאבר המטמא באוהל גם אם אין לו שיעור כזית, וכן קולית זו \u0003ב\u0004טומאת \u0003אהל נמי ליטמא\u0004 \u0005[גם כן תטמא]!\u0006 \u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא\u0004 בתשובה: \u0003זאת אומרת,\u0004 מכאן נסיק כי לדעת משנתנו \u0003מוח בפנים אינו מעלה ארוכה\u0004 לבשר ש\u0003מבחוץ.\u0004","ושואלים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת]\u0006 את משנתנו? בזמן \u0003דליכא\u0004 \u0005[שאין]\u0006 בתוך הקולית \u0003כזית\u0004 מוח — \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא, \u0003ב\u0004קולית ה\u0003מוקדשים אמאי\u0004 \u0005[מדוע]\u0006 \u0003מטמא?\u0004 שהרי טומאת קולית הקרבנות היא מגזירת חכמים שגזרו על העצמות ששימשו את הנותר (ואף הקולית שימשה את המוח שבתוכה, שהוא בכלל נותר), ואולם אין דין נותר בפחות מכזית!","\u0003ותו\u0004 \u0005[ועוד]\u0006 יש לשאול: אם אמנם מדובר במשנתנו בזמן שאין בקולית מוח בשיעור כזית, \u0003קולית נבלה וקולית השרץ כי\u0004 \u0005[כאשר]\u0006 \u0003ניקבו, אמאי\u0004 \u0005[מדוע]\u0006 \u0003הן\u0004 \u0003מטמאו\u0004 \u0005[מטמאות]?\u0006 והרי אין בהן כזית מוח!","ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה לא קשה],\u0006 שיש לומר כי ב\u0003רישא\u0004 \u0005[התחלה]\u0006 של משנתנו (בדין טומאת המת) מדובר במקרה \u0003דליכא\u0004 \u0005[שאין]\u0006 בקולית \u0003כזית\u0004 מוח, ואילו ב\u0003סיפא\u0004 \u0005[סוף,\u0006 בהמשך\u0005]\u0006 משנתנו (בדין קולית המוקדשים וקולית הנבילה והשרץ) מדובר במקרה \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003כזית\u0004 מוח בקולית. ומעתה בקולית המוקדשים מדובר שיש בה שיעור שנוהג דין נותר, ובקולית הנבילה והשרץ יש בו שיעור שנוהגות בו טומאות אלה. \u0003ו\u0004תוהים: אם כן, \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 התנא במשנתנו, והרי הלכה ידועה היא! ומשיבים: \u0003מילי מילי קא משמע לן\u0004 \u0005[דברים דברים הוא\u0006 התנא \u0005משמיע לנו]\u0006 שבכל דבר השנוי במשנתנו יש דבר חידוש.","שב\u0003רישא קא משמע לן\u0004 \u0005[בהתחלה הוא משמיע לנו]\u0006 כי ה\u0003מוח מבפנים אינו מעלה ארוכה\u0004 לבשר ש\u0003מבחוץ,\u0004 ושלא כדעת האומרים שהריהו מעלה ארוכה. ולאחר מכן בקולית ה\u0003מוקדשין מאי קא משמע לן\u0004 \u0005[מה הוא משמיע לנו]?\u0006 שגם הדבר שהוא \u0003שימוש\u0004 של ה\u0003נותר,\u0004 כעצמות הללו שיש בהן \u0003מוח שהוא כבשר הקרבן\u0004 — \u0003מילתא\u0004 \u0005[דבר]\u0006 נחשב \u0003היא,\u0004 ומטמאת. שכן \u0003אמר מרי בר אבוה, אמר ר' יצחק: עצמות\u0004 של \u0003קדשים ששימשו\u0004 את ה\u0003נותר\u0004 — הריהן \u0003מטמאין את הידים,\u0004 כפי שקרבן הנותר מטמאן. וטעם הדבר: \u0003הואיל ו\u0004העצם הזו \u0003נעשה בסיס לדבר האסור,\u0004 לכך דינו כדין הדבר האסור. ולאחר מכן זו ששנינו במשנתנו בקולית ה","\u0003נבלה\u0004 שמטמאה רק כשהיא נקובה ולא כשהיא סתומה — חידוש יש בדבר: ש\u0003אף על גב דאיכא\u0004 \u0005[אף על פי שיש]\u0006 בתוכה \u0003כזית\u0004 מוח, מכל מקום רק אם \u0003ניקבה\u0004 הקולית — \u0003אין\u0004 \u0005[כן]\u0006 הריהי מטמאת, ואם \u0003לא ניקבה\u0004 — היא \u0003לא\u0004 מטמאת.","ועוד אופן בהסבר דברי משנתנו. \u0003אביי אמר: לעולם\u0004 יש לומר כי משנתנו סבורה ש\u0003מוח מבפנים\u0004 העצם הריהו \u0003מעלה ארוכה\u0004 לבשר ש\u0003מבחוץ\u0004 לה. \u0003ו\u0004באשר לשאלה מדוע אין הקולית מטמאת בטומאת אוהל, ומשום המוח — \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 במשנתנו \u0005במה אנו עוסקים]?\u0006 \u0003ב\u0004מקרה \u0003ששפה\u0004 (שפשף, שייף והחליק) את העצם ושוב אין העצם מעלה ארוכה לבשר שעליה ולמוח שבתוכה. ולכן אינה נחשבת כאיבר, לטמא בטומאת אוהל.","\u0003וכ\u0004שיטת \u0003ר' אלעזר,\u0004 שכן \u0003אמר ר' אלעזר: קולית ששפה\u0004 אותה \u0003לארכה\u0004 — הרי היא עדיין \u0003טמאה\u0004 כאיבר, אף שאין בה בשר או מוח, שכן כששף כיוצא בה בחי הריהי מעלה ארוכה, וגם לאחר ששויפה יש אפשרות להתרקמות מחודשת. ואולם אם ניסרה \u0003לרחבה\u0004 — אין היא שוב מעלה ארוכה, ולכך הריהי \u0003טהורה, וסימניך\u0004 מה מעלה ארוכה ומה אינו מעלה: \u0003דיקלא\u0004 שאם משייפים אותו לאורך הוא עשוי לחזור ולהתאחות, ואולם אם משייפים אותו לרוחב, באופן שמנתק את זרימת השרף בתוכו, אין הוא מתאחה.","\u0003ו\u0004עוד אופן בהסבר דברי משנתנו. \u0003ר' יוחנן אמר: לעולם\u0004 מדובר במשנתנו במקרה \u0003דאיכא\u0004 \u0005[שיש]\u0006 בקולית \u0003כזית\u0004 מוח, \u0003ו\u0004\u0003כמו כן סבורה משנתנו ש\u0004\u0003מוח מבפנים\u0004 העצם \u0003מעלה ארוכה\u0004 לבשר ש\u0003מבחוץ.\u0004 ובתשובה לשאלה מדוע אין הקולית מטמאת בטומאת אוהל, משום המוח שבתוכה — יש לומר כי אכן מטמאת הקולית אף בטומאת אוהל, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \"ה \u0003נוגע\u0004 בהן — טמא\" \u0003דקתני\u0004 \u0005[ששנינו]?\u0006 הכוונה היא ל\u0003מאהיל\u0004 עליהן.","\u0003ו\u0004שואלים על הסבר זה: \u0003אי\u0004 \u0005[אם]\u0006 אתה אומר ש\u0003מוח מבפנים מעלה ארוכה מבחוץ, קולית נבלה וקולית השרץ כי\u0004 \u0005[כאשר]\u0006 \u0003לא נקבו, אמאי\u0004 \u0005[מדוע]\u0006 הם \u0003טהורים?\u0004","\u0003אמר ר' בנימין בר גידל,\u0004 \u0003אמר ר' יוחנן: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון דאיכא\u0004 \u0005[שיש]\u0006 בפנים \u0003כזית מוח המתקשקש\u0004 (שנעקר ממקומו, ונע ממקום למקום ומשמיע בתוך כך רחש), ואז ל\u0003גבי\u0004 \u0005[אצל]\u0006 טומאת ה\u0003מת\u0004 — \u0003טומאה בוקעת ועולה,\u0004 ולכך הריהי מטמאה באוהל. ואולם אצל טומאת \u0003נבלה, כיון\u0004 שהמוח \u0003מתקשקש הוא,\u0004 שוב אינו מבריא, ולכן אם \u0003ניקבה\u0004 הקולית, וניתן לגעת במוח שבתוכה — \u0003אין\u0004 \u0005[כן]\u0006 מטמאה, ואולם אם \u0003לא ניקבה\u0004 — היא \u0003לא\u0004 מטמאה.","למעלה למדנו בדברי ר' יוחנן כי המאהיל נקרא \"נוגע\", ובענין זה \u0003אמר ר' אבין ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יוסי בר אבין: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 כדבר הזה, שכן שנינו במסכת אהלות שכל \u0003הנוגע\u0004 בידו האחת \u0003ב\u0004חתיכת בשר מן המת ששיעורה הוא \u0003כחצי זית, ו\u0004באותה עת \u0003הוא\u0004 \u0003מאהיל\u0004 בידו השניה \u0003על\u0004 חתיכת בשר מן המת ששיעורה הוא כ\u0003חצי זית, או\u0004 שחתיכת בשר מן המת ששיעורה הוא כ\u0003חצי זית מאהיל עליו\u0004 — הריהו \u0003טמא.\u0004","ומעתה \u0003אי אמרת בשלמא חד שמא הוא\u0004 \u0005[נניח,\u0006 מובן הדבר, \u0005אם אתה אומר\u0006 כי \u0005שם אחד הוא,\u0006 לטומאת מת ולטומאת אהל\u0005]\u0006 — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003מצטרף\u0004 חצי זית של נגיעה לחצי זית זה של אוהל, לטמא בו את האדם.","\u0003אלא אי אמרת תרי שמי נינהו\u0004 \u0005[אם אתה אומר\u0006 ש\u0005שני שמות הם]\u0006 — \u0003מי\u0004 \u0005[האם]\u0006 \u0003מצטרף\u0004 הוא? \u0003והתנן\u0004 \u0005[והרי שנינו]:\u0006 \u0003זה הכלל, כל שהוא\u0004 טמא \u0003משם\u0004 טומאה \u0003אחד\u0004 — הרי זה \u0003מצטרף, וטמא.\u0004 אם הוא טמא \u0003משני שמות\u0004 — אין הוא מצטרף, ו\u0003טהור!\u0004","ומקשים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אתה אומר, ש\u0003חד שמא\u0004 \u0005[שם אחד]\u0006 \u0003הוא? אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף]\u0006 אותה משנה: \u0003אבל\u0004"],["\u0003הנוגע ב\u0004חתיכת בשר מן המת ששיעורה הוא \u0003כחצי זית, ו\u0004באותה עת \u0003דבר אחר\u0004 (כגון קרש) \u0003מאהיל עליו ועל\u0004 חתיכת בשר אחרת מן המת ששיעורה הוא \u0003כחצי זית\u0004 — הריהו \u0003טהור.\u0004","\u0003ואי חד שמא\u0004 \u0005[ואם שם אחד]\u0006 \u0003הוא,\u0004 לטומאת מגע ולטומאת אוהל, \u0003אמאי\u0004 \u0005[מדוע]\u0006 אדם זה \u0003טהור?\u0004 ואומרים: \u0003אלא\u0004 מעתה \u0003קשיא רישא\u0004 \u0005[קשה התחלת\u0006 אותה משנה\u0005]\u0006 שממנה עולה שמצטרפות טומאת אוהל לטומאת מגע על מה שעולה מסוף המשנה שאין מצטרפות טומאת אוהל לטומאת מגע!","\u0003אמר ר' זירא:\u0004 בתחילת המשנה מדובר \u0003ב\u0004חתיכת בשר מן המת הנמצאת במקום דחוק, ונקראת \u0003טומאה רצוצה\u0004 (צפופה, זו שאין לה מקום מרווח), שנמצאת \u0003בין שני מגדלים\u0004 (ארונות עץ) \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ואין ביניהן\u0004 רווח כשיעור \u0003פותח טפח,\u0004 שכיון שמאהיל האדם בידו האחת מעל המגדלים הללו, והטומאה הרצוצה עולה כלפי מעלה, נמצא ש\u0003כולה נגיעה\u0004 אחת \u0003היא,\u0004 שהוא כנוגע בידו בטומאה ממש, והטומאה נוגעת בו כשהיא בוקעת ועולה. ונמצא איפוא שאין מהמשנה באהלות ראיה לשיטת ר' יוחנן שמאהיל הריהו כנוגע.","\u0003ו\u0004שואלים: אלא מעתה \u0003מאן\u0004 \u0005[מי]\u0006 ה\u0003תנא דקרי\u0004 \u0005[שקורא]\u0006 \u0003ל\u0004טומאת \u0003אהל \"נוגע\",\u0004 כשיטת ר' יוחנן? ומשיבים: שיטת \u0003ר' יוסי היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי אומר:\u0004 כמות בשיעור \u0003מלא תרווד\u0004 (כף) של \u0003רקב\u0004 (בשר המת שנרקב) הריהי \u0003מטמא\u0004 כדרך שהמת עצמו מטמא, בשלושה אופנים: \u0003במגע\u0004 בו, \u0003ובמשא\u0004 אותו \u0003ובאהל\u0004 המאהיל על הרקב ועל האדם.","\u0003בשלמא\u0004 \u0005[נניח,\u0006 זה מובן\u0005]\u0006 שמטמא הרקב \u0003במשא ובאהל,\u0004 שכן לענין טומאת משא — \u0003הא קא טעין ליה לכוליה\u0004 \u0005[הרי הוא נושא אותו כולו,\u0006 את כל מלוא התרווד\u0005]\u0006 בבת אחת. \u0003ו\u0004כיוצא בזה לענין טומאת אוהל — \u0003הא קא\u0004 \u0005[הרי הוא]\u0006 \u0003מאהיל אכוליה\u0004 \u0005[על כולו]\u0006 בבת אחת, ונטמא בכך. \u0003אלא\u0004 זה ה\u0003נוגע\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 הוא \u0003לא נגע בכוליה\u0004 \u0005[בכולו],\u0006 וכיצד הוא יכול להיטמא?! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא נלמד מכאן]\u0006 כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"נוגע\"\u0004 שאמר ר' יוסי? \u0003מאהיל.\u0004 וזהו התנא הסבור כשיטת ר' יוחנן שמאהיל נקרא \"נוגע\".","ומקשים: איך אפשר לפרש כן, \u0003והא קתני\u0004 \u0005[והרי שנה]\u0006 ר' יוסי בברייתא \u0003\"נוגע\"\u0004 לחוד \u0003והא קתני\u0004 \u0005[והרי שנה]\u0006 \u0003\"מאהיל\"\u0004 לחוד, והרי שאין מאהיל נקרא \"נוגע\"! \u0003אמר אביי:\u0004 אין זו קושיה, שכן יש להבחין בין מאהיל על הטומאה הנמצאת מתחת לידו המאהילה בשיעור ש\u0003למטה\u0004 (פחות) \u0003מטפח\u0004 — הרי \u0003אהל\u0004 זה נקרא \u0003\"נגיעה\",\u0004 ובזה אמר ר' יוסי שמלוא תרווד רקב מטמא במגע. ואילו המאהיל על הטומאה שמתחתיו בשיעור ש\u0003למעלה\u0004 (יותר) \u0003מטפח\u0004 — הרי זה \u0003אהל גרידא\u0004 \u0005[סתם],\u0006 ובזה אמר ר' יוסי שמלא תרוד רקב מטמא באוהל.","\u0003רבא אמר:\u0004 לדעת ר' יוסי \u0003אפילו\u0004 כשמאהיל על הטומאה \u0003ש\u0004\u0003למעלה מטפח נמי\u0004 \u0005[גם כן]\u0006 \u0003אהל נגיעה הוא, והיכי דמי\u0004 \u0005[ואיך נחשב,\u0006 באיזה אופן הוא מוגדר\u0005]\u0006 כ\u0003אהל גרידא\u0004 \u0005[סתם],\u0006 ולא כנוגע? \u0003בהמשכה,\u0004 כאשר דבר מאהיל על האדם ועל הטומאה גם יחד. שהדבר המאהיל ממשיך את הטומאה מן הדבר המטמא אל האדם.","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה,\u0006 את דעתי זו\u0005]?\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יוסי אומר: חבילי מטה\u0004 (רשת העשויה מחבלים המשמשת לשבת עליה), \u0003ו\u0004כן \u0003סריגי\u0004 (רשת סורגים) ה\u0003חלונות,\u0004 ששטחם בין קורות שבגג הבית, ועתה הם משמשים כתקרה בין הבית לעליה — הרי אלה התבטלו עם קביעתן כתקרה, ואין הם מקבלים טומאה. ואף שיש ברשתות הללו נקבים, הריהם \u0003חוצצין בין הבית לעלייה, שלא להכניס טומאה\u0004 של המת הנמצאת בתוך הבית \u0003לצד שני,\u0004 לעליה.","ואם \u0003פרסן\u0004 את הרשתות הללו \u0003על פני המת\u0004 הנמצא מחוץ לבית, שתלאן \u0003באויר,\u0004 ולא קבען, כל \u0003הנוגע כנגד הנקב\u0004 שברשתות הללו — הריהו \u0003טמא,\u0004 והנוגע \u0003שלא כנגד הנקב\u0004 — הריהו \u0003טהור.\u0004","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שפרס את הרשתות במרחק ש\u0003למטה\u0004 (פחות) \u0003מטפח\u0004 מפני המת — זה הנוגע \u0003שלא כנגד הנקב אמאי\u0004 \u0005[מדוע]\u0006 הוא \u0003טהור?\u0004 הלא במרחק כה קרוב אל המת, נחשבות הרשתות הללו כאחד מבגדיו של המת, וכ\u0003מת\u0004 הלבוש \u0003בכסותו היא, ו\u0004כלל הוא ש\u0003מת בכסותו מטמא,\u0004 שאין הכסות חוצצת בין המת ובין המאהיל עליו!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר שפרס במרחק ש\u0003למעלה\u0004 (יותר) \u0003מטפח\u0004 מעל פני המת, \u0003וקא קרי ליה\u0004 \u0005[והוא\u0006 ר' יוסי \u0005קורא לו]\u0006 \u0003\"נוגע\".\u0004 הרי איפוא שלשיטת ר' יוסי אף המאהיל מעל לטפח נקרא \"נוגע\", ושלא כדברי אביי.","\u0003אמר אביי\u0004 בדחיית ראייתו של רבא: אין זו קושיה, שכן \u0003לעולם\u0004 מדובר כאן בפורס את הרשתות הללו במרחק ש\u0003למטה מטפח, ודקאמרת\u0004 \u0005[ומה שאמרת]\u0006 בשאלה מדוע הנוגע שלא כנגד הנקב טהור, והרי כ\u0003מת\u0004 הלבוש \u0003בכסותו הוא\u0004 — אין המקרה הזה דומה למת הלבוש בכסותו, שכן \u0003מת בכסותו\u0004 — הכסות אינה חוצצת בין המת למאהיל עליו, משום שבהלבשת המת בכסותו בכך הריהו \u0003מבטל ליה\u0004 \u0005[אותו,\u0006 את הכסות\u0005]\u0006 אצל המת, שיהא זה בגדו של המת. ולכן הכסות נחשבת כחלק ממנו, ואינה חוצצת. מה שאין כן \u0003האי\u0004 \u0005[זה]\u0006 הרשת הניתנת מעל פני המת — \u0003לא מבטל ליה\u0004 \u0005[אותו]\u0006 לגבי המת, שהרי הוא עומד ליטלו ממנו.","ושואלים על הסברו של אביי: אם אכן המדובר בפורס מעל פני המת במרחק שפחות מטפח, אף שאין אלה נחשבים ככסותו של המת, \u0003ו\u0004מכל מקום \u0003תהוי\u0004 \u0005[תהיה,\u0006 תיחשב זו\u0005]\u0006 \u0003כטומאה טמונה\u0004 (הנמצאת בתוך חלל, מתחת לדבר הרחוק ממנה פחות מטפח) שהיא \u0003בוקעת\u0004 מבעד לאותו הדבר שמעליה, \u0003ועולה\u0004 מעלה, ותטמא אף את זה הנוגע שלא כנגד הנקב! ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003ר' יוסי\u0004 ש\u0003טומאה טמונה אינה בוקעת\u0004 ועולה.","\u0003ומנא תימרא\u0004 \u0005[ומנין אתה אומר\u0006 זאת\u0005]?\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003תיבת המגדל\u0004 (מגירה בארון) הנמצא בתוך הבית, \u0003שיש בה\u0004 עצמה חלל ששיעורו הוא כ\u0003פותח טפח\u0004 (טפח על טפח בגובה טפח), \u0003ו\u0004אולם \u0003אין ביציאתה\u0004 (בחלק המגירה הנשלף החוצה) שיעור של \u0003פותח טפח,\u0004 אם היתה \u0003טומאה בתוכה\u0004 של המגירה, וכגון שהיה בה כזית מן המת — אין המגירה חוצצת בעד הטומאה, ולכך \u0003הבית טמא.\u0004 ואם ישנה \u0003טומאה ב\u0004תוך ה\u0003בית\u0004 — כל \u0003מה שבתוכה\u0004 של המגירה הריהו \u0003טהור,\u0004 שכן אין בפתח המגירה שיעור כטפח על טפח.","וטעם הדבר: \u0003מפני שדרך טומאה\u0004 הוא \u0003לצאת\u0004 ממקומה, ולכך ודאי שטומאה הנמצאת בתוך המגירה תצא לתוך הבית ותטמאו, ולכן אף כאשר הטומאה בתוך המגירה הריהי מטמאה את כל הבית. \u0003ו\u0004אולם \u0003אין דרך\u0004 ה\u0003טומאה ליכנס,\u0004 שאין דרך הטומאה שבבית להיכנס אל החלל הסגור שבתוכו, כמגירה זו. ולכך אם הטומאה בבית, כל מה שבמגירה טהור. שכיון שהמגירה נתונה בתוך ארון שיש בו ארבעים סאה, והריהו נחשב לאוהל, אף המגירה נחשבת כן, כיון שהיא קבועה בו.","\u0003ור' יוסי מטהר\u0004 את הבית בזמן שהטומאה נמצאת בתוך המגירה, \u0003מפני\u0004 שאין זה בהכרח שהטומאה תטמאה לכשתצא ממנה, \u0003ש\u0004הרי \u0003יכול הוא להוציאה\u0004 מן המגירה לא בשיעור המטמא, אלא \u0003לחצאין, או\u0004 שיכול הוא \u0003לשורפה במקומה,\u0004 בתוך המגירה.","\u0003וקתני סיפא\u0004 \u0005[ושנה בסוף\u0006 אותה משנה\u0005]\u0006 שאם \u0003העמידה\u0004 את הארון \u0003ב\u0004תוך ה\u0003פתח\u0004 של הבית, \u0003ופתחה\u0004 של הארון פונה \u0003לחוץ\u0004 מן הבית, ולא אל תוך הבית, אם היתה \u0003טומאה בתוכה\u0004 של הארון — כל הנמצא בתוך \u0003הבית\u0004 הריהו \u0003טהור.\u0004 שכן כל הטומאה יוצאת אל מחוץ לבית. ואם היתה \u0003טומאה בבית\u0004 — כל \u0003מה שבתוכה\u0004 של הארון הריהו \u0003טהור,\u0004 כיון שאין סופה של הטומאה להיכנס אל הארון."],["\u0003ותני עלה\u0004 \u0005[ושנויה\u0006 \u0005עליה,\u0006 על אותה הלכה שבמשנה ש\u0003ר' יוסי מטהר.\u0004 ויש לברר: \u0003אהייא\u0004 \u0005[על מה,\u0006 על איזו הלכה במשנה\u0005]\u0006 מוסבים דברי ר' יוסי? \u0003אילימא אסיפא\u0004 \u0005[אם תאמר על הסוף],\u0006 בדינו של הארון שהעמידו בפתח הבית — והרי \u0003תנא קמא נמי טהורי קא מטהר\u0004 \u0005[התנא הראשון גם כן הוא מטהר]\u0006 במקרה זה!","\u0003אלא\u0004 צריך לומר \u0003דקאמר תנא קמא\u0004 \u0005[שמה שאמר התנא הראשון]\u0006 במגירה שבתוך הארון הנמצא בבית, שאם היתה \u0003טומאה בתוכה\u0004 של המגירה — \u0003הבית טמא, אי\u0004 \u0005[או]\u0006 \u0003משום\u0004 ש\u0003דרך טומאה לצאת, ואי\u0004 \u0005[או]\u0006 \u0003משום\u0004 שהוא סבור כי \u0003טומאה טמונה בוקעת,\u0004 \u0003ו\u0004כנגד זה \u0003קאמר ליה\u0004 \u0005[אמר לו]\u0006 \u0003ר' יוסי: ודקאמרת\u0004 \u0005[ו\u0006מה \u0005שאתה אומר]\u0006 כי \u0003דרך טומאה לצאת\u0004 — הרי אין זה הכרח, שהרי \u0003יכול הוא להוציאה לחצאין או לשורפה במקומה, ודקאמרת\u0004 \u0005[ו\u0006מה \u0005שאמרת]\u0006 כי \u0003טומאה טמונה בוקעת\u0004 — \u0003טומאה טמונה\u0004 לדעתו \u0003אינה בוקעת.\u0004 הרי נמצאנו למדים לשיטת ר' יוסי שטומאה טמונה אינה בוקעת ועולה.","למעלה התבררה שיטת ר' יוסי בדין טומאה טמונה. \u0003ו\u0004בענין זה \u0003רמי\u0004 \u0005[משליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003ר' יוסי\u0004 על דברי \u0003ר' יוסי,\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכלב שאכל\u0004 מ\u0003בשר\u0004 האדם ה\u0003מת,\u0004 והרי בשר המת נמצא בתוכו, \u0003ומת הכלב\u0004 ההוא, \u0003ו\u0004הריהו \u0003מוטל על האסקופה\u0004 (מפתן הדלת), באופן שצווארו ופיו פונים לצד הבית פנימה. \u0003ר' מאיר אומר: אם יש ב\u0004חלל שבתוך \u0003צוארו\u0004 של הכלב כשיעור \u0003פותח טפח\u0004 (טפח על טפח בגובה טפח) — הרי זה \u0003מביא את הטומאה\u0004 אל תוך הבית. שכן חלקו העליון של הכלב מאהיל על הטומאה הנמצאת בתוך גופו, ויוצאת הטומאה מבעד לצווארו ופיו של הכלב אל תוך הבית. \u0003ואם לאו,\u0004 שאין בצווארו של הכלב כשיעור זה, והרי איפוא אין בגופו של הכלב טומאת אוהל — \u0003אינו מביא את הטומאה\u0004 אל תוך הבית.","ר' יוסי אומר: \u0003רואין\u0004 (בוחנים) היכן בדיוק בפתח נמצאת הטומאה שבתוך גופו של הכלב, שאם היא נמצאת \u0003מכנגד השקוף\u0004 (המשקוף) \u0003ולפנים\u0004 (פנימה, כלפי הבית) — \u0003הבית טמא,\u0004 ואם היא נמצאת \u0003מכנגד השקוף ולחוץ\u0004 — \u0003הבית טהור.\u0004","\u0003ר' אלעזר אומר:\u0004 בוחנים אנו באיזה אופן מונח הכלב על מפתן הדלת, שאם היה \u0003פיו\u0004 של הכלב נתון \u0003לפנים\u0004 הבית, ואחוריו וכן הטומאה, בחלק שבחוץ — \u0003הבית טהור,\u0004 ואם היה \u0003פיו לחוץ\u0004 הבית, וחלקו האחורי אל תוך הבית — \u0003הבית טמא,\u0004 וטעם הדבר: \u0003מפני שטומאה יוצאה דרך שוליו,\u0004 דרך אחוריו ולא דרך פיו.","\u0003ר' יהודה בן בתירא אומר: בין כך ובין כך,\u0004 בין כאשר פיו לפנים ובין כאשר פיו לחוץ — \u0003הבית טמא.\u0004 שכן הטומאה יוצאת הן דרך פיו והן דרך בית הרעי.","ויש לברר את דברי ר' יוסי האומר שאם הטומאה נמצאת מכנגד המשקוף ולפנים שהבית טמא, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 על מה ששנינו לפני כן בשיטת ר' מאיר האומר שאם \u0003אין בצוארו\u0004 של הכלב שיעור של \u0003פותח טפח\u0004 שהבית טהור, \u0003קאי\u0004 \u0005[עומד,\u0006 מתייחס\u0005]\u0006 \u0003ר' יוסי\u0004 בדבריו, ואומר שאם הטומאה שבתוך הכלב נמצאת כנגד חלק המשקוף ולפנים שהבית טמא, גם אם אין בצווארו של הכלב שיעור פותח טפח העושה אותו לאוהל, שהרי הבית הוא שמאהיל על הטומאה (אף שהיא טומאה טמונה).","\u0003ו\u0004מעתה \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי לדעת ר' יוסי \u0003טומאה טמונה בוקעת,\u0004 ושלא כשיטת ר' יוסי המוזכרת למעלה שאין טומאה טמונה בוקעת ועולה!","\u0003אמר רבא\u0004 בדחיה: ר' יוסי אכן סבור כי טומאה טמונה אינה בוקעת ועולה. ומה שאמר ר' יוסי \"רואין את הטומאה מכנגד המשקוף\", ש\u0003רואין את חלל\u0004 מקומה של \u0003הטומאה קתני\u0004 \u0005[הוא\u0006 ש\u0005שנה,\u0006 התכוין\u0005].\u0006 \u0003ור' יוסי בתרתי פליג\u0004 \u0005[בשני\u0006 דברים \u0005חולק]\u0006 על ר' מאיר, \u0003וקאמר ליה\u0004 \u0005[והוא אומר לו]\u0006 \u0003לר' מאיר\u0004 כך: זה \u0003דקאמרת\u0004 \u0005[שאתה אומר]\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003יש בצוארו\u0004 של הכלב שיעור \u0003פותח טפח\u0004 הריהו \u0003מביא את הטומאה\u0004 לבית, גם כאשר הוא בצד החיצון של מפתן הדלת, \u0003אנן בתר\u0004 \u0005[אנחנו אחר]\u0006 \u0003חללה אזלינן\u0004 \u0005[אנו הולכים].\u0006","\u0003ודקא אמרת\u0004 \u0005[וזה שאתה אומר]\u0006 שאם הכלב מוטל על מפתן \u0003הבית כולו,\u0004 ואפילו אם הוא בחלק החיצוני של המפתן, שהבית \u0003טמא\u0004 — לא כן הוא. אלא רק אם מקום הטומאה שבכלב נמצא \u0003מכנגד השקוף ולפנים\u0004 — \u0003הבית טמא,\u0004 אבל אם מקום הטומאה שבכלב נמצא \u0003מכנגד השקוף ולחוץ\u0004 — \u0003הבית טהור.\u0004","ומוסרים כי \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא מתני לה בהדיא\u0004 \u0005[היה שונה אותה,\u0006 את המשנה \u0005במפורש\u0006 כהסברו של \u0005רבא\u0006\u0005],\u0006 שכן היה שונה, \u0003ר' יוסי אומר: רואין את חלל הטומאה\u0004 אם הוא מכנגד המשקוף ולפנים — הבית טמא.","בעמוד הקודם התברר כי לדעת ר' יוסי אף המאהיל נקרא \"נוגע\" וטומאת אהל וטומאת מגע הריהן שם אחד. ואולם מן המשנה שהובאה במהלך הסוגיה למדנו כי הנוגע בחתיכת בשר מן המת ששיעורה כחצי זית ובאותה עת דבר מסויים האהיל עליו ועל חתיכת בשר אחרת מן המת שאף שיעורה הוא כחצי זית, שאין שתי טומאות אלה מצטרפות. הרי איפוא שיש תנא החולק על ר' יוסי וסבור כי אין המאהיל נקרא \"נוגע\", \u0003ו\u0004לכך שואלים: \u0003מאן\u0004 \u0005[מי]\u0006 ה\u0003תנא דפליג עליה\u0004 \u0005[שחולק עליו]?\u0006 ומשיבים: \u0003ר' שמעון הוא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר:\u0004"],["המת שאמרו שמטמא הריהו בבשרו (ובלבד שיש בו שיעור כזית) ובאבר (שלם), ובעצמותיו (בשיעור כרובע) וברוב מנין ובנין שלו. וכל אלה מטמאים באחת משלושת אופנים: במגע, במשא, ובאוהל. ואולם יש \u0003שלש טומאות\u0004 ה\u0003פורשות מן המת,\u0004 שרק \u0003שתים\u0004 מדרכי ההיטמאות נוהגות \u0003בכל אחת\u0004 מהן, \u0003ו\u0004אולם דרך ההיטמאות ה\u0003שלישית אין בהן.\u0004 ומפרטים: \u0003ואלו הן: מלא תרווד\u0004 (כף גדולה שיש בה שיעור מלוא חפניים) \u0003רקב\u0004 מבשר המת, \u0003ועצם\u0004 מן המת ששיעורה הוא \u0003כשעורה, ו\u0004אבני ה\u0003גולל ו\u0004ה\u0003דופק\u0004 המשמשות לקבורת המת.","\u0003מלא תרווד רקב\u0004 — אמנם \u0003מטמא במשא ובאהל, ואינו מטמא במגע,\u0004 שהרי מאחר שהרקב הוא אוסף פירורים, אין אפשרות לגעת בכולו כאחת. \u0003והיכן\u0004 נוהגת טומאת \u0003מגעו\u0004 של המת בשלוש הטומאות הללו? \u0003עם אחת מהן\u0004 מהשתים האחרות (עצם כשעורה, וגולל \u0003ודופק).\u0004","\u0003עצם כשעורה\u0004 — אמנם \u0003מטמא במשא ובמגע, ו\u0004אולם \u0003הוא\u0004 \u0003אינו מטמא באהל,\u0004 הלכה למשה מסיני. \u0003והיכן\u0004 נוהגת טומאת \u0003אהלו\u0004 של המת בשלוש הטומאות הללו? \u0003עם אחת מהן,\u0004 מהשתים האחרות (מלא תרוד רקב וגולל ודופק).","ה\u0003גולל ו\u0004ה\u0003דופק\u0004 — אמנם \u0003מטמא במגע ובאהל, ו\u0004אולם \u0003אינו מטמא במשא,\u0004 הלכה למשה מסיני. \u0003והיכן\u0004 נוהגת טומאת \u0003משאו\u0004 של המת בשלוש הטומאות הללו? \u0003עם אחד מהן\u0004 מהשתים האחרות (מלוא תרווד רקב ועצם כשעורה). הרי נמצאנו למדים כי לדעת ר' שמעון מלוא תרווד רקב מטמא באוהל אך לא במגע, ומכאן שלדעתו אין המאהיל נקרא \u0003נוגע, ושלא כר' יוסי.\u0004","שנינו במשנתנו כי הנוגע ב\u0003קולית נבלה וקולית השרץ\u0004 \u0003כשהן סתומות (ואי אפשר לגעת במוח שבתוכן) — הריהו טהור. שכן אין עצמותיהן כשלעצמן מטמאות. ובענין זה עוד\u0004 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא על הכתוב בטומאת נבילה \"הנוגע בנבלתה יטמא עד הערב\" (ויקרא יא, לט). ובאה המלה \u0003\"בנבלתה\"\u0004 להדגיש: דווקא זה הנוגע בנבלתה, \u0003ולא\u0004 זה הנוגע \u0003בקולית סתומה.\u0004","מעתה יש לשאול: \u0003יכול\u0004 יהא כן הדין \u0003אפילו\u0004 הנוגע בקולית ש\u0003ניקבה?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"הנוגע\u0004 בנבלתה \u0003יטמא\",\u0004 ללמדנו: דווקא \u0003את\u0004 זה הנוגע במה \u0003שאפשר ליגע\u0004 בו — הרי הוא \u0003טמא, ו\u0004אולם \u0003את\u0004 הנוגע בדבר \u0003שאי אפשר ליגע\u0004 בו, וכגון בקולית שאי אפשר לגעת במוח שבתוכה — הריהו \u0003טהור.\u0004 שאף הנוגע ב\"שומר\" (כקולית זו השומרת על המוח שבתוכה) בדבר שאי אפשר לגעת בו, אין הוא נטמא בכך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לאביי\u0004 בשאלה: \u0003אלא מעתה,\u0004 שאין מטמאת הנגיעה ב\"שומר\" של דבר שאי אפשר לגעת בו, גם \u0003בהמה\u0004 נבילה, כשהיא עדיין נתונה \u0003בעורה\u0004 (בטרם הופשטה ממנו), \u0003לא תטמא\u0004 שהרי בשלב זה אי אפשר לגעת בבשר, ואילו הנגיעה היא רק ב\"שומר\", הוא העור! השיב לו אביי: \u0003פוק חזי\u0004 \u0005[צא\u0006 ו\u0005ראה]\u0006 \u0003כמה נקבים יש בה\u0004 בבהמה (פה, אף ועיניים) שדרכם אפשר לגעת בבשר.","וכיוצא בזה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא: אלא מעתה\u0004 שאין מטמאת הנגיעה ב\"שומר\" \u0003דבר שאי אפשר לגעת בו,\u0004 נגיעה ב\u0003כוליא\u0004 \u0005[כליה]\u0006 המכוסה כולה \u0003בחלבה לא תטמא!\u0004 השיב לו רבא: אין זה נחשב כדבר שאי אפשר לגעת בו, שהרי \u0003תא חזי\u0004 \u0005[בוא\u0006 ו\u0005ראה]\u0006 \u0003כמה חוטין נמשכין הימנה\u0004 מהכליה אל מחוצה לה, וניתן לגעת בהם.","שנינו במשנתנו שישנה הבחנה בדין טומאה בין קולית הנבילה והשרץ הסתומות לבין הנקובות, ובענין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אושעיא:\u0004 אם הבעלים \u0003חישב עליה לנוקבה, ו\u0004עדיין \u0003לא ניקבה,\u0004 \u0003מהו\u0004 דינה של קולית זו לענין טומאה. האם נחשבת היא כסתומה או כנקובה. וצדדי השאלה: האם דבר ה\u0003מחוסר נקיבה כמחוסר מעשה דמי\u0004 \u0005[נחשב],\u0006 והרי קולית זו דינה כסתומה, \u0003או לא?\u0004","\u0003הדר\u0004 \u0005[חזר]\u0006 רב אושעיא ו\u0003פשטה\u0004 \u0005[פתרה]\u0006 לשאלתו: \u0003מחוסר נקיבה לאו\u0004 \u0005[לא]\u0006 \u0003כמחוסר מעשה דמי\u0004 \u0005[נחשב],\u0006 ולכן גם אם רק חשב עליה לנוקבה, הרי היא כנקובה.","\u0003ביצת השרץ המרוקמת\u0004 שהתחיל להתרקם בה עובר — אף שהשרץ שבתוכה הינו טמא, מכל מקום הנגיעה בביצה הרי היא \u0003טהורה,\u0004 שכן בשלב הזה אי אפשר לגעת בשרץ עצמו. ואולם אם \u0003ניקבה\u0004 הביצה, ואפילו בנקב \u0003כל שהוא\u0004 — הנוגע בביצה הריהו \u0003טמא.\u0004 מין ה\u0003עכבר\u0004 הגדל מהקרקע, הנמצא בשלב \u0003ש\u0004בו \u0003חציו\u0004 האחד הוא \u0003בשר, ו\u0004אילו \u0003חציו\u0004 האחר \u0003הוא\u0004 \u0003אדמה, הנוגע ב\u0004חלק ה\u0003בשר\u0004 — הריהו \u0003טמא,\u0004 ואילו הנוגע \u0003ב\u0004חלק ה\u0003אדמה\u0004 — הריהו \u0003טהור. ר' יהודה אומר: אף הנוגע ב\u0004חלק ה\u0003אדמה שכנגד הבשר\u0004 — הריהו \u0003טמא.\u0004","שנינו במשנתנו כי ביצת השרץ המרוקמת שניקבה מטמאת את הנוגע בה. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא נאמר \"אלה הטמאים לכם בכל השרץ כל הנוגע בהם במותם יטמא עד הערב\" (ויקרא יא, לא), ובאה המלה \u0003\"הטמאים\"\u0004 — \u0003לרבות\u0004 בכלל טומאה זו אף \u0003את\u0004 \u0003ביצת השרץ וקולית השרץ. יכול\u0004 יהא","כך הדין \u0003אפילו לא ריקמה\u0004 הביצה? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"השרץ\"\u0004 — \u0003מה שרץ\u0004 הריהו דבר \u0003ש\u0004כבר \u0003רקם, אף ביצת השרץ\u0004 המטמאת אינה אלא זו \u0003ש\u0004כבר \u0003רקמה. יכול\u0004 יהא הדין שביצת השרץ שרוקמה שהיא","מטמאת \u0003אפילו\u0004 אם \u0003לא ניקבו?\u0004 לכך \u0003תלמוד לומר\u0004 \u0003\"הנוגע\u0004 בהם במותם \u0003יטמא\",\u0004 להורות: נגיעה \u0003את\u0004 זה \u0003שאפשר ליגע\u0004 בו — הריהו \u0003טמא, ואת\u0004 זה \u0003שאי אפשר ליגע\u0004 בו — הריהו \u0003טהור.\u0004","\u0003וכמה\u0004 הוא \u0003נקיבתה,\u0004 שעל ידה הנוגע בביצת ובקולית השרץ הריהו נטמא? \u0003כחוט השערה, ש\u0004כן \u0003אפשר ליגע\u0004 בדבר שבתוך הביצה ובתוך הקולית \u0003כ\u0004אדם ש\u0003חוט השערה\u0004 נכנס מבעד לנקב כזה.","שנינו במשנתנו כי ה\u0003עכבר שחציו\u0004 בשר וחציו אדמה, הנוגע בחלק הבשר שבו נטמא בכך. ובענין זה \u0003אמר ר' יהושע בן לוי: והוא\u0004 (ובלבד) \u0003שהשריץ\u0004 (שנוצר חציו הבשרי של העכבר) \u0003על פני כולו\u0004 (לכל אורכו, מראשו ועד רגליו). שכל הנוגע בצד זה של השרץ נטמא, שכל שבצד זה נחשב כשרץ. \u0003איכא דמתני לה אסיפא\u0004 \u0005[יש ששונים אותה על סוף\u0006 משנתנו\u0005],\u0006 ש\u0003ר' יהודה אומר: אף הנוגע באדמה שכנגד בשר\u0004 — \u0003טמא,\u0004 ועל כך \u0003אמר ר' יהושע בן לוי: והוא שהשריץ על פני כולו.\u0004","ומעירים: \u0003מאן דמתני לה ארישא\u0004 \u0005[מי ששונה את\u0006 דברי ר' יהושע \u0005בן לוי\u0006 \u0005על ראש\u0006 המשנה\u0005],\u0006 שסבור הוא כי הנוגע בחלק הבשר של העכבר נטמא רק אם היה חלק הבשר לכל אורכו של העכבר — \u0003כל שכן\u0004 שכך הוא הדין \u0003אסיפא\u0004 \u0005[על סוף\u0006 המשנה, על דברי ר' יהודה\u0005],\u0006 שבוודאי שהנוגע בחלק האדמה שכנגד הבשר נטמא רק אם החלק הבשר של העכבר היה על כל אורכו. \u0003ו\u0004אולם \u0003מאן דמתני לה אסיפא\u0004 \u0005[מי ששונה אותם על סוף\u0006 המשנה\u0005]\u0006 — דווקא הנוגע בחלק האדמה שכנגד הבשר נטמא רק כאשר השריץ העכבר על פני כולו, \u0003אבל\u0004 בדין הנזכר ב\u0003רישא\u0004 \u0005[ראש\u0006 המשנה\u0005]\u0006 — הנוגע בחלק הבשר הריהו נטמא, \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא השריץ\u0004 על פני כולו.","ועוד בדין טומאת העכבר. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מתוך שנאמר\u0004 בתורה בכלל שמונת השרצים \u0003\"עכבר\"\u0004 (\"וזה לכם הטמא בשרץ השורץ על הארץ החולד והעכבר והצב למינהו\". ויקרא יא, כט), \u0003שומע אני\u0004 שמטמא \u0003אפילו עכבר שבים, ש\u0004גם \u0003שמו\u0004 הוא \u0003\"עכבר\". ו\u0004לכאורה דבר הנלמד מן \u0003ה\u0004\u0003דין\u0004 (היקש) \u0003הוא: טימא בחולדה וטימא בעכבר, מה חולדה\u0004 המטמאת היא דווקא \u0003מין הגדל על הארץ, אף עכבר\u0004 המטמא הוא דווקא \u0003מין הגדל על הארץ,\u0004 ואין עכבר של ים מטמא.","\u0003או כלך\u0004 (הלך) \u0003לדרך זו: טימא בחולדה וטימא בעכבר, מה חולדה\u0004 המטמאת הריהי \u0003כל ששמה\u0004 הוא \u0003\"חולדה\". אף עכבר\u0004 המטמא הוא \u0003כל ששמו \"עכבר\",\u0004 ובכלל זה \u0003אפילו עכבר שבים\u0004 הריהו מטמא, \u0003ש\u0004כן \u0003שמו \"עכבר\".\u0004 לכך \u0003תלמוד לומר\u0004 \u0003\"על הארץ\"\u0004 — זה שעל הארץ, של יבשה, ואין עכבר של ים מטמא.","ועדיין יש לשאול: \u0003אי\u0004 \u0005[אם]\u0006 למדים אנו מן הכתוב \u0003\"על הארץ\", יכול\u0004 שכך בא הכתוב ללמדנו: שאם היה העכבר \u0003על הארץ,\u0004 בין עכבר של יבשה ובין עכבר של ים — \u0003יטמא,\u0004 ואולם אם \u0003ירד לים,\u0004 בין עכבר של יבשה ובין עכבר של ים — \u0003לא יטמא,\u0004"],["לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בטומאת השרצים \"וזה לכם הטמא בשרץ השורץ על הארץ החולד והעכבר והצב למינהו\" (ויקרא יא, כט), ובאה המלה היתירה \u0003\"השורץ\"\u0004 להורות כי טומאת השרצים נוהגת ב\u0003כל מקום ש\u0004יכול אחד השרצים המנויים בפרשה זו שיהא \u0003שורץ.\u0004 וכיון שאף בים השרץ שט לו, והריהו איפוא שורץ גם בים, שוב אין לומר שלא יטמא בים. ולכך ודאי שהלימוד מ\"על הארץ\" בא למעט את עכבר הים מטומאת השרץ.","ודנים עוד: \u0003או\u0004 שמא נאמר כי הכתוב \u0003אינו\u0004 בא לדרשה זו \u0003אלא\u0004 לדרשה אחרת, שכך למדים אנו מן ההדגשה \"השורץ\": \u0003כל המשריץ\u0004 הפרה ורבה מזיווג שבין זכר ונקבה — \u0003יטמא,\u0004 ואילו זה \u0003שאין משריץ,\u0004 שאינו נוצר מזיווג שבין זכר ונקבה, וכגון שנוצר מן האדמה — \u0003לא יטמא,\u0004 ומכאן \u0003אוציא\u0004 מכלל השרצים המטמאים את ה\u0003עכבר שחציו בשר וחציו אדמה, שאין\u0004 זה \u0003פרה ורבה\u0004 ואינו משריץ, ונאמר כי הכתוב \"על הארץ\" לא בא למעט אלא כשירד העכבר (ואפילו זה עכבר יבשה) לים, ואילו עכבר שבים הנמצא על היבשה הריהו מטמא!","\u0003ו\u0004לכאורה דבר זה מן ה\u0003דין\u0004 (היקש) \u0003הוא\u0004 נלמד: שכן הכתוב \u0003טימא בחולדה ו\u0004כמו כן הכתוב \u0003טימא בעכבר, מה\u0004 טומאה ב\u0003חולדה\u0004 — הריהי נוהגת ב\u0003כל ששמה חולדה, אף\u0004 טומאת \u0003עכבר\u0004 — הריהי נוהגת ב\u0003כל ששמו עכבר,\u0004 ומעתה \u0003אביא\u0004 בכלל טומאת העכבר גם את ה\u0003עכבר שחציו בשר וחציו אדמה.\u0004","\u0003או\u0004 שמא \u0003כלך\u0004 (הלך) \u0003לדרך זו: מה\u0004 טומאת \u0003חולדה\u0004 — נוהגת רק בזו ש\u0003פרה ורבה, אף\u0004 טומאת \u0003עכבר\u0004 — נוהגת רק בזה ש\u0003פרה ורבה,\u0004 ויצא מכלל זה עכבר שחציו בשכר וחציו אדמה, שאינו פרה ורבה. לכך \u0003תלמוד לומר\u0004 \"וזה לכם הטמא בשרץ השורץ על הארץ\", ובא הכתוב \"בשרץ\" ללמדנו שאף העכבר שחציו בשר וחציו אדמה הריהו בכלל טומאת העכבר. ומכאן שהכתוב \"השורץ\" המרבה בא ללמד שהריהו מטמא בכל מקום שהוא שורץ, ואף זה שירד לים. ואילו הכתוב \"על הארץ\" הממעט בא ללמדנו שאין עכבר הים בכלל טומאת עכבר.","\u0003אמר ליה ההוא מדרבנן\u0004 \u0005[לו אחד מהחכמים]\u0006 \u0003לרבא:\u0004 \u0003אימא\u0004 \u0005[אמור]\u0006 באופן שונה, שהמלה המרבה \u0003\"בשרץ\"\u0004 באה \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003עכבר שחציו בשר וחציו אדמה,\u0004 וכן המלה המרבה \u0003\"השורץ\"\u0004 באה לרבות \u0003כל שהוא שורץ\u0004 (נע) \u0003ואפילו עכבר שבים, ואי\u0004 \u0005[ואם]\u0006 \u0003משום\u0004 שנאמר כתוב ממעט \u0003\"על הארץ\",\u0004 אני אומר כי בא ללמדנו שדווקא בהיותו \u0003על הארץ\u0004 — \u0003יטמא,\u0004 ואם \u0003ירד לים\u0004 — \u0003לא יטמא!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לאותו חכם בדחיית דבריו: \u0003ו\u0004הרי \u0005אין הדברים מסתברים, שכן\u0006 \u0003מאחר דשויתיה\u0004 \u0005[שעשית אותו]\u0006 לפי שיטתך \u0003לים מקום טומאה,\u0004 שכן לדבריך עכבר שבים מטמא, שוב אין מקום לומר שעכבר שירד לים לא יטמא, שכן \u0003מה\u0004 זה משנה \u0003לי\u0004 אם הוא נמצא \u0003הכא\u0004 \u0005[כאן,\u0006 ביבשה\u0005],\u0006 \u0003מה לי\u0004 זה משנה אם הוא נמצא \u0003הכא\u0004 \u0005[כאן,\u0006 בים\u0005],\u0006 מאחר ששני המקומות הינם מקומות טומאה.","ומקשים עוד על דברי הברייתא: כיצד דורשת הברייתא את הכתוב הממעט \"על הארץ\" למעט מין עכבר שבים, \u0003ו\u0004הלא \u0003האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"על הארץ\" מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 למיעוט אחר, \u0003להוציא\u0004 (למעט) מטומאת שרצים מקרה של \u0003ספק טומאה צפה.\u0004 שאם יש ספק לאדם אם אמנם נגע בשרץ שצף על פני המים, הריהו טהור, גם אם התרחש ספק זה ברשות היחיד. שכן \u0003אמר רב יצחק בר אבדימי:\u0004 נאמר \u0003\"על הארץ\"\u0004 — \u0003להוציא\u0004 (למעט) \u0003ספק טומאה צפה!\u0004","ומשיבים: \u0003תרתי\u0004 \u0005[שני]\u0006 \u0003\"על הארץ\" כתיבי\u0004 \u0005[כתובים]\u0006 בפרשיה זו, האחד בא למעט ספק טומאה צפה, והאחר בא למעט עכבר שבים.","ועוד בדיני טומאת שמונת השרצים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הנאמר \u0003\"הצב למינהו\"\u0004 (ויקרא יא, כט) — \u0003להביא\u0004 (לרבות) לטומאה \u0003את\u0004 \u0003הערוד וכן\u0004 את השרצים \u0003ה\u0004נקראים \u0003נפילים ו\u0004את שרץ ה\u0003סלמנדרא. ו\u0004מתוך שהוזכרה הסלמנדרה, שמקובל בה שהריהי נוצרת מן האש, מסופר כי","\u0003כשהיה ר' עקיבא מגיע לפסוק זה\u0004 שבפרשת השרצים המטמאים, היה \u0003אומר: \"מה רבו מעשיך ה' \"\u0004(תהלים קד, כד)! \u0003יש לך בריות\u0004 ה\u0003גדלות בים ויש לך בריות\u0004 ה\u0003גדלות ביבשה,\u0004 אלה \u0003ש\u0004גדלות \u0003בים\u0004 — \u0003אילמלי\u0004 (אילו) היו \u0003עולות ביבשה,\u0004 היו \u0003מיד מתות.\u0004 אלו \u0003ש\u0004גדלות \u0003ביבשה\u0004 — \u0003אילמלי\u0004 (אילו) היו \u0003יורדות לים,\u0004 היו \u0003מיד מתות.\u0004","וכמו כן, \u0003יש לך בריות\u0004 ה\u0003גדלות באור\u0004 (אש), \u0003ויש לך בריות\u0004 ה\u0003גדלות באויר,\u0004 אלה \u0003ש\u0004גדלות \u0003באור\u0004 — \u0003אילמלי\u0004 (אילו) היו \u0003עולות לאויר,\u0004 היו \u0003מיד מתות.\u0004 וכן אלה \u0003ש\u0004גדלות \u0003באויר\u0004 — \u0003אילמלי\u0004 (אילו) היו \u0003יורדות לאור,\u0004 היו \u0003מיד מתות,\u0004 הרי זה \u0003\"מה רבו מעשיך ה' \".\u0004","ועוד בעניינם של יצורים החיים רק בסביבה אחת. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל\u0004 בעל חיים \u0003שיש\u0004 כמותו \u0003ביבשה,\u0004 בדומה לו \u0003יש\u0004 גם \u0003בים, חוץ מן החולדה,\u0004 הנמצאת ביבשה בלבד. \u0003אמר ר' זירא: מאי קראה\u0004 \u0005[מה המקרא]\u0006 המלמד על כך? \u0003\"האזינו כל יושבי חלד\"\u0004 (שם מט, ב), שכן היבשה נקראת \"חלד\" על שום שהיא מקומה הבלעדי של החולדה.","ועוד בעניינם של יצורים החיים רק במקום אחד \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: ביברי\u0004 \u0005[הבונים]\u0006 באיזור העיר \u0003נרש, אינן מן הישוב\u0004 שהם חיים רק במים ולא ביבשה.","כיון שהוזכרה העיר נרש, מביאים עוד בעניינה של עיר זו, שכן \u0003אמר רב פפא: בשמתא\u0004 \u0005[בנידוי]\u0006 יהיו אנשי העיר \u0003נרש,\u0004 שרשעים הם כולם, \u0003תרביה משכיה ואליתיה\u0004 \u0005[חלבה, עורה, ואלייתה,\u0006 כלומר, כל סוגי האנשים שבה, הגדולים והקטנים\u0005].\u0006 ועוד בעניינה של העיר נרש: \u0003\"ארץ ארץ ארץ שמעי דבר ה' \"\u0004(ירמיהו כב, כט) — \u0003אמר רב פפא:\u0004 פסוק זה ראוי להיאמר בבני העיר נרש, ש\u0003לא אבה נרש שמוע דבר ה'.\u0004","ועוד: \u0003אמר רב גידל,\u0004 \u0003אמר רב:\u0004 אם \u0003נרשאה נשקיך\u0004 \u0005[בן נרשאה נישק אותך]\u0006 — \u0003מני ככיך\u0004 \u0005[מנה\u0006 את \u0005שיניך]\u0006 אם לא חסרו מתוך נשיקה זו, מפני שגנבים הם. ואם \u0003נהר פקודאה לוייך\u0004 \u0005[בן נהר פקודא ליווה אותך]\u0006 בדרך — הרי זה \u0003מ\u0004פני \u0003גלימא שפירא דחזי עלך\u0004 \u0005[גלימה יפה שראה עליך],\u0006 והוא חפץ לקחתה ממך. אם \u0003פומבדיתאה לוייך\u0004 \u0005[בן פומבדיתא ליווה אותך]\u0006 בדרך — \u0003אשני אושפיזך\u0004 \u0005[שנה\u0006 את \u0005מלונך],\u0006 מפני שיש לחשוש בו שיבוא לגנוב ממך דברים.","ושבים לעניינם של יצורים שונים. \u0003אמר רב הונא בר תורתא: פעם אחת הלכתי לוועד, וראיתי\u0004 שם שנוהגים בני המקום שיהא \u0003נחש שהוא כרוך על הצב,\u0004 כדי שיזדווגו זה עם זה. \u0003לימים יצא ערוד\u0004 (הנושך וממית בני אדם) \u0003מביניהם.\u0004","\u0003וכשבאתי לפני ר' שמעון החסיד\u0004 וסיפרתי לו זאת, \u0003אמר לי\u0004 כהסבר לדבר שיצא הערוד מתוך זיווג זה: \u0003אמר הקדוש ברוך הוא: הם,\u0004 אנשי אותו המקום \u0003הביאו\u0004 (גרמו שתיווצר) \u0003בריה שלא בראתי בעולמי,\u0004 כלומר, שרצו ליצור יצור כלשהו מזיווג זה של נחש וצב. \u0003אף אני אביא עליהם בריה שלא בראתי בעולמי,\u0004 כערוד הזה, שייענשו על ידו.","ושואלים על המסופר: כיצד מזיווגם של הנחש והצב יצא ערוד, \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003כל\u0004 בעלי החיים השונים \u0003שתשמישן\u0004 (דרך הזדווגותם) \u0003ו\u0004משך זמן \u0003עיבורן שוה\u0004 — הריהם \u0003יולדין ומגדלין זה מזה, וכל\u0004 בעלי החיים \u0003שאין תשמישן ועיבורן שוה\u0004 — \u0003אין יולדין ומגדלין זה מזה.\u0004 ואילו הצב והערוד אין משך עיבורם שווה!","\u0003אמר רב\u0004 בתשובה: לידתו של אותו ערוד לא היתה בדרך הטבע, אלא \u0003נס בתוך נס.\u0004 שהזדווגו זה לזה, ושמתוך זיווג זה נוצר בעל חיים חדש. ותוהים: \u0003האי פורענותא\u0004 \u0005[זה\u0006 הערוד, דבר \u0005פורענות]\u0006 \u0003הוא,\u0004 שהריהו ממית באנשים, ומדוע הרי זה נחשב לנס? ומשיבים: \u0003מאי\u0004 \u0005[מה]\u0006 טיבו של \u0003נס בתוך נס\u0004 זה? \u0003לפורענות\u0004 לרשעים, להענישם בכך.","\u0003האבר\u0004 של הבהמה, שיש בו בשר וגידים ועצמות, \u0003ו\u0004כן \u0003הבשר\u0004 מן הבהמה \u0003המדולדלין\u0004 (שנתלשו מן הבהמה, אך עדיין הם תלויים באופן רופף) \u0003בבהמה\u0004 — אין הם נחשבים כ\"אבר מן החי\" (לענין שיטמאו כנבילה), ואולם אם חשב על אבר ובשר זה לאכילה, הריהם נחשבים כדבר מאכל, ולכך הם \u0003מטמאין טומאת אוכלין במקומן\u0004 אם נגע בהם שרץ, ומעתה מטמאים מאכלים אחרים. \u0003ו\u0004אולם כדי שייטמאו הם \u0003צריכין הכשר\u0004 (בנתינת אחד משבעת המשקים המכשירים את האוכל לקבל טומאה)."],["ואם \u0003נשחטה הבהמה,\u0004 ולא ניתן אחד משבעת המשקים המכשירים לטומאה על האבר והבשר המדולדלים — הרי אלו \u0003הוכשרו\u0004 לקבלת טומאה \u0003בדמיה\u0004 של הבהמה הנשחטת (שהרי דם הוא אחד משבעת המשקים המכשירים לטומאה). אלה דברי ר' מאיר. ר' שמעון אומר: \u0003לא הוכשרו\u0004 לקבל טומאה בדמי השחיטה.","ואם \u0003מתה הבהמה\u0004 — \u0003הבשר\u0004 המדולדל \u0003צריך הכשר\u0004 לקבלת טומאה, שהרי הוא נחשב כבשר מן החי, וצריך הכשר כדי לטמא טומאת אוכלים. ואילו \u0003האבר\u0004 המדולדל של בהמה \u0003מטמא משום\u0004 היותו \u0003אבר\u0004 הבא \u0003מן החי,\u0004 שמטמא אדם וכלים, \u0003ו\u0004אולם \u0003אינו מטמא משום אבר\u0004 הבא מן ה\u0003נבלה.\u0004 \u0003אלה\u0004 \u0003דברי ר' מאיר. ור' שמעון מטהר.\u0004","שנינו במשנתנו שהאבר המדולדל בבהמה מטמא טומאת אוכלים, ומדייקים: \u0003טומאת אוכלין\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מטמא, ואולם \u0003טומאת נבלה\u0004 — \u0003לא\u0004 מטמא, שכן אינו נחשב כתלוש לגמרי, שמטמא אדם וכלים.","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד מדובר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר פה באיברים שנתלשו מן הבהמה והם תלויים בה באופן רופף, ואולם הם מסוגלים שיהיו \u0003מעלין ארוכה\u0004 ויחזרו ויתאחו עם גוף הבהמה — אז \u0003אפילו טומאת אוכלין נמי לא ליטמו\u0004 \u0005[גם כן שלא יטמאו]!\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר שנתלשו באופן ששוב \u0003אין\u0004 הם \u0003מעלין ארוכה\u0004 — \u0003טומאת נבלה נמי ליטמו\u0004 \u0005[גם כן יטמאו]!\u0006","ומשיבים: \u0003לעולם\u0004 מדובר באברים שנתלשו ש\u0003אין\u0004 הם \u0003מעלין ארוכה, ו\u0004טעם הדבר שאינם מטמאים בטומאת נבילה — \u0003שאני\u0004 \u0005[שונה,\u0006 מיוחדת\u0005]\u0006 היא \u0003טומאת נבלה, דרחמנא\u0004 \u0005[ש\u0006כן \u0005המקרא]\u0006 \u0003אמר\u0004 בדין טומאה זו \"ו \u0003כי יפול\u0004 מנבלתם על כל זרע זרוע\" (ויקרא יא, לז), וכוונתו: שאין נקראת \"נבלה\" אלא \u0003עד שיפול\u0004 ממש מגוף הבהמה.","ומציעים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא האומרת \u0005גם כן כך,\u0006 כהסבר זה\u0005]:\u0006 \u0003האבר והבשר המדולדלין בבהמה ומעורין\u0004 (מחוברים) בה \u0003בחוט השערה, יכול יטמאו טומאת נבלה?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \"וכי \u0003יפול\"\u0004 — \u0003עד שיפול\u0004 ממש. \u0003ואפילו הכי\u0004 \u0005[כך],\u0006 שאין האברים המדולדלים מטמאים טומאת נבילה, מכל מקום לענין \u0003טומאת אוכלין\u0004 הריהם \u0003מיטמו\u0004 \u0005[נטמאים],\u0006 שכן לענין זה הם נחשבים כאינם מחוברים לגוף הבהמה.","ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לרב חייא בר אשי,\u0004 שכן \u0003אמר רב חייא בר אשי, אמר שמואל\u0004 בדינן של ה\u0003תאנים שצמקו\u0004 (יבשו והתכווצו) בעודן \u0003באיביהן\u0004 בהיותן נתונות עדיין על העץ — אף שהן עדיין מחוברות, מכל מקום \u0003מטמאות טומאת אוכלין,\u0004 שלענין זה הן נחשבות כתלושות, \u0003ו\u0004אולם לענין דין שבת, הריהן נחשבות כמחוברות לעץ, ולכך \u0003התולש מהן בשבת חייב חטאת.\u0004 הרי איפוא שישנם דברים שלענין מסויים נחשבים כתלושים ולענין אחר הם נחשבים כמחוברים, ובדומה לזה שלמדנו בדינם של אברים המדולדלים. ומציעים:","\u0003לימא מסייע ליה\u0004 \u0005[האם אפשר לסייע לו,\u0006 לשמואל\u0005]\u0006 האומר שתאנים שצמקו הנתונות על העץ נחשבות כתלושות לענין טומאת אוכלים מברייתא זו ששנינו בה כי ה\u0003ירקות שצמקו באיביהן, כגון הכרוב והדלעת\u0004 — \u0003אין\u0004 \u0003מטמאין טומאת אוכלין,\u0004 שכן משעה שצמקו אין הם נאכלים כלל, והריהם כעץ סתם. ואולם אם \u0003קצצן\u0004 בהיותם לחים \u0003ויבשן\u0004 על מנת לעשות מהם כלים שונים (מן הדלעת היבשה) או להשתמש בהם להסקה — הריהם \u0003מטמאין טומאת אוכלין.\u0004","ותהו על הדברים: בזמן ש\u0003קצצן ויבשן סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר שהם מטמאים טומאת אוכלים, והלא אין הם \"אוכל\" כלל, שהרי \u0003עץ בעלמא\u0004 \u0005[סתם]\u0006 \u0003הוא!\u0004 \u0003ואמר ר' יצחק\u0004 בהסבר הדברים: אין הכוונה \u0003ב\u0004שקצצם כשהם כבר יבשים, אלא שקצצם כשהם לחים \u0003על מנת ליבשן.\u0004 וחידשה לנו הברייתא שאף שבסופו של דבר יהיו לעץ, כל עוד הם עדיין לחים — הם מטמאים טומאת אוכלים.","ומעתה יש לדייק: \u0003טעמא\u0004 \u0005[הטעם]\u0006 של הלכה זו הינו משום שמדובר דווקא ב\u0003כרוב ודלעת הוא,\u0004 ש\u0003כיון\u0004 ש\u0003יבשן לאו\u0004 \u0005[לא]\u0006 \u0003בני אכילה נינהו\u0004 \u0005[הם].\u0006 ומכאן נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 ב\u0003שאר פירות,\u0004 הראויים לאכילה אף כשהתייבשו וצמקו — הריהם \u0003מטמאי\u0004 \u0005[מטמאים]\u0006 בטומאת אוכלים.","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005מדובר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003יבשו\u0004 גם \u0003הן ו\u0004גם \u0003עוקציהן,\u0004 שכל הפרי כולו יבש, ולמדים אנו מן הברייתא ששאר פירות (מלבד הכרוב והדלעת) מקבלים טומאת אוכלים משום שהריהם בכלל \"אוכל\" — אין צורך להשמיענו כן, שהרי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר שהם מטמאים, שהרי הם אינם צומחים יותר! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר באופן שקצצם \u0003בלא עוקציהן\u0004 ויבשו הפירות עצמם אך לא עוקציהם. ומעתה הרינו נלמדים שלענין קבלת טומאת אוכלים הם נחשבים כתלושים, אף שלענין שבת אין הם נחשבים כתלושים. והרי זה כשיטתו של שמואל.","ודוחים: אין זו ראיה, שכן אפשר לומר \u0003כי\u0004 \u0003לעולם\u0004 מדובר שיבשו גם \u0003הן ו\u0004גם \u0003עוקציהן, ו\u0004אשר לשאלה מה החידוש שיש בדבר — \u0003קצצן על מנת ליבשן איצטריכא ליה\u0004 \u0005[הוצרך לו ללמד],\u0006 שאף שעתידים הכרוב והדלעת להיות כעץ סתם, מכל מקום כל עוד הם לחים הריהם נחשבים כאוכל, ומטמאים טומאת אוכלים.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה שלא כדברי שמואל ממה ששנינו בדינו של \u0003אילן שנפשח\u0004 (נחתך) ממנו ענף \u0003ובו פירות\u0004 — אף שהפירות עדיין לחים, \u0003הרי הן\u0004 נחשבים \u0003כתלושין\u0004 מן האילן. ואולם אם \u0003יבשו\u0004 הפירות בעודם נתונים על האילן — \u0003הרי הן\u0004 נחשבים \u0003כמחוברין,\u0004 אף שהם יבשים. ונברר: \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ב\u0003מה\u0004 שאמר התנא בראשית דבריו בענף שנתלש שהפירות שעליו נחשבים כ\u0003תלושין\u0004 — הרי זה \u0003לכל דבריהן\u0004 (ענייני הלכותיהם), בין לענין קבלת טומאת אוכלים ובין לענין איסור תלישה בשבת. ו\u0003אף\u0004 זה שאמר התנא שהפירות שהתייבשו על העץ נחשבים כ\u0003מחוברין\u0004 — הרי זה \u0003לכל דבריהן,\u0004 ואף לענין קבלת טומאת אוכלים. והרי זה שלא כדברי \u0003שמואל!\u0004","ודוחים: אין זו קושיה, שכן \u0003מידי איריא\u0004 \u0005[וכי הדברים שייכים],\u0006 אין הדברים שבתחילת הברייתא כדברים שבסופה, \u0003הא כדאיתא, והא כדאיתא\u0004 \u0005[זה כמו שישנו, וזה כמו שישנו],\u0006 שבתחילת הדברים, בדין הפירות על ענף שנחתך הריהם אמורים הן לענין טומאה והן לענין שבת. ואילו בסוף הדברים, בדין הפירות שהתייבשו על האילן, אמורים הדברים רק לענין שבת ולא לענין טומאה.","שנינו במשנתנו בדעת ר' מאיר שאם \u0003נשחטה הבהמה,\u0004 אף שעדיין לא בא כל משקה על האבר והבשר המדולדלים, הוכשרו בכך לקבל טומאה. ואילו לדעת ר' שמעון לא הוכשרו בכך. ומבררים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה \u0005עקרון\u0006 \u0005הם חלוקים]?\u0006","\u0003אמר רבה:\u0004 אין המדובר כשנזל מדם השחיטה על האבר המדולדל, אלא על גוף הבהמה בלבד. והכל סבורים שאם הוכשרה (במתן משקה עליה) ה\"יד\" (הדבר המשמש כבית אחיזה לדבר אחר, שעל ידי ה\"יד\" נישא הדבר האחר), אף הדבר הנישא על ידה הוכשר בכך. שהרי דינה של ה\"יד\" שהיא מביאה את הטומאה אל הדבר הנישא על ידה, ובדומה לכך היא מכשירה את הדבר הנישא על ידה. ואולם \u0003ב\u0004שאלה האם ה\u0003בהמה נעשית \"יד\" לאבר קמיפלגי\u0004 \u0005[חלוקים הם].\u0006 ש\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' שמעון \u0005סבור]\u0006 כי \u0003אין\u0004 ה\u0003בהמה נעשית \"יד\" לאבר\u0004 שבה, ולכך לא הוכשר האבר המדולדל בהכשר הבהמה כולה. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' מאיר, \u0005סבור]\u0006 ש\u0003בהמה נעשית יד לאבר,\u0004 ולכך הוכשר האבר בהכשר \u0003הבהמה.\u0004","\u0003אביי אמר\u0004 הסבר אחר במחלוקת ר' מאיר ור' שמעון: מדובר שלא נזל מדם השחיטה על האבר או הבשר המדולדלים אלא על גוף הבהמה בלבד, וכן הכל מודים שאין הכשר הבהמה מועיל להכשיר בה אבר מסויים, שכן אין הבהמה נעשית \"יד\" לאבר אחד שבה. אולם מוסכם על הכל שאין צורך שיבוא המשקה המכשיר על כל דבר המאכל, ומעתה יש מקום לדון האם האבר המדולדל נחשב כגוף אחד עם הבהמה, לענין שיוכשר הוא איתה. ו\u0003ב\u0004שאלה הנוגעת לדבר אחד קטן שהוא חלק מדבר גדול, וכאשר אדם \u0003אוחז ב\u0004חלק ה\u0003קטן ואין\u0004 החלק ה\u0003גדול עולה עמו קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 האם נחשב החלק הקטן כגוף אחד עם החלק הגדול.","\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' מאיר, \u0005סבור]\u0006 שכל חלק קטן מדבר שלם גדול, וה\u0003אוחז ב\u0004דבר ה\u0003קטן ואין\u0004 ה\u0003גדול עולה עמו\u0004 — אף על פי כן \u0003הרי הוא כמוהו.\u0004 ולכך נחשב ההכשר של דם השחיטה לגוף הבהמה גם כהכשר לאבר המדולדל שבה. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' שמעון, \u0005סבור]\u0006 שהחלק הקטן \u0003אינו כמוהו,\u0004 ולכך \u0003לא הוכשר האבר המדולדל בהכשר הבהמה.\u0004","ומעירים: \u0003ואף ר' יוחנן סבר\u0004 כהסברו זה של אביי, ש\u0003באוחז בקטן ואין גדול עולה עמו קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 שכן","\u0003ר' יוחנן רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 בין דברי \u0003ר' מאיר\u0004 על דברי \u0003ר' מאיר: מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' מאיר\u0004 שה\u0003אוחז בקטן ואין\u0004 ה\u0003גדול עולה עמו הרי הוא כמוהו?\u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים \u0005סתירה\u0006\u0005]\u0006 ממה ששנינו בדינו של חלק \u0003אוכל שנפרס\u0004 מאוכל גדול יותר, \u0003ו\u0004הריהו \u0003מעורה\u0004 (מחובר) \u0003במקצת\u0004 בחלק הגדול של האוכל,"],["שכן הלכה היא שכל הדברים שאוחזים בהם כשנוטלים את האוכל (\"ידות האוכלים\") נחשבים כחיבור לגוף האוכל לענין הטומאה, שאם נגעה בהם הטומאה, נטמא גוף האוכל בכך. ואף אם נגע ב\"יד\" מי שטבל לטומאתו ואולם עדיין לא העריבה שמשו (\"טבול יום\"), נפסל בכך הפרי עצמו. וכן אם נגע בפרי, נפסלה בכך ה\"יד\". ואולם באוכל שנחלק \u0003ר' מאיר אומר: אם\u0004 כשהוא \u0003אוחז ב\u0004חלק ה\u0003קטן ו\u0004באותה עת החלק ה\u0003גדול עולה עמו\u0004 — \u0003הרי הוא כמוהו, ואם לאו\u0004 — \u0003אינו כמוהו.\u0004 והרי זה שלא כשיטתו של ר' מאיר במשנתנו שאין האבר המדולדל צריך הכשר, משום שהריהו כחלק מגוף הבהמה, אף שכשאוחז בחלק הקטן אין החלק הגדול עולה עמו.","\u0003ואמר ר' יוחנן\u0004 בתשובה לסתירה זו: \u0003מוחלפת השיטה,\u0004 במסכת טבול יום החליף ר' מאיר את שיטתו, ואולם בכלל שיטתו היא שבמקרה של חלק קטן שאוחזים בו ובאותה עת אין החלק הגדול עולה עמו, הריהו כמותו. הרי שר' יוחנן מפרש את שיטת ר' מאיר שבמשנתנו כדרך שפירשה אביי.","ושואלים על הסתירה שהראה ר' יוחנן בדברי ר' מאיר במשנתנו לבין דבריו במסכת טבול יום: \u0003ומאי קושיא\u0004 \u0005[ומה קושיה]\u0006 היא זו? \u0003דילמא שני ליה\u0004 \u0005[שמא שונה לו]\u0006 \u0003לר' מאיר\u0004 הדין \u0003בין\u0004 טומאתו של \u0003טבול יום\u0004 שהיא קלה ביותר (שהרי כבר טבל מטומאתו, ואין הוא ממתין אלא להערב שמש בלבד, כדי לאכול מן הקדשים), ולכך יש מקום להקל ולומר שכאשר נגע הטבול יום בחלק האחד, אין החלק האחר נפסל בכך. \u0003ל\u0004בין \u0003שאר טומאות,\u0004 כבמשנתנו בנגיעת אדם בטומאה חמורה, שסבור ר' מאיר שנגיעה בחלק האחד נחשבת כנגיעה בחלק האחר. ומשיבים: אין להבחין בין זה לזה, שכן","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: אחד\u0004 (בין) \u0003טבול יום ואחד\u0004 (ובין) \u0003שאר טומאות\u0004 דינם שווה, שהדבר שנחשב כנגיעה בזה (בטומאה החמורה), הריהו נחשב כנגיעה גם בזה (בטומאה הקלה, כטבול יום).","\u0003ו\u0004מקשים עוד: מה תשובה היא זו, \u0003דילמא\u0004 \u0005[שמא]\u0006 אמנם \u0003ל\u0004דעת \u0003רבי לא שני ליה\u0004 \u0005[אין שונה לו]\u0006 בין טבול יום (הקל) לשאר טומאות (החמורות), \u0003ו\u0004אולם \u0003ל\u0004דעת \u0003ר' מאיר שני ליה\u0004 \u0005[שונה לו]\u0006 בין זה לזה, ואין איפוא מקום לסתירה שהראה ר' יוחנן?","\u0003אמר ר' יאשיה, הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: לדברי רבי\u0004 הסבור ששוות הן טומאת הטבול יום ושאר הטומאות לענין זה, נמצא שלפנינו סתירה בדברי ר' מאיר, ולכך יש צורך לומר ש\u0003מוחלפת השיטה\u0004 של ר' מאיר במשנה במסכת טבול יום, ממה ששנה במסכתנו.","ועוד הסבר במחלוקת ר' מאיר ור' שמעון שבמשנתנו. \u0003רבא אמר:\u0004 אין המדובר במשנתנו אלא כשנזל דם השחיטה על גוף הבהמה ולא על האבר המדולדל, וכמו כן הכל מודים כי הבהמה נעשית יד אף לאבר מסויים שבה, ואולם \u0003ב\u0004שאלה האם \u0003יש \"יד\"\u0004 דווקא \u0003ל\u0004ענין הבאת והוצאת \u0003טומאה ו\u0004אילו לענין הכשר לטומאה אומרים אנו ש\u0003אין יד להכשר, קמיפלגי\u0004 \u0005[חלוקים הם].\u0006","ש\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' שמעון, \u0005סבור]\u0006 ש\u0003יש \"יד\"\u0004 דווקא \u0003ל\u0004ענין ה\u0003טומאה ו\u0004אולם \u0003אין \"יד\" להכשר, ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' מאיר \u0005סבור]\u0006 ש\u0003יש \"יד\"\u0004 הן \u0003ל\u0004ענין ה\u0003טומאה ו\u0004הן \u0003ל\u0004ענין \u0003הכשר.\u0004","ומציעים עוד הסבר במחלוקת ר' מאיר ור' שמעון שבמשנתנו. \u0003רב פפא אמר:\u0004 לדעת הכל יש \"יד\" להכשר כשם שיש \"יד\" לטומאה, ואולם במשנתנו מדובר במקרה שכבר הוכשר האבר המדולדל בדם השחיטה, אך היה ההכשר לפני שחשב על אבר זה להאכילו לגוי. ו\u0003ב\u0004שאלת \u0003הכשר קודם מחשבה\u0004 אם נחשב להכשר, \u0003קמיפלגי\u0004 \u0005[חלוקים הם].\u0006 שר' שמעון סבור שכיון שבשעת ההכשר עדיין לא היה ראוי אבר זה לקבל טומאה (שהרי באותה עת עדיין לא חשב עליו לאכילה), ומן הסתם אינו עומד לאכילה (שהרי אף לבן נח אסור הוא), לכך אין זה הכשר ראוי. ואילו ר' מאיר סבור שחל ההכשר לענין זה שכאשר יחשוב על האבר לאכילה, יהא זה ראוי לקבל טומאה.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 בדינו של חלב בהמה טהורה, ש\u0003אמר ר' יהודה: כך היה ר' עקיבא שונה,\u0004 ה\u0003חלב\u0004 של בהמה \u0003שחוטה בכפרים,\u0004 שבהם מעטים הם האנשים, \u0003ורב הוא הבשר, ולכך אין אנשים שבכפרים אוכלים מן החלב\u0004 — אין החלב מוגדר כ\"אוכל\" לענין קבלת טומאה. ולכך על מנת שיקבל טומאת אוכלים \u0003צריך מחשבה\u0004 להאכילו. \u0003ו\u0004אולם \u0003אין\u0004 החלב \u0003צריך הכשר\u0004 כדי לקבל טומאה, משום \u0003שכבר הוכשר בשחיטה,\u0004 אף שהוכשר לקבל טומאה לפני שהוגדר כ\"אוכל\".","\u0003אמרתי לפניו: למדתנו רבינו\u0004 כי עשבי \u0003ה\u0004\u0003עולשין שלקטן\u0004 מן השדה \u0003והדיחן\u0004 במים כדי לתיתם כאוכל \u0003לבהמה\u0004 (ואין דבר העומד למאכל בהמה נחשב כ\"אוכל\" לענין קבלת טומאת אוכלים), \u0003ו\u0004אחר כך \u0003נמלך עליהן ל\u0004מאכל \u0003אדם\u0004 — הרי אלה \u0003צריכות הכשר שני.\u0004 שיחזור ויתן עליהם אחד משבעת המשקים המכשירים לקבל טומאה, שכן אין ההדחה הראשונה נחשבת לכך. וטעם הדבר: משום שההכשר צריך להיות אחרי המחשבה ולא לפניה. \u0003וחזר ר' עקיבא\u0004 מהדרך שבה שנה את דבריו הקודמים, \u0003להיות שונה כר' יהודה.\u0004","ובכך נחלקו ר' מאיר ור' שמעון: ש\u0003מר סבר לה\u0004 \u0005[חכם זה,\u0006 ר' מאיר, \u0005סבור הוא]\u0006 \u0003כ\u0004דרך ששנה ר' עקיבא \u0003מעיקרא\u0004 \u0005[מתחילה],\u0006 \u0003ומר סבר לה\u0004 \u0005[וחכם זה,\u0006 ר' שמעון, \u0005סבור הוא]\u0006 \u0003כ\u0004דרך ששנה ר' עקיבא לאחר \u0003חזרה.\u0004","ומביאים הצעת פירוש חמישית בהסבר מחלוקת ר' מאיר ור' שמעון. \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא אמר:\u0004 מדובר במשנתנו כאשר אמנם נזל מדם השחיטה על האבר המדולדל, ודם שחיטה מכשיר את דבר המאכל לקבל טומאה. ואולם כאן מדובר \u0003ב\u0004זמן ש\u0003נתקנח\u0004 (התנגב, הוסר) \u0003הדם בין\u0004 שחיטתו של \u0003ה\u0004\u0003סימן\u0004 הראשון \u0003ל\u0004שחיטתו של ה\u0003סימן\u0004 השני. שהרי אין השחיטה המכשרת את הבהמה אלא זו שנשחטו בה שני הסימנים (קנה וושט) או רובם. שבזאת \u0003קמיפלגי\u0004 \u0005[חלוקים הם],\u0006","\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' מאיר, \u0005סבור]\u0006 כי \u0003ישנה ל\u0004שם \u0003\"שחיטה\"\u0004 במשך כל זמן שחיטתם של שני הסימנים, \u0003מתחלה ועד סוף, ו\u0004לכן \u0003האי\u0004 \u0005[זה]\u0006 הדם של הסימן הראשון שנזל על האבר \u0003\"דם שחיטה\" הוא\u0004 נחשב. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר ' שמעון, \u0005סבור]\u0006 כי \u0003אינה ל\u0004שם \u0003\"שחיטה\" אלא לסוף, ו\u0004לכן \u0003האי\u0004 \u0005[זה]\u0006 הדם של הסימן הראשון בלבד, אין זה דם שחיטה אלא \u0003דם מכה הוא,\u0004 שאינו מכשיר.","ועוד הצעת פירוש, שישית במספר, למחלוקת ר' מאיר ור' שמעון. \u0003רב אשי אמר:\u0004 מדובר \u0003ב\u0004מקרה שבו דם השחיטה אכן נזל על האבר המדולדל, ואולם נחלקו ר' מאיר ור' שמעון בשאלה העקרונית האם ה\u0003שחיטה\u0004 עצמה היא ה\u0003מכשרת\u0004 את בשר הבהמה לקבל טומאה, \u0003ולא דם\u0004 השחיטה הוא המכשיר, בכך \u0003קמיפלגי\u0004 \u0005[חלוקים הם].\u0006 שלדעת ר' שמעון אין דם השחיטה מכשיר לקבל טומאה (שאין הוא נחשב כ\"משקה\"), אלא השחיטה מתוך שהיא מכשירה את הבשר לאכילה הריהי גם מכשירתו לקבל טומאה (בכך שנקרא הוא מעתה \"אוכל\"). והאבר המדולדל, שאינו מותר לאכילה על ידי שחיטת הבהמה, כמו כן אין הוא מוכשר לטומאה בשחיטתה. ואילו ר' מאיר סבור שדם השחיטה נקרא \"משקה\" והריהו מכשיר את האבר לקבל טומאה.","למעלה הובא הסברו של רבה שר' מאיר סבור שבהמה נעשית \"יד\" לאבר שבתוכה. ובבירור דעתו זו של ר' מאיר \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה: בהמה\u0004 שיש בה אבר אחד מדולדל ונגעה בה טומאה \u0003בחייה,\u0004 ולא בשעת שחיטתה, \u0003מהו\u0004 דינה לענין \u0003שתעשה \"יד\" לאבר\u0004 שבה, להעביר אליו את הטומאה? שהרי הבהמה עצמה אינה נטמאת (כיון שחיה היא), ואילו האבר המדולדל שבה ראוי לקבל טומאת אוכלים. בעיה זו לא נפתרה ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ועוד בעיה דומה, לשיטת ר' שמעון. \u0003אמר אביי: הרי אמרו\u0004 חכמים במשנה כי ה\u0003קישות\u0004 (קישוא) טמאה \u0003שנטעה בעציץ\u0004 שאינו מנוקב, והריהי נחשבת כתלושה, וראויה איפוא לקבל טומאה ככל דבר מאכל אחר, \u0003והגדילה\u0004 בעציץ, \u0003ויצאת\u0004 (יצאה) אל מ\u0003חוץ לעציץ\u0004 והריהי נוטה מעל הקרקע — כל הקישות כולה \u0003טהורה.\u0004 שכן הצמח כולו (אף החלק שבתוך העציץ) כיונק מן הקרקע, ונחשב כמחובר לקרקע, ונטהר מטומאתו.","\u0003אמר ר' שמעון: וכי מה טיבה\u0004 (עניינה) של טומאת הקישות שבעציץ \u0003לטהר\u0004 בכך? \u0003אלא\u0004 החלק \u0003הטמא\u0004 שבעציץ ישאר \u0003בטומאתו, ו\u0004החלק ה\u0003טהור\u0004 שיצא לחוץ ישאר \u0003בטהרתו.\u0004","ומעתה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אביי\u0004 לדעת ר' שמעון: \u0003מהו\u0004 הדין לענין \u0003שתעשה\u0004 חלק הקישות שיצאה אל מחוץ לעציץ \u0003\"יד\" לחברתה\u0004 (לחלק שבתוך העציץ), שאם נגעה טומאה בחלק הקישות שמחוץ לעציץ ייטמא בכך החלק שבתוך העציץ? אף שאלה זו לא נפתרה ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","עוד בעיה לשיטת ר' שמעון, \u0003אמר ר' ירמיה: הרי אמרו\u0004 חכמים כי \u0003המשתחוה לחצי דלעת\u0004 — \u0003אסרה\u0004 לחצי דלעת זו בהנאה, משום עבודה זרה, ואולם חציה השני של הדלעת לא נאסר בהנאה. ומעתה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004"],["לדעת ר' שמעון שאין איסורי הנאה מטמאים טומאת אוכלים (כמובא להלן קכט,א), \u0003מהו\u0004 הדין לענין \u0003שתעשה\u0004 אותה חצי דלעת שנאסרה בהנאה \u0003\"יד\" לחברתה\u0004 (חציה השני של הדלעת, שלא נאסרה בהנאה), שאם נגעה טומאה בחצי האסור בהנאה, תעבור הטומאה אל החצי המותר בהנאה. אף שאלה זו לא נפתרה, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","ומביאים עוד בעיה דומה. \u0003אמר רב פפא, הרי אמרו\u0004 חכמים במשנה כי \u0003יחור\u0004 (ענף) \u0003של\u0004 עץ ה\u0003תאנה\u0004 שיש עליו תאנים, \u0003שנפשח\u0004 (נחתך מן העץ) \u0003ו\u0004אולם הוא עדיין \u0003מעורה\u0004 (מחובר) \u0003בקליפתה\u0004 של התאנה — \u0003ר' יהודה מטהר\u0004 את פירות התאנים שעל הענף, שאינן מקבלות טומאה, כיון שהריהן נחשבות כמחוברות לעץ. \u0003ו\u0004אילו \u0003חכמים אומרים\u0004 ש\u0003אם\u0004 כשיקשרו את הענף לעץ \u0003יכול\u0004 הוא \u0003לחיות\u0004 ולהוציא פירות — הריהו נחשב כמחובר לעץ, וכל הנמצא עתה עליו \u0003טהור, ואם לאו\u0004 \u0005[לא]\u0006 שאין הוא מוציא פירות לאחר שיקשרוהו לעץ — הריהו \u0003טמא.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 לדעת חכמים המבחינים בין ענף שיכול לחיות לבין ענף שאין יכול לחיות, \u0003מהו\u0004 הדין במקרה של ענף שנחתך מן העץ והריהו יכול לחיות, ומן הענף הזה נחתך ענף אחר שאיננו יכול לחיות ומחובר בקליפתו של הענף הראשון (ולכך הוא נחשב כתלוש, המקבל טומאה). אם נגעה טומאה בענף הראשון האם יש מקום לומר \u0003שיעשה\u0004 ענף זה \u0003\"יד\" לחבירו,\u0004 לענף התלוש, וייטמא? אף שאלה זו לא נפתרה, ו\u0003תיקו\u0004 \u0005[תעמוד,\u0006 תישאר\u0005]\u0006 במקומה.","ועוד בעיה דומה. \u0003אמר ר' זירא: הרי אמרו\u0004 חכמים במשנה כי \u0003אבן\u0004 גדולה \u0003ש\u0004נתונה \u0003בזוית\u0004 הכותל שבין בית זה לבית שכנו, והריהי נראית בשני הבתים. ונמצא נגע בית באבן זו, \u0003כשהוא חולץ\u0004 את האבן ממקומה — הריהו \u0003חולץ את\u0004 האבן \u0003כולה,\u0004 ואף את חלק האבן הנתון בבית שכנו. \u0003ו\u0004אולם \u0003כשהוא נותץ\u0004 את כל הבית — הריהו \u0003נותץ\u0004 רק \u0003את\u0004 הבית \u0003שלו,\u0004 ובכלל זה את חלק האבן שבביתו (שהריהי \"אבן המנוגעת\"), \u0003ומניח\u0004 מלנתוץ \u0003את\u0004 הבית \u0003של חבירו,\u0004 ואף לא את חלק האבן שבבית השכן (שאין היא בכלל \"אבן המנוגעת\").","ומעתה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא: מהו\u0004 הדין לענין \u0003שתעשה\u0004 חלק האבן הנתונה בבית שכנו \u0003\"יד\" לחברתה\u0004 (חלק האבן שבבית המנוגע), ולענין שתוציא ה\"יד\" את הטומאה אל הנוגע ב\"יד\". ויהא הבא אל בית השכן נטמא, כדרך שנטמא הבא אל הבית המנוגע. או שאין אנו אומרים דין \"יד\" בטומאת נגעי בתים. ומסכמים כי אף שאלה זו לא נפתרה ו\u0003תיקו\u0004 \u0005[תעמוד,\u0006 תישאר\u0005]\u0006 במקומה.","שנינו במשנתנו כי אם \u0003מתה הבהמה,\u0004 הבשר המדולדל צריך הכשר כדי לקבל טומאת אוכלים, ואילו האבר המדולדל אמנם מטמא משום אבר מן החי (שהריהו ככל אבר שפרש מן החי), ואולם הוא אינו מטמא משום אבר הנבילה. ושואלים: \u0003מאי איכא\u0004 \u0005[מה,\u0006 איזה הבדל הלכתי \u0005יש]\u0006 \u0003בין\u0004 טומאת \u0003אבר מן החי ל\u0004טומאת \u0003אבר של הנבלה,\u0004 והרי זו וזו טומאה חמורה היא?","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לגבי \u0003בשר הפורש ממנו, מאבר\u0004 ה\u0003בהמה.\u0004 ש\u0003אילו בשר הפורש מאבר מן החי\u0004 — \u0003לא מטמא.\u0004 שהרי אף אם פרש הבשר מן הבהמה עצמה, אין הוא מטמא. בעוד שהבשר הפורש \u0003מאבר מן הנבלה\u0004 — הריהו \u0003מטמא\u0004 אם יש בו שיעור כזית, שהרי בשר נבילה הוא.","ושבים לדון בעיקרה של טומאת \u0003אבר מן החי\u0004 שאמרנו בו שהוא \u0003מטמא, מאי קרא\u0004 \u0005[מהו המקרא]\u0006 המלמד על כך? \u0003אמר רב יהודה, אמר רב:\u0004 נאמר בתורה בפרשת טומאת הנבילה \u0003\"וכי ימות מן הבהמה\u0004 אשר היא לכם לאוכלה הנוגע בנבלתה יטמא עד הערב\" (ויקרא יא, לט). וממה שנאמר \u0003\"וכי ימות מן הבהמה\" ולא \"וכי תמות בהמה\" למדים שבכלל טומאה זו גם אבר מן הבהמה שמת (שנתלש ממנה, ובכך חדל להיות חלק מבעל חיים חי). ו\u0004","מקשים: כיצד דורש כן רב יהודה בשם רב מן הכתוב הזה, \u0003ו\u0004הרי \u0003האי\u0004 \u0005[זה]\u0006 הפסוק \u0003מיבעי ליה לכאידך\u0004 \u0005[נצרך לו\u0006 הפסוק \u0005ל\u0006דין \u0005אחר]\u0006 של \u0003רב יהודה\u0004 ש\u0003אמר\u0004 בשם \u0003רב,\u0004 שכן \u0003אמר רב יהודה\u0004 שכך \u0003אמר רב, ואמרי לה במתניתא תנא\u0004 \u0005[ויש אומרים\u0006 ש\u0005בברייתא\u0006 היא \u0005שנויה]:\u0006 \u0003\"וכי ימות מן הבהמה...\u0004 הנוגע בנבלתה יטמא עד הערב\" — מן הבהמה, ולא כל הבהמה, יש \u0003מקצת\u0004 (חלק) ממיני ה\u0003בהמה\u0004 ש\u0003מטמאה\u0004 במותה בטומאת נבילה, \u0003ו\u0004יש \u0003מקצת\u0004 (חלק) ממיני ה\u0003בהמה\u0004 ש\u0003אינה מטמאה\u0004 במותה בטומאת נבילה. \u0003ואיזו זו\u0004 הבהמה שאינה מטמאה? \u0003זו\u0004 בהמה \u0003טרפה ששחטה.\u0004 שאף שאין השחיטה מתירה את הבהמה לאכילה (שהרי טריפה היא), מכל מקום היא מועילה להוציאה מכלל טומאת נבילה.","ומשיבים: \u0003אם כן,\u0004 שרק לדרשה זו בא הכתוב, \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \"וכי ימות \u0003מבהמה\", מאי\u0004 \u0005[מה]\u0006 מלמדנו הכתוב \"וכי \u0003ימות\u0004 \u0003מן הבהמה\"\u0004 שהוא לשון יתר? \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003תרתי\u0004 \u0005[שתי]\u0006 דרשות יש בו, והדרשה השנית היא לענין טומאת אבר מן החי.","ומקשים : \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא שלמדים אנו מן הכתוב \"מן הבהמה\" שאף אבר מן החי מטמא בטומאת נבילה, מעתה נאמר כי \u0003אפילו בשר\u0004 שפרש מן החי \u0003נמי\u0004 \u0005[גם כן]\u0006 יטמא בטומאת נבילה, שיילמד אף הוא מכתוב זה! ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כך, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003יכול יהא בשר הפורש מן החי\u0004 \u0003טמא\u0004 בטומאת נבילה? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"וכי ימות מן הבהמה\"\u0004 — \u0003מה מיתה\u0004 הריהי דבר \u0003שאינה עושה חליפין,\u0004 שהרי אין שבים ונוצרים חיים חדשים בדבר שמת\u0003.\u0004 \u0003אף כל\u0004 המטמא בטומאת נבילה הוא זה \u0003ש\u0004במותו \u0003אינו עושה חליפין,\u0004 כאבר שפרש מן החי, שאין אותו אבר חוזר ונוצר בגוף הבהמה והוא זה שמטמא בטומאת הנבילה. מה שאין כן הבשר, שלאחר ופרש מן הבהמה, נוצר בשר אחר תחתיו. אלו הם \u0003דברי ר' יוסי.\u0004","\u0003ר' עקיבא אומר\u0004 כי יש ללמוד מן הכתוב \u0003\"בהמה\": מה בהמה\u0004 הריהי דבר שיש בו \u0003גידים ועצמות, אף כל\u0004 דבר שיש בו \u0003גידים ועצמות\u0004 הוא המטמא. ולכך אבר (שיש בו גידים ועצמות) שפרש מן החי מטמא, ואילו בשר שפרש מן החי אינו מטמא. \u0003רבי אומר\u0004 כי יש ללמוד כן מן הכתוב \u0003\"בהמה\", מה בהמה\u0004 הריהי דבר שיש בו \u0003בשר גידים ועצמות, אף כל\u0004 דבר שיש בו \u0003בשר גידים ועצמות\u0004 הוא המטמא. ולכך אבר (שיש בו בשר גידים ועצמות) שפרש מן החי מטמא, ואילו בשר שפרש \u0003אינו מטמא. ומבררים\u0004",": \u0003מאי איכא\u0004 \u0005[מה,\u0006 איזה הבדל \u0005יש]\u0006 \u0003בין\u0004 דרשתו של \u0003רבי ל\u0004בין דרשתו של \u0003ר' עקיבא,\u0004 שהרי לדעת שניהם אין מטמא הדבר שאין בו גידים ועצמות? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל בדינה של ה\u0003ארכובה\u0004 (העצם התחתונה שברגל), שיש בה גידים ועצמות ואולם אין בה בשר, שלדעת ר' עקיבא הריהי מטמאה כשפירשה מן החי, ולדעת רבי אינה מטמאה, כיון שאין בה בשר. ומבררים עוד:","\u0003בין ר' עקיבא לר' יוסי הגלילי, מאי איכא בינייהו\u0004 \u0005[מה\u0006 איזה הבדל \u0005יש ביניהם]?\u0006 \u0003אמר רב פפא:\u0004 למשל \u0003כוליא\u0004 \u0005[כליה]\u0006 \u0003וניב שפתים\u0004 של הבהמה שפרשו מן החי \u0003איכא בינייהו\u0004 \u0005[יש ביניהם].\u0006 שלדעת ר' יוסי הגלילי, כיון שהאברים הללו אינם \u0003מתחלפים — הריהם מטמאים. ואילו לדעת ר' עקיבא, כיון שאין באברים הללו עצם — אין הם מטמאים.\u0004","למעלה הובאה ברייתא בעניינה של טומאת בשר הפורש מן החי, והובאו בה דעות ר' יוסי הגלילי ור' עקיבא ורבי, ודנו חכמים בהבדלים שבין שיטות התנאים הללו. וכיוצא בדבר \u0003תניא נמי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 טומאת \u0003שרצים כהאי גוונא\u0004 \u0005[כגון זו].\u0006 שכך שנינו: \u0003יכול\u0004 ש\u0003בשר הפורש מן השרצים יהא טמא\u0004 כשרצים עצמם? \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בפרשת טומאת השרצים \"וכל אשר יפול עליו מהם במותם יטמא\" (ויקרא יא, לב), ובאה המלה \u0003\"במותם\"\u0004 להורות: \u0003מה מיתה\u0004 הריהי דבר \u0003שאינה עושה חליפין,\u0004 שאין חיים חדשים נוצרים במקומה, והיא זו המטמאת בטומאת השרצים, \u0003אף כל ש\u0004בא מן השרץ הריהו מטמא אם \u0003אינה עושה חליפין,\u0004 יצא מכלל זה הבשר שפרש מן השרץ בחייו, שבשר חדש עולה במקומו. אלה הם","\u0003דברי ר' יוסי הגלילי. ר' עקיבא אומר:\u0004 למדים אנו שאין הבשר שפרש מן השרץ בחייו מטמא, מתוך המלה \u0003\"שרץ\",\u0004 שהרי זה בא ללמד: \u0003מה שרץ\u0004 הריהו דבר שיש בו \u0003גידים ועצמות, אף כל\u0004 דבר שפרש מן השרץ דווקא אם יש בו \u0003גידים ועצמות\u0004 הריהו מטמא, יצא מכלל זה הבשר, שאין בו גידים ועצמות. ואילו \u0003רבי אומר\u0004 שלמדים אנו מן הכתוב \u0003\"שרץ\": מה שרץ\u0004 הריהו דבר שיש בו \u0003בשר גידים ועצמות, אף כל\u0004 דבר הפורש מן השרץ בחייו מטמא רק אם יש בו \u0003בשר גידים ועצמות.\u0004 יצא מכלל זה הבשר שפרש מן השרץ בחייו, שאין בו בשר גידים ועצמות. ומבררים:","\u0003בין רבי לר' עקיבא איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל בדינה של \u0003ארכובה\u0004 שפרשה מן השרץ בחייו, שלדעת ר' עקיבא הריהי מטמאה, כיון שיש בה גידים ועצמות, ולכך נחשבת היא כ\"שרץ\". ואילו לדעת רבי אין היא מטמאת, כיון שאין בה בשר. ואולם \u0003בין ר' עקיבא לר' יוסי הגלילי מאי איכא בינייהו\u0004 \u0005[מה,\u0006 איזה הבדל \u0005יש ביניהם]?\u0006 \u0003אמר רב פפא:\u0004 בדינם של \u0003כוליא\u0004 \u0005[כליה]\u0006 \u0003וניב שפתים איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל, שלדעת ר' יוסי הגלילי מטמאים הם, שכן הם אינם עושים חליפים, שאין אחרים עולים תחתם. ואילו לדעת ר' עקיבא הם אינם מטמאים, כיון שאין בהם עצם.","\u0003ו\u0004\u0005מסבירים מדוע נצרכו שתי ברייתות אלה להיאמר:\u0006 \u0003צריכא\u0004 \u0005[צריך]\u0006 דין בשר שפרש להישנות הן לענין טומאת בשר שפרש מן הבהמה בחייה והן לענין טומאת בשר שפרש מן השרץ. \u0003דאי אשמעינן\u0004 \u0005[ש\u0006כן \u0005אם היה משמיע לנו]\u0006 דין זה רק ב\u0003בהמה\u0004 — היינו אומרים כי \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 שהבשר שפרש \u0003לא מטמא מחיים, משום\u0004 שאין טומאת נבילה חמורה כל כך, שהרי \u0003לא מטמא ב\u0004שיעור קטן \u0003כעדשה,\u0004 אלא בשיעור כזית. \u0003אבל שרץ\u0004 שטומאתו חמורה, ש\u0003מטמא\u0004 אפילו \u0003ב\u0004שיעור \u0003כעדשה, אימא\u0004 \u0005[אמור]\u0006 שהבשר שפרש ממנו יהא דינו \u0003לטמא מחיים! ו\u0004מצד שני,","\u0003אי אשמועינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 את הדין רק בטומאת \u0003שרץ\u0004 — היינו אומרים כי טעם הדבר הוא \u0003משום\u0004 שקלה היא טומאה זו, שהרי השרץ \u0003לא מטמא במשא,\u0004 לכן בשרו שפרש ממנו \u0003לא מטמא מחיים, אבל בהמה\u0004 שטומאתה חמורה, שכזית מן הנבילה \u0003מטמא במשא, אימא\u0004 \u0005[אמור]\u0006 ש\u0003תטמא\u0004 גם בבשר שפרש ממנה \u0003מחיים,\u0004 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 הדין להיאמר בשתי הברייתות.","ומביאים עוד בדין בשר שפרש מן החי. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003החותך כזית בשר מאבר מן החי,\u0004 שאמנם אין הבשר הפורש מן האבר מטמא בטומאת נבילה, ואולם מטמא טומאת אוכלים (אם החשיבו כאוכל, ונגע בו שרץ). אם \u0003חתכו\u0004 מן האיבר \u0003ואחר כך חישב עליו\u0004 להאכיל אותו לגוי — הרי הוא \u0003טהור,\u0004 שכן בשעה שהחשיב את הבשר לאוכל עדיין לא היה דבר המטמא את הבשר.","ואולם אם \u0003חישב עליו\u0004 להאכילו לגוי לפני שחתך את הבשר מן האבר, \u0003ו\u0004רק \u0003אחר כך חתכו\u0004 — הריהו \u0003טמא,\u0004 שכן בעת שכבר הוגדר הבשר כ\"אוכל\" נגע בדבר המטמא, הוא האבר מן החי, ונטמא בו הבשר בטומאת אוכלים.","ובענין זה מסופר כי פעם אחת \u0003ר' אסי לא על לבי מדרשא\u0004 \u0005[לא נכנס לבית המדרש],\u0006 \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 \u0003ר' זירא, אמר ליה\u0004 \u0005[לו]\u0006 ר' אסי לר' זירא: \u0003מאי אמור בבי מדרשא\u0004 \u0005[מה אמרו\u0006 היום \u0005בבית המדרש]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא לר' אסי: \u0003מאי קשיא\u0004 \u0005[מה\u0006 הדבר ש\u0005קשה]\u0006 \u0003לך,\u0004 שסבור אתה שדנו בו בבית המדרש? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אסי לר' זירא: מה שקשה לי הוא זה \u0003דקתני\u0004 \u0005[ששנינו]\u0006 \u0003חישב\u0004 על הבשר שנחתך מאבר מן החי להאכילו לגוי, \u0003ואחר כך חתכו,\u0004 שהריהו \u0003טמא.\u0004"],["ועל כך קשה לי, כיצד נטמא הבשר באבר זה, והרי מקום מגעו טרם חיתוכו, נסתר, ו\u0003טומאת בית הסתרים היא, ו\u0004כלל הוא ש\u0003טומאת בית הסתרים לא מטמא!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא לר' אסי: \u0003אף לדידי קשיא\u0004 \u0005[לי עצמי היה קשה]\u0006 \u0003לי\u0004 כך, \u0003ושאילתיה\u0004 \u0005[ושאלתי אותה]\u0006 \u0003לר' אבא בר ממל, ואמר לי\u0004 בתשובה כי \u0003הא\u0004 \u0005[זו]\u0006 הברייתא כשיטת \u0003מני\u0004 \u0005[מי היא]?\u0006 כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר\u0004 כי \u0003טומאת בית הסתרים מטמא.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אסי לר' זירא: \u0003ולאו זימנין סגיאין\u0004 \u0005[והאם לא פעמים רבים]\u0006 \u0003אמרה\u0004 ר' אבא בר ממל את תירוצו זה \u0003קמאי\u0004 \u0005[לפני],\u0006 \u0003ואמרי ליה\u0004 \u0005[ואמרתי לו]\u0006 שאין זה מתרץ את דברי הברייתא, שהרי \u0003שני ליה\u0004 \u0005[שונה לו]\u0006 הדין בטומאת בית הסתרים \u0003לר' מאיר בין טומאה דבעיא\u0004 \u0005[שצריכה]\u0006 \u0003הכשר\u0004 כדי שתחול, וכגון במקרה שבברייתא, שבשעה שחתך את הבשר מן האבר, עדיין לא הוכשר הבשר.","\u0003ובין טומאה דלא בעיא\u0004 \u0005[שאינה צריכה]\u0006 \u0003הכשר. אמר רבא\u0004 בתמיהה על דברי ר' אסי: \u0003ומאי קושיא\u0004 \u0005[ומה שאלה]\u0006 היא זו? \u0003דלמא\u0004 \u0005[שמא]\u0006 אף בברייתא זו מדובר \u0003בשהוכשר\u0004 הבשר לפני שנחתך האבר?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר רב חנן לרבא\u0004 בדחיית דבריו: \u0003למה לי הכשר\u0004 לבשר הזה שנחתך מן האבר מן החי, ו\u0003הרי\u0004 הבשר הזה בשעה שהיה מחובר לאבר, היה \u0003מטמא טומאה חמורה\u0004 מתוקף היותו באותו זמן \u0003אגב\u0004 \u0005[אצל]\u0006 \u0003אביו\u0004 (כלומר, אבר מן החי, שהבשר היה חלק ממנו, ולאחר מכן פרש מאתו). ובאותה עת היתה זו טומאה חמורה כטומאת נבילה (המטמאת אדם וכלים). ודין הוא בהלכות טומאה כי כל שסופו לטמא טומאה חמורה, הריהו מטמא עתה טומאה קלה (כטומאת אוכלים) אף בלא שהוכשר בנתינת משקה עליו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לרבה בר חנן: לא נאמר הכלל הזה אלא כאשר הטומאה החמורה והטומאה הקלה שתיהן מטמאות כ\"אוכל\". ואולם לפנינו מדובר \u0003כששימש\u0004 הבשר את האבר רק על מנת שיוכל האבר להיקרא \"אבר מן החי\" (שהרי אין אבר נקרא כן אלא אם כן יש בו בשר גידים ועצמות), ונמצא איפוא כי הבשר כ\u0003מעשה עץ שימש\u0004 את האבר, ולא כ\"אוכל\". ובמקרה שכזה זקוק הבשר להכשר כדי שתחול עליו טומאת אוכלים.","למעלה הובאה קביעתו של רבא שכל דבר מאכל ששימש כ\"מעשה עץ\" את הטומאה החמורה, נזקק להכשר שיקבל טומאה קלה. ומביאים עוד עניינים המוסברים על ידי קביעה זו. שכן \u0003אמר אביי: הרי אמרו\u0004 חכמים בברייתא כי \u0003כופת\u0004 (גוש) של \u0003שאור ש\u0004התקשה ועמד ו\u0003יחדה\u0004 (הועיד אותה) \u0003ל\u0004צורך \u0003ישיבה\u0004 עליה — בכך \u0003בטלה\u0004 מלהיחשב עוד כ\"חמץ\" האסור בימי הפסח, ומותר לקיימה בתוך הבית. ששוב אין זה \"אוכל\" אלא כלי מושב. אכן מעתה שנחשב גוש השאור ככלי מושב, יש בו דין טומאת מדרס (שאם ישב עליו הזב — נטמא בכך).","ואולם \u0003טומאתה\u0004 זו היא \u0003לאו דאורייתא\u0004 \u0005[אינה מן התורה],\u0006 אלא מדברי חכמים. ומנמק אביי את דבריו: \u0003דאי סלקא דעתך דאורייתא\u0004 \u0005[שאם עולה על דעתך\u0006 לומר \u0005ש\u0006טומאה זו היא \u0005מן התורה],\u0006 מעתה \u0003מצינו\u0004 \u0005[מוצאים אנו]\u0006 \u0003לאוכלין\u0004 שיש אופן \u0003ש\u0004בו הם \u0003מטמאין טומאה חמורה\u0004 (כאב הטומאה), והרי אמרו חכמים כי לא נאמר דין הכשר אלא בדברי אוכל, \u0003ומשום שהאוכל לעולם אינו בא לכלל טומאה חמורה.\u0004 ומעתה נמצא שגם אוכל (שחישב עליו לישיבה) בא לידי טומאה חמורה. לכך צריך לומר שטומאה זו היא מדברי חכמים, ולא מדין תורה. ואולם עתה, עם קביעתו של רבא, יש לדחות את דברי אביי: אכן טומאת גוש השאור שיוחד לישיבה היא מן התורה, ואולם \u0003כששימש\u0004 גוש השאור הזה כדי לקבל \u0003טומאת מדרס מן התורה —\u0004 לא כ\"אוכל\" שימש, אלא כ\u0003מעשה עץ\u0004 הוא \u0003שימש,\u0004 לצורך הישיבה עליו.","כיוצא בדבר \u0003אמר אביי, הרי אמרו\u0004 חכמים במסכתנו (לעיל יג,ב) ש\u0003תקרובת\u0004 (הדברים הבאים כקרבן) ל\u0003עבודה זרה של אוכלין\u0004 הריהם \u0003מטמאין באוהל\u0004 כטומאת המת. ואף בזו יש לומר כי \u0003טומאתה\u0004 היא \u0003לאו דאורייתא\u0004 \u0005[אינה מן התורה],\u0006 אלא מגזירת חכמים היא. ומנמק אביי את דבריו: \u0003דאי סלקא דעתך דאורייתא\u0004 \u0005[שאם עולה על דעתך\u0006 לומר \u0005ש\u0006טומאה זו היא \u0005מן התורה],\u0006 מעתה \u0003מצינו\u0004 \u0005[מוצאים אנו]\u0006 \u0003לאוכלין\u0004 שיש אופן \u0003ש\u0004בו הם \u0003מטמאין טומאה חמורה\u0004 (כאב הטומאה)! ודוחים: אף כאן יש לומר שטומאת תקרובת עבודה זרה של אוכלין היא אכן מן התורה, ואולם \u0003כששימש\u0004 דבר מאכל זה כתקרובת עבודה זרה \u0003—\u0004 לא כאוכל שימש, אלא כ\u0003מעשה עץ\u0004 הוא \u0003שימש\u0004 את העבודה זרה.","כיוצא בדבר \u0003אמר אביי, הרי אמרו\u0004 חכמים כי \u0003חבורי אוכלין\u0004 (דברי מאכל שמחוברים לכלים, כבצק הנמצא בסדקיו של הכלי, ומשמש בכך את הכלי, ומעונין הבעלים שישאר שם חמץ זה בשימושו את הכלי — \u0003ככלים\u0004 \u0003דמו\u0004 \u0005[נחשבים],\u0006 ולפיכך, אם נגע כזית מן המת בהם, הריהם נטמאים כ\"אב הטומאה\" ככל כלי, וחוזרים ומטמאים כטומאה חמורה, אדם וכלים. אף בזו יש לומר כי \u0003טומאתן\u0004 היא \u0003לאו דאורייתא\u0004 \u0005[אינה מן התורה],\u0006 אלא מגזירת חכמים היא. ומנמק אביי את דבריו: \u0003דאי סלקא דעתך דאורייתא\u0004 \u0005[שאם עולה על דעתך\u0006 לומר \u0005ש\u0006טומאה זו היא \u0005מן התורה],\u0006 מעתה \u0003מצינו\u0004 \u0005[מוצאים אנו]\u0006 \u0003לאוכל\u0004 שיש אופן \u0003ש\u0004בו הוא \u0003מטמא טומאה חמורה\u0004 (כאב הטומאה)! ודוחים: אף כאן יש לומר שטומאת חבורי האוכלים היא אכן מן התורה, ואולם \u0003כששימש\u0004 דבר מאכל זה כחיבורי הכלי \u0003—\u0004 לא כאוכל שימש, אלא כ\u0003מעשה עץ שימש\u0004 את הכלי.","ומביאים עוד כיוצא בזה, מה ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא: הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]\u0006 כי \u0003חלב נבלה\u0004 הבא מן הבהמה הטהורה, \u0003בכפרים\u0004 על מנת שיקבל טומאת אוכלים הריהו \u0003צריך\u0004 גם \u0003מחשבה\u0004 של הבעלים שייאכל החלב (על ידי גוי, ובכך הריהו מוגדר כאוכל), \u0003ו\u0004הריהו צריך גם \u0003הכשר\u0004 במתן אחד המשקים המכשירים עליו. ועל כך אמר רב פפא כי חלב הכליה \u0003טומאתו אגב כוליא\u0004 \u0005[אצל הכליה]\u0006 היא \u0003לאו דאורייתא\u0004 \u0005[אינה מן התורה],\u0006 אלא מגזירת חכמים היא. ומנמק רב פפא את דבריו: \u0003דאי סלקא דעתך דאורייתא\u0004 \u0005[שאם עולה על דעתך\u0006 לומר \u0005ש\u0006טומאה זו היא \u0005מן התורה],\u0006 מעתה \u0003מצינו\u0004 \u0005[מוצאים אנו]\u0006 \u0003לאוכל\u0004 שיש אופן \u0003ש\u0004בו הוא \u0003מטמא טומאה חמורה\u0004 (כאב הטומאה)!","ודוחים: אף כאן יש לומר שטומאת חלב הנבילה בכפרים היא אכן מן התורה, ואולם \u0003כששימש\u0004 החלב את הכליה, שימוש זה שבגללו הוא מטמא \u0003—\u0004 לא כאוכל הוא שימש, אלא כ\u0003מעשה עץ\u0004 הוא \u0003שימש\u0004 את הכלי, וכאילו היה זה עצם השומר על הכליה.","ומביאים עוד כיוצא בזה, מה ש\u0003אמר רב מתנה, הרי אמרו\u0004 חכמים כי \u0003בית שסככו בזרעים\u0004 (צמחים שונים), שהשתמש בהם כתקרה לביתו, אם היתה באותם צמחים טומאת אוכלים — \u0003טהרו\u0004 בסיכוכם מידי טומאתם. שכן שוב אין הם בכלל אוכל אלא כחלק מן הבית. ולכך אם תפרח צרעת באותו בית — כל הבית טמא, על כתליו ואהלו. ועל כך אמר רב מתנה כי \u0003טומאתו\u0004 זו היא \u0003לאו דאורייתא\u0004 \u0005[אינה מן התורה],\u0006 ומנמק רב מתנה את דבריו: \u0003דאי סלקא דעתך דאורייתא\u0004 \u0005[שאם עולה על דעתך\u0006 לומר \u0005ש\u0006טומאה זו היא \u0005מן התורה],\u0006 מעתה \u0003מצינו\u0004 \u0005[מוצאים אנו]\u0006 \u0003לזרעים\u0004 שיש אופן \u0003ש\u0004בו הוא \u0003מטמא טומאה חמורה\u0004 (כאב הטומאה)! ודוחים: אף כאן יש לומר שטומאת הזרעים שסוככו היא אכן מן התורה, ואולם \u0003כששימש\u0004 הזרע את הבית כתקרה \u0003—\u0004 לא כאוכל הוא שימש, אלא כ\u0003מעשה עץ שימש\u0004 את הבית.","ושבים להסבר משנתנו, ששנינו בה שאם מתה הבהמה, נחשבים הבשר והאבר המדולדלים כאילו נפלו ממנה בחייה, ואין הם נעשים נבילה עם מותה של הבהמה. ולכך הבשר המדולדל צריך הכשר כדי לקבל טומאה (שהרי דינו כבשר מן החי, שטהור הוא), ואילו האבר המדולדל מטמא משום אבר מן החי, ואינו מטמא משום אבר נבילה. אלה הם דברי ר' מאיר, ואילו \u0003ר' שמעון מטהר.\u0004 ונראים דברי ר' שמעון כמוסבים על מה שאמר ר' מאיר במתה הבהמה, שבניגוד לר' מאיר המטמא את האבר טומאה חמורה, ר' שמעון מטהר את האבר מטומאה חמורה זו.","ושואלים: \u0003מה נפשך\u0004 \u0005[מה רצונך]\u0006 לומר בהסבר שיטתו של ר' שמעון? \u0003אי\u0004 \u0005[אם]\u0006 אתה אומר שטעמו הוא משום שה\u0003מיתה\u0004 של הבהמה \u0003עושה ניפול\u0004 (מחשיבה את האבר כאילו הוא נפל ממנה קודם למותה) — \u0003ליטמא\u0004 \u0005[שיטמא]\u0006 האבר \u0003משום אבר מן החי,\u0004 וכדינו של כל אבר הפורש מן הבהמה בחייה! ו\u0003אי\u0004 \u0005[אם]\u0006 תאמר בטעמו של ר' שמעון ש\u0003אין מיתה עושה ניפול,\u0004 וזו הסיבה מדוע אין האבר מטמא משום אבר מן החי, ומשום שהריהו כחלק מגוף הבהמה — מעתה \u0003ליטמא\u0004 \u0005[שיטמא]\u0006 \u0003משום אבר מן הנבלה!\u0004 וכיצד לדעת ר' שמעון הוא טהור לגמרי?","ומשיבים: אין דברי ר' שמעון מוסבים על סוף משנתנו, בזמן שמתה הבהמה, אלא \u0003ר' שמעון ארישא קאי\u0004 \u0005[על ראשה\u0006 של המשנה \u0005עומד,\u0006 מתייחס\u0005],\u0006 שכן שנינו בה בדינם של \u0003האבר והבשר המדולדלין בבהמה\u0004 — \u0003מטמא טומאת אוכלין במקומן וצריכין הכשר, ו\u0004על זה שונים אנו בסוף המשנה כי \u0003ר' שמעון מטהר\u0004 מטומאת אוכלים.","ובהסבר שיטתו של ר' שמעון, \u0003אמר ר' אסי, אמר ר' יוחנן: מאי טעמא\u0004 \u0005[מה הטעם,\u0006 מקור דעתו\u0005]\u0006 של \u0003ר' שמעון?\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפרשת טומאת האוכלים \u0003\"מכל האוכל אשר יאכל\u0004 אשר יבוא עליו מים יטמא\" (ויקרא יא,לד) — בא כפל הלשון (\"האוכל אשר יאכל\") ללמדנו כי רק \u0003אוכל שאתה יכול להאכילו\u0004 בהיתר \u0003לאחרים,\u0004 אף לגוים — הוא זה ה\u0003קרוי\u0004 (הנקרא, הנחשב) \u0003אוכל\u0004 לענין קבלת טומאת אוכלים. אבל \u0003אוכל שאי\u0004 (שאין) \u0003אתה יכול להאכילו\u0004"],["\u0003לאחרים\u0004 (כדבר האסור אף לגוים משום אבר מן החי, כגון אבר והבשר המדולדלים) \u0003—\u0004 \u0003אין קרוי\u0004 (נקרא, נחשב) \u0003אוכל.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' אסי\u0004 בשאלה על הסברו זה בשם ר' יוחנן: אם אמנם ר' שמעון מתייחס לתחילת משנתנו, מנין לנו שטעמו של ר' שמעון הוא משום שדבר שאינו ראוי להאכילו לאחרים אינו נחשב אוכל, \u0003דילמא טעמא\u0004 \u0005[שמא הטעם]\u0006 של \u0003ר' שמעון התם\u0004 \u0005[שם],\u0006 בראשית משנתנו, שמטהר את האבר והבשר המדולדלים מכלל טומאת אוכלים, הוא משום שסבור ר' שמעון כי \u0003הואיל ו\u0004האבר והבשר הוא עדיין \u0003מעורה\u0004 בגוף הבהמה (אף שהם מדולדלים) לכך הוא נחשב כ\u0003מעורה\u0004 לכל דבר.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדין \u0003יחור\u0004 (ענף רך) \u0003של\u0004 עץ ה\u0003תאנה שנפשח\u0004 (נחתך) מן העץ, \u0003ו\u0004אולם הוא עדיין \u0003מעורה בקליפה\u0004 של עץ התאנה — לדעת \u0003ר' יהודה\u0004 אין פירות התאנים שבאותו ענף נחשבים כתלושים אלא כמחוברים, ולכך הריהו \u0003מטהר\u0004 אותם מכלל טומאה. \u0003ו\u0004אילו \u0003חכמים אומרים: אם\u0004 הוא \u0003יכול\u0004 במצבו זה לשוב ו\u0003לחיות\u0004 (להתחבר עם העץ ולפרוח ולהניב) — הרי זה נחשב למחובר, ולכך הפרי הנמצא עליו הינו \u0003טהור. ואם לאו\u0004 \u0005[לא],\u0006 שאין הענף מסוגל לשוב ולהתאחות עם העץ — נחשב הוא כתלוש, והפרי הנמצא עליו הריהו \u0003טמא. ואמרינן לך\u0004 \u0005[ואמרנו לך,\u0006 לר' אסי\u0005]\u0006 בשאלה: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה? ואמרת לן\u0004 \u0005[לנו]\u0006 בתשובה כי טעמו הוא \u0003הואיל ו\u0004הענף עדיין \u0003מעורה\u0004 בעץ התאנה, נחשב הוא כ\u0003מעורה.\u0004 ומעתה בדומה לכך יש לומר גם לדעת ר' שמעון!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אסי לר' זירא בתשובה: לדעת ר' יוחנן, אין דברי ר' שמעון מוסבים על ראשית המשנה, אלא \u0003אמצעיתא\u0004 \u0005[על אמצע\u0006 המשנה\u0005],\u0006 ששנינו בה כי אם \u0003נשחטה הבהמה,\u0004 אף שעדיין לא בא עליה משקה, מכל מקום \u0003הוכשרה\u0004 לקבל טומאה \u0003ב\u0004אמצעות \u0003דמיה\u0004 של השחיטה, \u0003דברי ר' מאיר,\u0004 ועל \u0003כך\u0004 \u0003ר' שמעון אומר\u0004 כי \u0003לא הוכשרו\u0004 בדמי השחיטה.","","","","","ובהסבר שיטתו זו של ר' שמעון \u0003אמר ר' יוחנן: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון?\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפרשת טומאת האוכלים \u0003\"מכל האוכל אשר יאכל\u0004 אשר יבוא עליו מים יטמא\" (ויקרא יא, לד) — בא כפל הלשון (\"האוכל אשר יאכל\") ללמדנו כי רק \u0003אוכל שאתה יכול להאכילו\u0004 בהיתר \u0003לאחרים\u0004 — הוא זה ה\u0003קרוי\u0004 (הנקרא, הנחשב) \u0003אוכל\u0004 לענין קבלת טומאת אוכלים. אבל \u0003אוכל שאין אתה יכול להאכילו\u0004 — \u0003אין קרוי אוכל.\u0004 ואף על הצעה זו שואלים: מנין לו לר' יוחנן להסביר כך את שיטת ר' שמעון, \u0003ודילמא טעמא\u0004 \u0005[ושמא הטעם]\u0006 של \u0003ר' שמעון בההיא\u0004 \u0005[באותה\u0006 הלכה\u0005]\u0006","","\u0003אי\u0004 \u0005[או]\u0006 \u0003כ\u0004הסברו של \u0003רבא\u0004 (רבה) בהסבר מחלוקתם זו (לעיל קכז,ב) שלדעת ר' שמעון אין הבהמה כולה נעשית יד לאבר מסויים שבה. \u0003אי\u0004 \u0005[או]\u0006 \u0003כ\u0004הסברו של \u0003ר' יוחנן\u0004 (שם) הסבור שנחלקו ר' מאיר ור' שמעון בשאלה האם הבשר והאבר המדולדל נחשבים כגוף אחד עם הבהמה, וכגון שכשאוחז באבר ובבשר הללו, אין גוף הבהמה עולה אתם? \u0003אלא, לעולם\u0004 אתה צריך לפרש, כדרך שאמרנו בתחילה, שדברי ר' שמעון מתייחסים \u0003אסיפא\u0004 \u0005[על סופה]\u0006 של המשנה, \u0003ו\u0004אולם \u0003לאו\u0004 \u0005[לא]\u0006 על ה\u0003אבר\u0004 המדולדל, \u0003אלא\u0004 על ה\u0003בשר\u0004 המדולדל. שכן צריכים לשנות בסוף המשנה: אם \u0003מתה הבהמה\u0004 — \u0003הבשר\u0004 המדולדל \u0003צריך הכשר,\u0004 ומקבל טומאת אוכלים. \u0003ו\u0004אילו \u0003ר' שמעון מטהר\u0004 אף אם יבואו משקים על הבשר. ובהסבר טעם שיטתו זו של ר' שמעון \u0003אמר ר' יוחנן: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון?\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"מכל האוכל אשר יאכל\", אוכל שאתה יכול להאכילו לאחרים\u0004 — \u0003קרוי אוכל, אוכל שאי\u0004 (אין) \u0003אתה יכול להאכילו לאחרים\u0004 — \u0003אין קרוי אוכל.\u0004 וכיון שהבשר המדולדל אסור באכילה אף לבני נח, ומשום אבר מן החי, לכך אין הוא מקבל טומאה כלל. \u0003האבר והבשר\u0004 שנתלשו מגוף \u0003ה\u0004אדם, ועתה הם \u0003מדולדלין באדם\u0004 החי — הריהם \u0003טהורים\u0004 אף שאינם יכולים לשוב ולהתאחות ולהירפא. אם \u0003מת האדם\u0004 — \u0003הבשר\u0004 המדולדל שבו הריהו \u0003טהור,\u0004 שדינו כדין הבשר שנשר מן האדם החי שהריהו טהור. ואילו \u0003האבר\u0004 המדולדל שבו הריהו \u0003מטמא משום אבר מן החי, ו\u0004אולם \u0003אינו מטמא משום אבר מן המת.\u0004 אלה \u0003דברי ר' מאיר, ור' שמעון מטהר\u0004 בזה ובזה. שנינו במשנתנו כי לדעת ר' מאיר האבר המדולדל לאחר מיתה מטמא משום אבר מן החי ואינו מטמא משום אבר מן המת, ואילו ר' שמעון מטהר בזה ובזה. \u0003ו\u0004תוהים: בהסבר דעתו של \u0003ר' שמעון מה נפשך\u0004 \u0005[מה רצונך]\u0006 לומר, שהרי \u0003אי\u0004 \u0005[אם]\u0006 סבור הוא ש\u0003מיתה עושה ניפול,\u0004 שנחשב האבר המדולדל כאילו נפל מן האדם בחייו — \u0003ליטמא\u0004 \u0005[שיטמא]\u0006 האבר המדולדל \u0003משום אבר מן החי! ואי\u0004 \u0005[ואם]\u0006 סבור ר' שמעון ש\u0003אין מיתה עושה ניפול,\u0004 ונחשב האבר כמחובר לגוף בשעת מיתה — מעתה \u0003ליטמא\u0004 \u0005[שיטמא]\u0006 האבר המדולדל \u0003משום אבר מן המת!\u0004","ומשיבים: אין דברי \u0003ר' שמעון\u0004 הללו מוסבים על האמור במשנתנו, אלא לענין אבר הפורש מן המת \u0003בעלמא\u0004 \u0005[סתם,\u0006 בכלל, זה הפורש מן האדם המת לאחר מותו\u0005]\u0006 \u0003קאי\u0004 \u0005[עומד,\u0006 מתייחס\u0005]\u0006 ר' שמעון. שכן שמע ר' שמעון \u0003דקאמר\u0004 \u0005[שאמר]\u0006 ה\u0003תנא קמא\u0004 \u0005[התנא הראשון\u0006 במשנתנו, ר' מאיר\u0005]\u0006 שאם מת האדם, \u0003האבר\u0004 המדולדל שבו \u0003מטמא משום אבר מן החי ואין\u0004 הוא \u0003מטמא משום אבר מן המת. אלמא\u0004 \u0005[ניתן להסיק מכאן]\u0006 כי \u0003אבר המת בעלמא\u0004 \u0005[סתם]\u0006 הריהו \u0003מטמא. ו\u0004על כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון: אבר המת בעלמא\u0004 \u0005[סתם]\u0006 \u0003לא מטמא.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 שעולה ממנה כי הרי זו מחלוקתם של תנאים קודמים. שכך \u0003אמר ר' אליעזר: שמעתי שאבר מן החי\u0004 באדם \u0003מטמא. אמר לו ר' יהושע:\u0004 אמנם שמעת כן שאבר מן החי הריהו מטמא, ואולם בשל כך סבור אתה שהכוונה דווקא לאבר שבא \u0003מן\u0004 האדם \u0003החי\u0004 הוא המטמא, \u0003ולא\u0004 אבר הבא \u0003מן המת? ו\u0004הלוא \u0003קל וחומר\u0004 הוא זה שיהא אבר הבא מן המת מטמא: \u0003ומה\u0004 אבר הבא מן האדם \u0003ה\u0004\u0003חי,\u0004 שהרי זה דבר קל, כיון \u0003שהוא\u0004 האדם הריהו \u0003טהור\u0004 — בכל זאת \u0003אבר הפורש ממנו\u0004 הינו \u0003טמא.\u0004 אבר הבא מן האדם ה\u0003מת,\u0004 שהרי זה דבר חמור, שכן \u0003הוא\u0004 המת עצמו \u0003טמא\u0004 — \u0003לא כל שכן\u0004 הוא שהאבר הפורש ממנו יהיה טמא!","ועוד הוסיף ר' יהושע ואמר: והרי \u0003כתוב במגילת תענית\u0004 כי \u0003פסחא זעירא\u0004 \u0005[פסח קטן,\u0006 י\"ד באייר\u0005]\u0006 דינו הוא \u0003דלא למספד\u0004 \u0005[שאין סופדים]\u0006 בו, והאם גם בזה תאמר: \u0003הא\u0004 \u0005[הרי]\u0006 מכאן כי דווקא ב\"פסח קטן\" אין סופדים, ואולם בפסח \u0003רבה\u0004 \u0005[גדול,\u0006 שבי\"ד בניסן\u0005]\u0006 מותר \u0003למספד\u0004 \u0005[לספוד]\u0006 בו?! \u0003אלא כל\u0004 ש\u0003כן\u0004 הוא, שאם ב\"פסח קטן\" אין סופדים, בוודאי שאין סופדים ב\"פסח גדול\". מעתה \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לומר שאם אבר הבא מן החי מטמא, \u0003כל\u0004 ש\u0003כן\u0004 שהוא הדין באבר הבא מן המת! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אליעזר: אמנם יש לומר קל וחומר זה, ואולם \u0003כך שמעתי\u0004 מרבותי. שנינו במשנתנו שלדעת ר' מאיר האבר המדולדל הבא מן המת הריהו מטמא משום אבר מן החי, ואין הוא מטמא משום אבר מן המת. \u0003ו\u0004שואלים: \u0003מאי איכא\u0004 \u0005[מה,\u0006 איזה הבדל \u0005יש]\u0006 \u0003בין\u0004 טומאת \u0003אבר מן החי ל\u0004טומאת \u0003אבר מן המת?\u0004 ומשיבים: לענין \u0003כזית בשר ועצם\u0004 ששיעורה \u0003כשעורה הפורש מאבר מן החי איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל.","","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כזית בשר הפורש מאבר מן החי\u0004 — \u0003ר' אליעזר מטמא, ור' נחוניא בן הקנה ור' יהושע מטהרין. עצם כשעורה הפורש מאבר מן החי\u0004 — \u0003ר' נחוניא מטמא, ר' אליעזר ור' יהושע מטהרין.\u0004","ואומרים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכאן,\u0006 למחלוקת תנאים זו\u0005],\u0006 אפשר לומר ש\u0003בין תנא קמא לר' שמעון נמי\u0004 \u0005[גם כן]\u0006 הבדל זה שבדין \u0003כזית בשר ועצם כשעורה איכא בינייהו\u0004",""],["\u0003הזרוע והלחיים והקבה,\u0004 שהן המתנות הניתנות לכהנים מבהמת חולין הנשחטת, \u0003נוהגין\u0004 בין \u0003בארץ\u0004 ישראל ובין \u0003ובחוצה לארץ.\u0004 בין \u0003בפני הבית\u0004 (בזמן שבית המקדש קיים), \u0003ו\u0004בין \u0003שלא בפני הבית.\u0004 ונוהגות \u0003ב\u0004בהמות \u0003חולין אבל לא ב\u0004בהמות \u0003מוקדשין\u0004 (קדשים).","וצריך לשנות במפורש שאינן ניתנות מבהמות קדשים, משום \u0003שהיה\u0004 מקום לומר \u0003בדין\u0004 (בקל וחומר) שבהמות קדשים חייבות בזרוע לחייים וקיבה. \u0003ו\u0004באופן זה: \u0003מה אם\u0004 בהמות \u0003החולין\u0004 הקלות בדינן, \u0003ש\u0004הרי \u0003אינן חייבים ב\u0004נתינת \u0003חזה ושוק\u0004 לכהנים (כקרבנות השלמים שניתנים חזה ושוק שלהם לכהנים), הריהן \u0003חייבים במתנות\u0004 (זרוע לחיים וקיבה), \u0003קדשים,\u0004 החמורים בדינם, \u0003ש\u0004כן הם \u0003חייבים ב\u0004נתינת \u0003חזה ושוק,\u0004 \u0003אינו דין ש\u0004הם \u0003חייבים במתנות?\u0004","לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \"כי את חזה התנופה ואת שוק התרומה לקחתי מאת בני ישראל מזבחי שלמיהם \u0003ואתן אותם לאהרן הכהן ולבניו לחק עולם\u0004 מאת בני ישראל\" (ויקרא ו, לד) — להורות כי \u0003אין לו\u0004 לכהן מבהמות הקדשים \u0003אלא מה שאמור בענין,\u0004 חזה ושוק, ולא זרוע לחיים וקיבה.","\u0003כל\u0004 בהמות \u0003הקדשים שקדם\u0004 בהן \u0003מום קבוע\u0004 (שאינו עובר) \u0003להקדשן,\u0004 שהקדישן הבעלים לאחר שנפל בהם מום. אף שאין להקדיש בעלי מום, ולא חלה עליהם קדושת הגוף, חלה עליהם קדושת דמים, ויש לפדותן ולהביא בדמיהן קרבנות. ואם לא נפדו — לא חלה קדושת בכורה על הבכור הנולד להן, שאין קדושה חלה על קדושה. ופטורות ממתנות זרוע לחיים וקיבה אם שחטן כבהמות קדשים. \u0003ו\u0004אם \u0003נפדו,\u0004 ואחרי כן ילדו בכור, הריהן \u0003חייבין בבכורה, ו\u0004אם שחטן הריהו חייב \u0003במתנות\u0004 (זרוע לחיים וקיבה) לכהנים, \u0003ו\u0004עם פדיונן, הן \u0003יוצאין לחולין\u0004 לגמרי, ויכולות \u0003להגזז ולהעבד, וולדן\u0004 \u0003וחלבן מותר לאחר פדיונן.\u0004","\u0003והשוחטן בחוץ\u0004 לעזרה, אף קודם שנפדו, \u0003פטור\u0004 מעונש כרת (כעונש השוחט קדשים בחוץ), שכן אינן ראויות להיקרב בפנים (כיון שהן בעלות מום). \u0003ואין\u0004 הן \u0003עושין תמורה\u0004 אף קודם פדיונן. שאם המיר בהן בהמת חולין, אין בהמת החולין מתקדשת בכך (כדין תמורה), שאינן נחשבות כקדושות לענין זה. \u0003ואם מתו\u0004 הבהמות הללו קודם שנפדו — \u0003יפדו\u0004 לאחר מותן, וינתן בשרן לכלבים. שאף שאין פודים את הקדשים להאכילם לכלבים, מכל מקום באלה (שאין בהן קדושת הגוף) הותר הדבר. \u0003חוץ מן\u0004 בהמת \u0003הבכור ומן המעשר,\u0004 שיש בהן קדושה גמורה, אף שקדם מומן להקדשן.","\u0003כל שקדם הקדשן את מומן,\u0004 שרק לאחר שהקדישן נפל בהן מום, \u0003או\u0004 שהיה בהן \u0003מום עובר\u0004 (שאינו נחשב כמום לענין זה וחלה עליהן קדושת הגוף) \u0003קודם להקדשן, ולאחר מכאן\u0004 (לאחר שהוקדשו) \u0003נולד להם מום קבוע,\u0004 והרי עתה הריהן עומדות לפדיון, \u0003ונפדו\u0004 — יצאו בכך לחולין, ואולם אם ילדו בכור, הריהן \u0003פטורין מן הבכורה, ומן המתנות, ואינן יוצאין\u0004 לגמרי \u0003לחולין\u0004 כדי \u0003להגזז ולהעבד,\u0004","\u0003וולדן\u0004 שנולד בין לפני פדיונן, ובין לאחר פדיונן (שהתעברו בו לפני פדיונן), \u0003ו\u0004כן \u0003חלבן אסור לאחר פדיונן, והשוחטן בחוץ\u0004 לעזרה, לפני פדיונן — \u0003חייב, ועושין תמורה\u0004 קודם פדיונן, שחלה קדושה על בהמת החולין שהמיר באלה. \u0003ואם מתו\u0004 קודם שנפדו — אינן נפדות לאכילת כלבים, אלא \u0003יקברו.\u0004","שנינו במשנתנו כי אין הקדשים חייבים במתנות זרוע לחיים וקיבה משום דרשת הכתוב \"ואתן אותם לאהרן הכהן ולבניו\", ונדייק: \u0003טעמא\u0004 \u0005[טעם\u0006 הדבר\u0005]\u0006 \u0005משום ש\u0006\u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"אותם\", הא לאו הכי, הוה אמינא\u0004 \u0005[הרי לולא כן, הייתי אומר]\u0006 ש\u0003קדשים חייבין במתנות,\u0004 קל וחומר מבהמות חולין?","ואולם \u0003איכא למיפרך\u0004 \u0005[יש מקום לפרוך]\u0006 את הקל וחומר ולומר: \u0003מה לחולין שכן\u0004 צד חמור יש בהם, שהם \u0003חייבין בבכורה,\u0004 שלא כקדשים. וכיון שאי אפשר לחייב את הקדשים במתנות מקל וחומר, אין צורך בפסוק לפטרם!","ומוסיפים ושואלים: \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 הלכה זו שקדשים פטורים מן המתנות, \u0003מקל וחומר\u0004 \u0003מזכרים\u0004 של בהמות חולין, שאין הם מולידים, ולפיכך אין בהם דין בכורה. ודוחים: אין זה קל וחומר \u0003מה לזכרים\u0004 שיש בהם צד חומרה \u0003שכן חייבין בראשית הגז\u0004 כשהם חולין!","ושואלים: ונלמד קל וחומר \u0003מתיישים\u0004 של חולין, שאין בהם לא דין בכורה ולא ראשית הגז, והריהם חייבים במתנות כהונה! ודוחים: אף באלה יש צד חומרה שאין בקדשים, \u0003מה לתיישים שכן נכנסין לדיר להתעשר,\u0004 שהריהם בכלל דין מעשר בהמה. מה שאין כן בבהמות קדשים!","ושואלים: יילמד הקל וחומר \u0003מ\u0004תיישים \u0003זקנים\u0004 (שכבר נכנסו לדיר להתעשר, ושוב אינם חייבים במעשר בהמה), ונמצא איפוא שאין בהם לא בכורה ולא ראשית הגז ולא מעשר בהמה. ואין צורך אם כן בדרשת הכתוב לפטור את הקדשים ממתנות כהונה! ומשיבים: אף זה אינו קל וחומר, שהרי יש לטעון: \u0003מה ל\u0004תיישים \u0003זקנים שכן\u0004 הם שייכים בדין, שכן הם \u0003נכנסו\u0004 בעבר \u0003לדיר להתעשר!\u0004","ומוסיפים ושואלים: ונלמד קל וחומר \u0003מלקוח\u0004 (בהמה הנקנית), שאין היא חייבת במעשר בהמה, ואינה נכנסת כלל לדיר להתעשר, או \u0003יתום,\u0004 \u0003שנולד לאחר שמתה אימו, שהריהו פטור ממעשר בהמה, ואינו נכנס לדיר כלל להתעשר! ודוחים:\u0004 \u0003מה ללקוח ויתום, שכן\u0004 אף שהם עצמם אינם \u0003נכנסין\u0004 לדיר להתעשר, ואולם \u0003במינן\u0004 שאר בהמות שאינן קנויות או יתומות, נכנסות \u0003לדיר להתעשר!\u0004","ותוהים על דחייה זו: \u0003במינן קאמרת\u0004 \u0005[אומר אתה],\u0006 והרי בהמות \u0003קדשים נמי\u0004 \u0005[גם כן],\u0006 שאר בהמות \u0003במינן,\u0004 שהן של חולין, \u0003נכנסין לדיר להתעשר.\u0004 ולכך הרי זה קל וחומר, וממנו נלמד כי אף קדשים חייבים במתנות כהונה. ומשום כך נצרכים אנו לדרשת \"אותם\" ללמד שאין הקדשים חייבים במתנות כהונה, ותורצו דברי המשנה.","ושואלים מצד אחר: \u0003ו\u0004מעתה \u0003יהיו חולין חייבין ב\u0004מתן \u0003חזה ושוק מקל וחומר\u0004 מקדשים: \u0003ומה קדשים\u0004 הקלים בדינם, \u0003ש\u0004הרי \u0003אין\u0004 הם \u0003חייבים במתנות\u0004 זרוע לחיים וקיבה, ומכל מקום הריהם \u0003חייבין בחזה ושוק. חולין,\u0004 החמורים בדינם, \u0003ש\u0004הרי הם \u0003חייבין במתנות\u0004 זרוע לחיים וקיבה, \u0003אינו דין ש\u0004יהיו \u0003חייבין בחזה ושוק?\u0004","לכך \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין מתנת זרוע לחיים וקיבה: \u0003\"וזה יהיה משפט הכהנים\u0004 מאת העם מאת זובחי הזבח אם שור אם שה ונתן לכהן הזרוע והלחיים והקבה\" (דברים יח, ג), ונדייק: \u0003\"זה\"\u0004 זרוע לחיים וקיבה — \u0003אין\u0004 \u0005[כן]\u0006 ניתן לכהנים, \u0003מידי אחרינא\u0004 \u0005[דבר אחר],\u0006 כחזה ושוק — \u0003לא\u0004 ניתן לכהנים מבהמת חולין הנשחטת.","ומקשים: \u0003אלא טעמא\u0004 \u0005[הטעם]\u0006 לפטור חזה ושוק בחולין משום ש\u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"זה\", הא לאו הכי, הוה אמינא\u0004 \u0005[הרי לולא כן, הייתי אומר]\u0006 ש\u0003חולין חייבין בחזה ושוק? והא\u0004 \u0005[והרי]\u0006 אי אפשר לומר כן, שכן מתנת חזה ושוק \u0003בעי\u0004 \u0005[צריכה]\u0006 \u0003תנופה\u0004 (הנפה), וחזה ושוק של בהמת חולין \u0003היכא לינופינהו\u0004 \u0005[היכן נניף אותם]?\u0006 \u0003אי אבראי\u0004 \u0005[אם מחוץ\u0006 למקדש\u0005]\u0006 — בהנפה \"להניף אותו תנופה \u0003לפני ה' \"\u0004(ויקרא ז, ל) \u0003כתיב\u0004 \u0005[נאמר],\u0006 כלומר, דווקא בבית המקדש!"],["ו\u0003אי אגואי\u0004 \u0005[אם\u0006 נניף אותם \u0005בפנים,\u0006 במקדש\u0005]\u0006 — אין לעשות כן, שהרי בכך \u0003קא מעייל\u0004 \u0005[הוא מכניס]\u0006 \u0003חולין לעזרה! הלכך, לא אפשר\u0004 לקיים הנפה בחזה ושוק של חולין, ואין איפוא צורך בכתוב ללמדנו שהם פטורים מחזה ושוק!","ושואלים: \u0003אלא\u0004 מעתה הכתוב בדין מתנת זרוע לחיים וקיבה: \"ו \u0003זה\u0004 יהיה \u0003משפט הכהנים\u0004 מאת העם זובחי הזבח אם שור אם שה ונתן לכהן הזרוע והלחיים והקבה\" (דברים יח, ג), \u0003למה לי?\u0004 ומשיבים: הדבר נצרך \u0003ל\u0004הלכה זו \u0003כ\u0004דברי \u0003רב חסדא,\u0004 שכן \u0003אמר רב חסדא: המזיק מתנות כהונה או שאכלן\u0004 קודם שנתנם לכהן — \u0003פטור מלשלם.\u0004 שכן אמר הכתוב \"וזה\" — שדווקא הזרוע הלחיים והקיבה עצמן הן שניתנות לכהן, ולא תמורתן. למעלה הובאה הלכה בשמו של רב חסדא, ועתה דנים \u0003בה\u0004","\u0003גופא\u0004 \u0005[עצמה].\u0006 \u0003אמר רב חסדא: המזיק מתנות כהונה, או שאכלן\u0004 — \u0003פטור מלשלם\u0004 לכהן את תמורתם. ומבררים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003איבעית אימא דכתיב\u0004 \u0005[אם תרצה אמור\u0006 משום \u0005שכתוב]\u0006 \u0003\"זה\"\u0004 — דווקא הזרוע הלחיים והקיבה עצמן ניתנות לכהן, ולא תמורתן. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 טעם אחר: \u0003משום דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003ממון שאין לו תובעים,\u0004 שהרי אין כהן מסויים שיכול לתבוע את הממון הזה ממנו, שאין המתנה שייכת לכהן מסויים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: הכתוב \u0003\"וזה יהיה משפט הכהנים\"\u0004 — \u0003מלמד שהמתנות\u0004 הניתנות לכהנים הינן \u0003דין\u0004 (\"משפט\"). ויש לברר: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נאמר הדבר? \u0003לאו\u0004 \u0005[האם לא]\u0006 לענין \u0003להוציאן בדיינין,\u0004 שיכולים הכהנים לתבוע אותן בבית הדין, ומורים בית דין לבעלים לתת להם, ושלא כדברי רב חסדא! ודוחים: \u0003לא,\u0004 כוונת הדברים לענין \u0003לחולקן בדיינין,\u0004 שבית הדין מורה לבעלים למי לתת אותן, \u0003וכ\u0004דברי","\u0003רב שמואל בר נחמני,\u0004 שכן \u0003אמר רב שמואל בר נחמני, אמר ר' יונתן: מנין שאין נותנין מתנה\u0004 (של כהונה) \u0003לכהן עם הארץ? שנאמר \"ויאמר לעם ליושבי ירושלים לתת מנת לכהנים וללוים למען יחזקו בתורת ה' \"\u0004(דברי הימים ב לא, ד), לומר ש\u0003כל\u0004 כהן \u0003המחזיק בתורת ה'\u0004 — \u0003יש לו מנת\u0004 (מתנת כהונה), \u0003ו\u0004אילו כהן זה \u0003שאינו מחזיק בתורת ה'\u0004 — \u0003אין לו מנת.\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא לענין דברי רב חסדא אלה, \u0003ר' יהודה בן בתירא אומר:\u0004 הכתוב \"וזה יהיה \u0003משפט\u0004 הכהנים\" — \u0003מלמד שהמתנות דין. יכול אפילו\u0004 מתנת \u0003חזה ושוק\u0004 הינה \u0003דין?\u0004 \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"זה\"\u0004 שהיא לשון מיעוט: דווקא מתנת \u0003זרוע לחיים וקיבה הן דין, ולא מתנת חזה ושוק.\u0004","ויש לברר: \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ענין אמר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 לענין \u0003לחולקו בדיינין,\u0004 ולהשמיענו שאין חזה ושוק \u0003מתחלקים על פי הוראת בית דין\u0004 — \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003חזה ושוק לאו\u0004 \u0005[לא]\u0006 \u0003בדיינין מיחלקו\u0004 \u0005[מתחלקים]?\u0006 והרי בהוראת בית דין אין הם ניתנים לכהן עם הארץ! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 לענין \u0003להוציא בדיינין,\u0004 ומכאן שמתנות כהונה (מלבד חזה ושוק) ניתנות לתובע על פי הוראת בית דין, ושלא כדעת רב חסדא!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003דאתו לידיה\u0004 \u0005[ש\u0006כבר \u0005באו\u0006 המתנות \u0005לידו\u0006 של הכהן\u0005],\u0006 ואחר כך גזלו הבעלים הראשונים אותן מידי הכהן, ולמדנו שיכול הכהן לתבוע בבית דין את מתנותיו, ובית דין מורה לבעלים לתיתן לכהן. ותוהים: \u0003אי דאתו לידיה\u0004 \u0005[אם\u0006 מדובר באופן \u0005ש\u0006כבר \u0005הגיעו לידו]\u0006 של הכהן, \u0003מאי למימרא\u0004 \u0005[מה יש לומר\u0006 בזה\u0005],\u0006 ודאי שיכול הכהן לתובען בבית דין, שהרי הן שלו! ומשיבים: מדובר באופן \u0003דאתו לידיה בטבלייהו\u0004 \u0005[שבאו לידו בטבלם,\u0006 לפני שהופרשו מתנותיהן\u0005],\u0006 \u0003וקסבר האי תנא\u0004 \u0005[וסבור תנא זה]\u0006 כי \u0003מתנות שלא הורמו\u0004 עדיין — \u0003כמי שהורמו דמיין\u0004 \u0005[נחשבות],\u0006 והריהן של הכהן, ולקיחתן ממנו בעל כרחו הריהי גזל.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 עוד לענין דעת רב חסדא, ממה ששנינו: \u0003בעל הבית\u0004 (עשיר) \u0003שהיה עובר ממקום למקום,\u0004 ובתוך כך נגמר כספו והוא זקוק לאוכל, כעני, \u0003וצריך\u0004 איפוא \u0003ליטול לקט שכחה ופאה ומעשר עני\u0004 כדי לקיים את עצמו — הרי זה \u0003נוטל\u0004 לפי שעה, \u0003ולכשיחזור\u0004 לביתו יטול מכספו ו\u0003ישלם\u0004 מה שלקח לעני. אלו דברי ר' אליעזר. והרי זה שלא כדעת רב חסדא!","\u0003אמר רב חסדא:\u0004 \u0003מדת חסידות שנו כאן,\u0004 ומן הדין אין העשיר יכול להיתבע בבית דין על כך. \u0003אמר רבא\u0004 בתמיהה על הסברו של רב חסדא: \u0003תנא תני\u0004 \u0005[התנא שנה]\u0006 \u0003\"ישלם\",\u0004 שמשמעה חובה, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 ש\u0003מדת חסידות שנו כאן?! ועוד\u0004 תמיהה על עצם השאלה \u0003מ\u0004דברי \u0003ר' אליעזר:\u0004 וכי ממנו \u0003ליקום וליתוב\u0004 \u0005[אתה קם ומקשה]?\u0006 הרי דבריו נדחו מן ההלכה?","\u0003אלא מסיפא\u0004 \u0005[מסופה]\u0006 של אותה הלכה הקשו על רב חסדא, ששנינו, \u0003וחכמים אומרים:\u0004 אין אותו בעל הבית צריך לשלם לעניים בבואו לביתו, משום ש\u0003עני היה באותה שעה\u0004 כשנזקק לקחת מתנות עניים. ונדייק: \u0003טעמא\u0004 \u0005[טעם\u0006 הדבר\u0005]\u0006 \u0005משום שבאותה עת הוא היה\u0006 \u0003עני, הא\u0004 \u0005[הרי]\u0006 אם \u0003היה\u0004 \u0003עשיר\u0004 באותה עת, ולקח מתנות עניים שלא כדין — \u0003משלם\u0004 לעניים התובעים אותו בבית דין, ויש לברר:","\u0003אמאי\u0004 \u0005[מדוע]\u0006 ישלם? \u0003ליהוי\u0004 \u0005[יהא]\u0006 דינו \u0003כמזיק מתנות כהונה או שאכלן,\u0004 שלדעת רב חסדא הריהו פטור מלשלם. ושלא כשיטת רב חסדא! ועל כך \u0003אמר רב חסדא:\u0004 אף העשיר שאכל מתנות עניים אינו חייב מן הדין לשלם להם, אלא אם כן רוצה בכך, ו\u0003מידת חסידות שנו כאן.\u0004","ומציעים עוד בבירור שיטת רב חסדא: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003מנין לבעל הבית שאכל\u0004 את \u0003פירותיו\u0004 כשהם \u0003טבלין,\u0004 שלא הפריש מהם תרומות ומעשרות כדין, ואכל את כולם. \u0003וכן לוי שאכל מעשרותיו\u0004 כשהם \u0003טבלים\u0004 ולא הפריש מהם תרומת מעשר לכהן, \u0003מנין ש\u0004הוא \u0003פטור מן התשלומין? תלמוד לומר \"ולא יחללו את קדשי בני ישראל\u0004 את \u0003אשר ירימו\u0004 לה' \" (ויקרא כב, טו) — \u0003אין לך\u0004 הכהן זכות \u0003בהן אלא משעת הרמה ואילך,\u0004 וכיון שאכלם לפני שהרים מהם את תרומותיו ומעשרותיו, אין זכות תביעה לכהן עליהן. ונדייק:","\u0003הא\u0004 \u0005[הרי]\u0006 אם אכלם \u0003משעת הרמה ואילך מיהא\u0004 \u0005[על כל פנים]\u0006 יש זכות תביעה לכהן על מעשרותיו, ו\u0003משלם\u0004 האוכלם. ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 חייב לשלם, \u0003ליהוי\u0004 \u0005[שיהא]\u0006 דינו \u0003כמזיק מתנות כהונה או שאכלן,\u0004 וכשיטת רב חסדא שהריהו פטור! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר"],["\u0003דאתו לידיה בטבלייהו\u0004 \u0005[שבאו\u0006 הפירות בתחילה \u0005לידיו\u0006 של הכהן \u0005בטבלם],\u0006 \u0003וקסבר האי תנא\u0004 \u0005[וסבור תנא זה]\u0006 כי \u0003מתנות שלא הורמו\u0004 — \u0003כמי שהורמו דמיין\u0004 \u0005[הן נחשבות],\u0006 ולכך זכה בהם הכהן מן ההפקר (שהרי קדם לכל כהן אחר בתפיסתן), ומסירתם לכהן, אף שהם עדיין בטבלם, נחשבת כ\"משעת הרמה\", ולכך חייב בעל הבית על אכילתם. ומציעים עוד בבירור דברי רב חסדא,","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003הרי שאנסו\u0004 אנשי \u0003בית המלך\u0004 את הבעלים למסור להם את \u0003גרנו\u0004 (ערימת התבואה), \u0003אם\u0004 היה זה \u0003ב\u0004פרעון \u0003חובו,\u0004 שהיה חייב להם סכום כסף מוגדר שנזקף עליו כחוב — הריהו \u0003חייב לעשר\u0004 מתבואות אחרות שיש לו, כשיעור המעשרות שהיה מפריש מהתבואה שנלקחה ממנו. שהרי כבר נתחייב בהפרשת מעשרותיה, וכאילו מכרה לאחר. ואולם \u0003אם באנפרות\u0004 \u0005[בשרירות]\u0006 נלקחה ממנו התבואה בידי אנשי בית המלך — הריהו \u0003פטור מלעשר.\u0004 ומתוך שחייב לשלם לכהן את מעשרות תבואה שנלקחה ממנו בפרעון חובו, נלמד שהרי זה ממון שיש לו תובעים (שאילולי היה צריך לשלם בעל כרחו, לא היה צריך להפריש תבואה ממקום אחר), ושלא כשיטת רב חסדא!","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 הדין, משום שנמצא \u0003דקא משתרשי ליה\u0004 \u0005[שהוא מרויח לו]\u0006 בזה שנלקחה ממנו התבואה בחובו, שמעתה אין הוא צריך להפריש ממנה מעשרות שהתחייב כבר בהם. לכך אמרה הברייתא שחייב להפריש מעשרות ממקום אחר, ולא משום שהוא נתבע על ידי הכהנים לשלם להם.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003אמר לו\u0004 ישראל לטבח \u0003\"מכור לי בני מעיה של פרה\"\u0004 מסויימת, \u0003והיה בהן\u0004 בתוך המעיים \u0003מתנות כהונה\u0004 (קיבה) שלא ניתנו לכהן — הקונה הוא ש\u0003נותנן\u0004 את המתנות \u0003לכהן, ו\u0004הטבח \u0003אינו מנכה לו\u0004 בשל כך \u0003מן הדמים\u0004 ששילם עבור בני המעיים, שכן ידע הקונה שהקיבה נמצאת בבני המעיים ואינה בכלל המכירה. ואולם אם \u0003לקח\u0004 (קנה) \u0003הימנו\u0004 (ממנו) \u0003במשקל,\u0004 ששילם עבור משקל מסויים של בני מעיים — הקונה אמנם \u0003נותנן לכהן\u0004 את מתנותיו, \u0003ו\u0004אולם הטבח \u0003מנכה לו\u0004 את משקל הקיבה \u0003מן הדמים\u0004 שקיבל.","ומעתה יש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 נדרש הקונה לתת את הקיבה לכהן, \u0003ליהוי\u0004 \u0005[יהא]\u0006 נחשב הטבח שמכר בני מעיה של פרה עם הקיבה שבהם, \u0003כמזיק מתנות כהונה או שאכלן,\u0004 שלשיטת רב חסדא הריהו פטור מלשלם. ושלא כשיטת רב חסדא! ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 הדין, שהקונה חייב לתת את מתנות הכהונה שבידו משום \u0003דאיתנהו בעיניהו\u0004 \u0005[ש\u0006הן \u0005נמצאות בעינן,\u0006 שלא נאכלו או אבדו\u0005],\u0006 ורב חסדא דיבר באופן שאינן בעין.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת לענין דברי רב חסדא, ממה ששנינו: \u0003תשעה\u0004 דברים הם \u0003נכסי כהן:\u0004 ה\u0003תרומה,\u0004 \u0003ותרומת מעשר, וחלה, ראשית הגז, ומתנות, והדמאי, והבכורים, ו\u0004שווים של של נכסי הגר שנגזלו בידי אדם, ונשבע הגזלן לשקר שלא גזלו, ולאחר מכן מת הגר בלא יורשים, והודה הגזלן שנשבע לשקר שהריהו משלם לכהן את שווי \u0003ה\u0004\u0003קרן\u0004 של נכסי הגר, \u0003ו\u0004בתוספת \u0003החומש\u0004 (חמישית) שלהם.","ונברר: \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ענין\u0005]\u0006 אמרו בדברים הללו שהם נכסי כהן? \u0003לאו\u0004 \u0005[האם לא]\u0006 לענין \u0003להוציאן בדיינין,\u0004 ושלא כשיטת רב \u0003חסדא!\u0004 ודוחים: \u0003לא,\u0004 כוונת הדברים \u0003לכדתנן\u0004 \u0005[לכמו ששנינו]:\u0006 \u0003למה אמרו\u0004 שהם \u0003נכסי כהן? שקונה בהן עבדים וקרקעות ובהמה טמאה, ובעל חוב\u0004 של הכהן \u0003נוטלן ב\u0004פרעון \u0003חובו, ואשה\u0004 של כהן המתגרשת ממנו נוטלת מהם \u0003בכתובתה, ו\u0004יכול הכהן לקנות בדמי אלה \u0003ספר תורה.\u0004","מסופר: \u0003ההוא ליואה דהוה חטף מתנתא\u0004 \u0005[לוי אחד שהיה חוטף מתנות\u0006 כהונה, זרוע לחיים וקיבה\u0005]\u0006 מידיהם של ילדים שהיו מוליכים את מתנות אביהם לכהן. \u0003אתו\u0004 \u0005[באו]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לרב\u0004 שכך נוהג אותו לוי. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא מסתייה\u0004 \u0005[לא דיו]\u0006 שכאשר הוא שוחט את בהמתו \u0003דלא שקלינן מיניה\u0004 \u0005[שאין אנו לוקחים ממנו]\u0006 מתנות \u0003כהונה,\u0004 \u0003אלא\u0004 הוא \u0003מיחטף נמי חטיף\u0004 \u0005[לחטוף גם כן חוטף]\u0006 מתנות הנשלחות לכהן?!","ושואלים: \u0003ו\u0004לדעת \u0003רב, אי איקרו\u0004 \u0005[אם\u0006 הלוים \u0005נקראים]\u0006 \u0003\"עם\"\u0004 — \u0003משקל נמי לשקול מינייהו\u0004 \u0005[שיקחו גם כן מהם]\u0006 זרוע לחיים וקיבה, שהריהם בכלל הנאמר במצות נתינת זרוע לחיים וקיבה \"מאת העם מאת זובחי הזבח\" (דברים יח, ג). ו\u0003אי לא איקרו\u0004 \u0005[אם לא נקראים]\u0006 הלוים \u0003\"עם\"\u0004 — \u0003רחמנא פטרינהו\u0004 \u0005[התורה פטרה אותם],\u0006 ואין אנו עושים להם טובה אם איננו לוקחים מהם מתנות זרוע לחיים וקיבה!","ומשיבים: \u0003מספקא ליה אי איקרו\u0004 \u0005[מסופק היה לו\u0006 לרב \u0005אם נקראים]\u0006 הלוים \u0003\"עם\" אי לא איקרו\u0004 \u0005[או לא נקראים]\u0006 \u0003\"עם\".\u0004 ומשום הספק פטר את הלוים מלתת מתנות לכהן, שהרי כלל הוא שהמוציא מחבירו עליו הראיה.","ובענין זה מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב פפא וקאמר לה להא שמעתא\u0004 \u0005[ואמר את ההלכה הזו]\u0006 של רב. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב אידי בר אבין לרב פפא\u0004 ממה ששנינו, \u0003ארבע מתנות עניים\u0004 הן \u0003שב\u0004פירות ה\u0003כרם,\u0004 ואלו הן: \u0003הפרט\u0004 (גרגרי ענבים מועטים הנושרים מן האשכול בזמן הבציר), \u0003והעוללות\u0004 (אשכולות ענבים שאינם שלמים), \u0003והשכחה\u0004 (אשכולות ענבים הנשכחים בכרם), \u0003והפאה\u0004 (מעט אשכולות בקצה הכרם). \u0003ושלש\u0004 מתנות עניים הן \u0003שבתבואה: הלקט\u0004 (שיבולים הנושרות בזמן הקצירה) \u0003והשכחה, והפאה. שנים\u0004 מתנות עניים הן \u0003שב\u0004פירות ה","\u0003אילן: השכחה, והפאה. כולן אין בהם טובת הנאה לבעלים,\u0004 שאין לבעלים זכות בהם, אפילו זכות לחלק אותם לאדם מסויים, וכל הקודם וזכה בהן, הריהן שלו. \u0003ואפילו עני שבישראל\u0004 שיש לו כרם או שדה תבואה או אילן חייב לתת מתנות עניים בפירותיו, ואם אינו נותנן — בית דין \u0003מוציאין מידו.\u0004","ואולם \u0003מעשר עני\u0004 (המופרש מן התבואות והפירות בשנים השלישית והשישית לשנות השמיטה) \u0003המתחלק בתוך ביתו\u0004 (שלא כשאר מתנות עניים הניתנות בהיות הפירות בשדה) \u0003—\u0004 \u0003יש בו טובת הנאה לבעלים,\u0004 שרשאי לתת את מעשר העני שברשותו לאיזה עני שירצה. \u0003ו\u0004בדומה לשאר מתנות עניים, \u0003אפילו עני שבישראל\u0004 אם אינו מפריש מפירותיו מעשר עני — בית הדין עומדים ו\u0003מוציאין אותו מידו. ו\u0004אילו \u0003שאר מתנות כהונה, כגון הזרוע והלחיים והקבה\u0004 אינן כמתנות עניים, ש\u0003אין מוציאין אותן לא מכהן\u0004 אחד ליתנן \u0003לכהן\u0004 אחר, \u0003ולא מלוי\u0004 אחד ליתנן \u0003ללוי\u0004 אחר. ועתה מפרשים את דברי ברייתא זו.","שנינו בה כי \u0003ארבע מתנות\u0004 עניים הן \u0003שב\u0004פירות ה\u0003כרם, הפרט, והעוללות, והשכחה, והפאה.\u0004 ומפרטים את מקורן בכתובים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכרמך לא תעולל ופרט כרמך לא תלקט\u0004 לעני ולגר תעזוב אותם\" (ויקרא יט, י)","\u0003—\u0004 שמצוה להניח את העוללות לעני (\"לא תעולל\"), וכן את הפרט (\"ופרט... לא תלקט\"). \u0003ו\u0004עוד \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"כי תבצור כרמך לא תעולל אחריך\u0004 לגר ליתום ולאלמנה יהיה\" (דברים כד, כא), \u0003אמר ר' לוי: \"אחריך\"\u0004 — \u0003זו\u0004 רמז ל\u0003שכחה,\u0004 שעומר השכחה הוא זה שנשכח מאחוריו של הקוצר, ואילו זה שלפניו — אינו שכחה. ובאשר למקור מצות","\u0003פאה\u0004 שחייבים גם בה בפירות הכרם — \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003\"אחריך\" \"אחריך\" מ\u0004מה שנאמר ב\u0003זית, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי תחבוט זיתך לא תפאר אחריך\u0004 לגר ליתום ולאלמנה יהיה\" (דברים שם, כ), \u0003ותנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005של בית]\u0006 מדרשו של \u0003ר' ישמעאל\u0004 בפירוש הלשון \"לא תפאר\": \u0003שלא תטול תפארתו ממנו\u0004 אלא תשאיר פאה.","ועוד שנינו בברייתא כי \u0003שלשה\u0004 מתנות עניים הן \u0003שבתבואה,\u0004 והן: \u0003הלקט,\u0004"],["\u0003השכחה, והפאה,\u0004 ומפרטים את מקורן בכתובים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ובקוצרכם את קציר ארצכם לא תכלה פאת שדך בקוצרך ולקט קצירך\u0004 לא תלקט לעני ולגר תעזוב אותם\" (ויקרא כג, כב) — הרי אלה מצוות פאה ולקט. ועוד נאמר \u0003\"כי תקצור קצירך בשדך ושכחת עומר בשדה\u0004 לא תשוב לקחתו לגר ליתום ולאלמנה יהיה\" (דברים כד, יט) — הרי זו מצות שכחה.","ועוד שנינו בברייתא בענין מתנות עניים כי \u0003שנים\u0004 הן \u0003ש\u0004מצוותן \u0003באילן:\u0004 \u0003השכחה והפאה, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"כי תחבוט זיתך לא תפאר אחריך\u0004 לגר ליתום ולאלמנה יהיה\" (שם כד, כ)\u0003, ותנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005של בית]\u0006 מדרשו של \u0003ר' ישמעאל\u0004 בפירוש הכתוב \"לא תפאר\": \u0003שלא תטול תפארתו ממנו,\u0004 אלא הותר פאה בפירות האילן, והנאמר \u0003\"אחריך\"\u0004 — \u0003זה שכחה.\u0004","\u0003וכולן,\u0004 כל מתנות העניים, \u0003אין בהן טובת הנאה לבעלים,\u0004 שאין בידי הבעלים לתיתן דווקא למי שהם רוצים, אלא כל עני זכאי בהן, ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם,\u0006 מקור\u0005]\u0006 הדבר? שכן לשון \u0003\"עזיבה\"\u0004 (\"תעזוב אותם\") \u0003כתיבא בהו\u0004 \u0005[נאמרה בהן].\u0006","\u0003ו\u0004עוד שנינו בברייתא כי \u0003אפילו עני שבישראל\u0004 אם יש לו שדה או כרם, \u0003מוציאין אותו\u0004 את מתנות העניים \u0003מידו, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ולקט קצירך לא תלקט לעני ולגר תעזוב אותם\"\u0004 — \u0003להזהיר\u0004 אף את ה\u0003עני על\u0004 התבואה והפירות \u0003שלו\u0004 לתת מהם מתנות עניים.","\u0003ו\u0004עוד שנו בברייתא כי \u0003מעשר עני המתחלק בתוך הבית יש בו טובת הנאה לבעלים,\u0004 שיכול לתת אותו לכל עני שירצה. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? שכן במעשר עני לשון \u0003\"נתינה\" כתיבא ביה\u0004 \u0005[כתובה בו]\u0006 (\"כי תכלה לעשר את כל מעשר תבואתך בשנה השלישית שנת המעשר ונתתה ללוי לגר ליתום ולאלמנה ואכלו בשעריך ושבעו\". שם כו, יב).","\u0003ו\u0004בענין ששנינו כי \u0003אפילו עני שבישראל מוציאין אותו\u0004 את מעשר העני \u0003מידו,\u0004 \u0003אמר ר' אילעא, גמר\u0004 \u0005[למד\u0006 בגזירה שווה\u0005]\u0006 מן המלים \u0003\"לגר\" \"לגר\" מהתם\u0004 \u0005[משם,\u0006 ממצות לקט\u0005],\u0006 \u0003מה להלן\u0004 \u0005[שם],\u0006 במצות לקט — \u0003מוזהר עני על שלו,\u0004 לתת מתבואתו ופירותיו לקט, \u0003אף כאן\u0004 במצות מעשר עני — \u0003מוזהר עני על שלו.\u0004","\u0003ו\u0004עוד שנינו בברייתא כי \u0003שאר מתנות כהונה, כגון הזרוע והלחיים והקבה, אין מוציאין אותן לא מכהן לכהן ולא מלוי ללוי.\u0004 ומדייקים: דווקא מאלה אין מוציאים, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מלוי לכהן\u0004 — \u0003מוציאין, אלמא\u0004 \u0005[מכאן]\u0006 נסיק כי הלויים \u0003איקרו\u0004 \u0005[נקראים]\u0006 \u0003\"עם\",\u0004 ולכך נוטלים מהם את המתנות, שכן נאמר במתנת זרוע לחיים וקיבה \"וזה יהיה משפט הכהנים מאת העם זובחי הזבח אם שור אם שה ונתן לכהן הזרוע לחיים והקיבה\" (שם יח, ג). ושלא כרב שהסתפק אם הלויים נקראים \"עם\"!","ודוחים: אין הכוונה בברייתא למתנות זרוע לחיים וקיבה ממש אלא בשאר מתנות כהונה \u0003כגון\u0004 (כמו, בדומה) \u0003הזרוע\u0004 לחיים וקיבה, \u0003ו\u0004אולם \u0003לא זרוע\u0004 לחיים וקיבה עצמם. \u0003ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 — \u0003מעשר ראשון.\u0004","ותוהים: \u0003מעשר ראשון\u0004 של \u0003לוי הוא\u0004 ומדוע מוציאים אותו מידו? ומשיבים: שיטת הברייתא \u0003כ\u0004דעת \u0003ר' אלעזר בן עזריה\u0004 הסבור כי מעשר ראשון ניתן לכהן ולא \u0003ללוי.\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 ה\u0003תרומה\u0004 — ניתנת \u0003לכהן, מעשר ראשון\u0004 — \u0003ללוי,\u0004 אלה \u0003דברי ר' עקיבא. ר' אלעזר בן עזריה אומר:\u0004 מעשר ראשון אף שנאמר בתורה שהוא ניתן ללוי, הריהו ניתן \u0003אף לכהן,\u0004 שכן במקומות רבים נקראים הכהנים \"לויים\".","ושואלים: \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' אלעזר בן עזריה\u0004 כי מעשר ראשון ניתן \u0003אף לכהן,\u0004 ואולם שיהא ניתן רק \u0003לכהן ולא ללוי מי\u0004 \u0005[האם]\u0006 \u0003אמר,\u0004 ואיך אם כן מוציאים את המעשר הראשון מידי הלוי לתתו לכהן? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 אכן מעיקר הדין אין מוציאים מן הלוי כדי לתיתו לכהן, ואולם מדובר \u0003לבתר דקנסינהו\u0004 \u0005[לאחר שקנסם]\u0006 \u0003עזרא\u0004 את הלויים שלא יתנו להם מעשר ראשון, מפני שלא עלו לארץ ישראל.","ושואלים: \u0003אימר דקנסינהו\u0004 \u0005[אמור שקנסם]\u0006 \u0003עזרא\u0004 — \u0003דלא יהבינן להו\u0004 \u0005[שלא ניתן להם]\u0006 מעשר ראשון, ואולם \u0003משקל מינייהו\u0004 \u0005[לקחת מהם]\u0006 מעשר ראשון שכבר ניתן להם, ולתיתו לכהנים, \u0003מי\u0004 \u0005[האם]\u0006 גם כן \u0003אמר?! אלא\u0004 יש להציע הסבר אחר: אין כוונת דברי הברייתא לזרוע לחיים וקיבה ממש, אלא לשאר מתנות כהונה שהן \u0003כגון זרוע\u0004 לחיים וקיבה, \u0003ולא זרוע\u0004 לחיים וקיבה ממש, \u0003ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 — \u0003ראשית הגז.\u0004 שבמצוה זו נאמר \"וראשית גז צאנך תתן לו\" (שם יח, ד), ולא נאמר בה \"מאת העם\", לכך אף הלוי חייב בנתינת ראשית הגז לכהן, ומוציאים אותה מתחת ידו.","ומציעים עוד בענין זה: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ראיה שלא כדברי רב ממה ששנינו בברייתא, \u0003זה הכלל: כל דבר שהוא בקדושה\u0004 שאסור באכילה למי שאינם כהנים, \u0003כגון תרומה ותרומת מעשר וחלה\u0004 — \u0003מוציאין אותן מידם\u0004 של לויים לתיתם לכהן. \u0003וכל דבר שאינו בקדושה, כגון הזרוע והלחיים והקבה\u0004 (שהרי הן באות מבהמות של חולין) — \u0003אין מוציאין אותו מידם\u0004 של הלויים לתיתן לכהנים. משום שאין הלויים נקראים \"עם\", ואינם נכללים איפוא בציווי \"מאת העם\". ושלא כדברי רב שהסתפק אם הם נקראים \"עם\"! ודוחים: אין הכוונה לזרוע לחיים וקיבה, אלא לשאר מתנות כהונה, שהן","\u0003כגון זרוע\u0004 לחיים וקיבה, \u0003ו\u0004אולם \u0003הן\u0004 \u0003לא\u0004 ממש \u0003זרוע\u0004 לחיים וקיבה, \u0003ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 — \u0003מעשר ראשון, ו\u0004מדובר \u0003לבתר דקנסינהו\u0004 \u0005[ולאחר שקנסם]\u0006 \u0003עזרא,\u0004 שלא יתנו להם \u0003עוד את המעשר הראשון אלא לכהנים. ואולם אם כבר ניתן מעשר ראשון ללוי —\u0004 אין מוציאים מידו, שעל כך לא גזר עזרא.","ומציעים עוד בענין זה: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ראיה שלא כדברי רב ממה ששנינו בברייתא: ישראל \u0003השוחט\u0004 בהמה \u0003לכהן ו\u0004כן אם שוחט \u0003לגוי\u0004 — הריהו \u0003פטור מן המתנות,\u0004 שהן כהן והן גוי פטורים מנתינת מתנות כהונה. ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם שחט \u0003ללוי ולישראל\u0004 — \u0003חייב\u0004 במתנות כהונה, ומוציאים מתחת ידו, והרי שלוי הוא בכלל \"עם\" שלא כרב שהסתפק בדבר! ודוחים: אין זו קושיה על דברי רב, שכן \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 בדיוק דברי הברייתא \u0003הא\u0004 \u0005[הרי]\u0006 מכאן שהשוחט \u0003ללוי ולישראל חייב, אלא\u0004 כך \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 מכאן שהשוחט \u0003לישראל\u0004 — \u0003חייב\u0004 במתנות כהונה.","ומקשים על הסבר זה: \u0003אבל ללוי מאי\u0004 \u0005[מה]\u0006 יהא הדין — שהשוחט לו בהמה הריהו \u0003פטור\u0004 ממתנות כהונה, \u0003אי הכי, ליתני\u0004 \u0005[אם כן, שישנה]\u0006 בברייתא \u0003\"השוחט ללוי ולגוי פטור מן המתנות\"\u0004, ומכאן נדע שהוא הדין בשוחט לכהן! \u0003ועוד:\u0004 \u0003הא תניא\u0004 \u0005[הרי שנינו\u0006 בברייתא\u0005]\u0006 במפורש ש\u0003השוחט לכהן ולגוי\u0004 — אכן \u0003פטור מן המתנות,\u0004 ואולם השוחט \u0003ללוי ולישראל\u0004 — \u0003חייב\u0004 במתנות כהונה, והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי","\u0003רב!\u0004 ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רב\u0004 כי אמנם דברי ברייתא זו הינם שלא כדבריו, ואולם מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא\u0004 השאלה אם הלויים נקראים \"עם\". \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על הכתוב בסיכום סדר העבודה ביום הכיפורים \"וכיפר את מקדש הקודש ואת אהל מועד ואת המזבח יכפר ועל הכהנים ועל כל עם הקהל יכפר\" (ויקרא טז, לג): \u0003\"וכפר את מקדש הקדש\"\u0004 — \u0003זה לפני ולפנים,\u0004 שקרבנות הפר והשעיר של יום הכפורים מכפרים על טומאה שאירעה בקודש הקדשים.","\u0003\"אהל מועד\"\u0004 — \u0003זה היכל,\u0004 שהם מכפרים על טומאה שאירעה בו. \u0003\"מזבח\"\u0004 — \u0003כמשמעו,\u0004 שהם מכפרים על טומאה שהיתה בעבודות שבמזבח. \u0003\"יכפר\"\u0004 — \u0003אלו עזרות\u0004 שבמקדש, שהם מכפרים את הטומאה שאירעה בהן. \"ועל \u0003ה\u0004\u0003כהנים\"\u0004 — \u0003כמשמעו,\u0004 אם שגגו ונכנסו טמאים לעזרה. \"ועל כל \u0003עם הקהל\"\u0004 — \u0003אלו ישראל, \"יכפר\"\u0004 — \u0003אלו הלוים.\u0004","\u0003ותניא אידך\u0004 \u0005[ושנינו\u0006 עוד ברייתא \u0005אחרת]\u0006 בדרשת כתוב זה: \u0003\"יכפר\"\u0004 — \u0003אלו עבדים\u0004 כנענים שבידי ישראל, שחייבים במקצת מצוות, ונדרשת גם עליהם כפרה. וטעם הדבר שבברייתא זו לא נדרש הכתוב ללויים כבברייתא הקודמת, אלא לעבדים כנענים, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 משום ש\u0003בהא קמיפלגי\u0004 \u0005[בזה הן\u0006 הברייתות הללו, \u0005חלוקות],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 בברייתא השניה, \u0005סבור]\u0006 כי הלוים \u0003איקרו\u0004 \u0005[נקראים]\u0006 \u0003\"עם\",\u0004 ונכללים הם בכתוב \"עם הקהל\", והכתוב הנוסף \"יכפר\" בא ללמד על עבדים כנענים. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 בברייתא הראשונה, \u0005סבור]\u0006 כי הלוים \u0003לא איקרו\u0004 \u0005[אינם נקראים]\u0006 \u0003\"עם\",\u0004 ואין הם נכללים בדרשת \"עם הקהל\", והכתוב הנוסף \"יכפר\" בא ללמד על הלויים.","ושואלים: \u0003ורב\u0004 המסתפק אם הלויים נקראים \"עם\", עתה שראינו כי חלוקים תנאים בשאלה זו, \u0003אי סבירא ליה כהאי תנא\u0004 \u0005[אם סבור הוא כתנא\u0006 זה, אחד מהם] — \u0003לימא\u0004 \u0005[שיאמר]\u0006 כדעתו של תנא זה, \u0003ואי סבירא ליה כהאי תנא\u0004 \u0005[ואם סבור הוא כתנא\u0006 זה, האחר] — \u0003לימא\u0004 \u0005[שיאמר]\u0006 כדעתו של תנא זה! ומסבירים: \u0003מספקא ליה אי כהאי תנא אי כהאי תנא\u0004 \u0005[מסופק לו לרב אם\u0006 ההלכה \u0005כתנא זה אם כתנא זה].\u0006","ובהכרעת הנדון \u0003דרש מרימר: הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רב\u0004 שספק אם הלויים נקראים \"עם\", ולכך אין מחייבים את הלויים לתת זרוע לחיים וקיבה לכהנים. \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב חסדא\u0004 שהמזיק מתנות כהונה או שאכלן פטור מלשלמן לכהנים.","ועוד בענין מתנות כהונה למי שאינו כהן, נמסר כי \u0003עולא הוה יהיב מתנתא לכהנתא\u0004 \u0005[היה נותן מתנות\u0006 כהונה \u0005לכהנת,\u0006 בת כהן\u0005],\u0006 אף שהיא נשואה לישראל, \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לעולא\u0004 על הנהגתו זו ממה ששנינו כי שיריי \u0003מנחת כהנת\u0004 — \u0003נאכלת,\u0004 כשיירי מנחת ישראל. ואילו שיירי \u0003מנחת כהן\u0004 — \u0003אינה נאכלת,\u0004 שכן נאמר במנחת כהן \"וכל מנחת כהן כליל תהיה לא תאכל\" (ויקרא ו, טז).","\u0003ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 שאפשר לתת מתנות כהונה לבת כהן משום שבכל מקום שנאמר בתורה \u0003\"כהן\"\u0004 הכוונה היא: \u0003ואפילו כהנת,\u0004 \u0003והכתיב: \"וכל מנחת כהן כליל תהיה לא תאכל\",\u0004 ומעתה גם שיירי מנחת כהנת לא ייאכלו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא לרבא בתשובה: \u0003רבי,\u0004"],["\u0003מטונך\u0004 \u0005[ממשאך],\u0006 ממה שאתה מקשה עלי, ממנו ראייה לשיטתי. שכן מה שלענין מנחה דינה של בת כהן כישראל, הרי זה משום ש\u0003\"אהרן ובניו\" כתובין בפרשה\u0004 של סדר הקרבת מנחת כהנים (\"וזאת תורת המנחה הקרב אותה בני אהרן לפני ה' אל פני המזבח\". ויקרא ו, ז) — להורות שהפרשה מדברת דווקא בכהנים ולא בבנות כהנים. ואולם בכל מקום שנאמר בו \"כהן\" בלבד — אף בת כהן בכלל זה, ולכך אפשר לתת אף לבת כהן מתנות כהונה.","ומביאים בענין זה מדברי תנאים בברייתות, \u0003דבי\u0004 \u0005[\u0006החכם \u0005של בית]\u0006 מדרשו של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]:\u0006 כל מקום שנאמר בכתוב בענין מתנות כהונה \u0003\"כהן\"\u0004 — הרי זה דווקא כהן \u0003ולא כהנת, וילמוד סתום\u0004 (הנאמר בסתם, בלא שפורש בו שמדובר בכהן) \u0003מן המפורש\u0004 בכהן האמור במנחה, שנאמר בו \"אהרן ובניו\" להדגיש שהכוונה דווקא לכהן ולא לכהנת.","\u0003דבי\u0004 \u0005[\u0006החכם \u0005של בית]\u0006 מדרשו של \u0003ר' אליעזר בן יעקב תנא\u0004 \u0005[שנה]:\u0006 אמנם כל מקום שנאמר בו \"כהן\" — הכוונה היא לכהן ולא לכהנת, ואולם \u0003\"כהן\"\u0004 האמור במתנות כהונה כוונתו: \u0003ואפילו כהנת.\u0004 וטעמ \u0003ו: שכן בתחילת פרשת מתנות זרוע לחיים וקיבה נאמר \"וזה יהיה משפט הכהנים\" (דברים יח, ג) — להורות\u0004 שהכוונה (כבשאר מקומות) דווקא לכהן ולא לכהנת. ובהמשך הפסוק נאמר \"ונתן לכהן הזרוע והלחיים והקיבה\" — ואף זה מורה על מיעוט, כהן ולא כהנת. ו\u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003מיעוט אחר מיעוט, ו\u0004כלל הוא ש\u0003אין מיעוט אחר מיעוט\u0004 בא \u0003אלא לרבות.\u0004 ולמדנו מכאן שבדין מתנות כהונה, אף \u0003כהנת בכלל.\u0004","ומוסרים כי \u0003רב כהנא\u0004 שהיה ישראל, ואשתו בת כהן, \u0003אכל\u0004 מתנות כהונה \u0003בשביל אשתו.\u0004 וכן \u0003רב פפא אכל בשביל אשתו,\u0004 וכן \u0003רב יימר אכל בשביל אשתו,\u0004 וכן \u0003רב אידי בר אבין אכל בשביל אשתו.\u0004","ובקביעת הלכה בסוגיות שנידונו למעלה, \u0003אמר רבינא,\u0004 כך \u0003אמר לי מרימר: הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רב\u0004 שזכות הלויים במתנות כהונה נתונה בספק, ולכן אין מוציאים אותן מידם למוסרן לכהנים. \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב חסדא\u0004 שהמזיק או אוכל מתנות כהונה פטור מלשלם על כך. \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003עולא\u0004 שמתנות כהונה ניתנות גם לבת כהן.","\u0003ו\u0004מוסיפים עוד הלכה, בנושא שלא נידון למעלה, ואולם הריהו קרוב לדינו של עולא: \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רב אדא בר אהבה\u0004 שאמר כי \u0003לויה\u0004 (בת לוי, אף שהיא נשואה לישראל) \u0003שילדה\u0004 בן בכור — \u0003בנה פטור מ\u0004נתינת \u0003חמש סלעים\u0004 לכהן בפדיונו, שהריהו כבנו של לוי הפטור מנתינה זו.","ועוד בדיני מתנת זרוע לחיים וקיבה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הזרוע והלחיים והקבה נוהגים\u0004 אף \u0003בכלאים\u0004 (בעלי חיים שנוצרו מהכלאת שני מינים) \u0003וב\u0004בעל החיים הנקרא \u0003כוי. ר' אליעזר אומר: כלאים הבא\u0004 (שנולד) \u0003מן העז ומן הרחל\u0004 — \u0003חייב במתנות\u0004 כהונה (זרוע לחיים וקיבה), ואילו הנולד \u0003מן התייש ומן הצבייה\u0004 — \u0003פטור מן המתנות,\u0004 שכן במתנות כהונה נאמר \"אם שור אם שה\", ואין הצביה בכלל \"שה\".","ותוהים: \u0003מכדי קיימא לן\u0004 \u0005[הרי מקובל בידינו],\u0006 (לעיל פ,א) כי \u0003לענין\u0004 מצוות \u0003כסוי הדם ו\u0004נתינת \u0003מתנות\u0004 כהונה \u0003לא משכחת ליה\u0004 \u0005[אין אתה מוצא]\u0006 את מחלוקתם זו של חכמים ור' אליעזר \u0003אלא ב\u0004נולד מה \u0003צבי הבא על התיישה, ובין לר' אליעזר בין לרבנן\u0004 \u0005[לחכמים]\u0006 — \u0003מספקא להו אי\u0004 \u0005[מסופק להם אם]\u0006 \u0003חוששין\u0004 (מתייחסים) \u0003לזרע האב\u0004 בקביעת זהות הנולד מהכלאה של שני מינים, והנולד מהם יש בו איפוא חלק צבי וחלק תיישה. \u0003אי\u0004 \u0005[או]\u0006 ש\u0003אין חוששין\u0004 לזרע האב, וקביעת זהותו הינה על פי האם, והריהו איפוא שה.","\u0003ו\u0004עוד \u0003ב\u0004שאלה האם האמור ש\u0003שה\u0004חייב במתנות, אינו לדעת הכל, \u0003ואפילו\u0004 ב\u0003מקצת שה קמיפלגי\u0004 \u0005[הם חלוקים].\u0006 ש\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]\u0006 כי \u0003\"שה\", ואפילו מקצת שה,\u0004 \u0003ולכך כיון שודאי יש בו מקצת שה, מצד אמו הריהו חייב במתנות כהונה.\u0004 \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אליעזר, \u0005סבור]\u0006 כי \u0003\"שה\" ואפילו מקצת שה לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 ולכן הריהו פטור ממתנות כהונה, שיש לחשוש לזרע האב שיש בו.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003ר' אליעזר\u0004 ש\u0003פטר\u0004 את הכלאיים ממתנות כהונה — שכן \u0003קסבר\u0004 \u0005[הוא סבור]\u0006 ש\u0003\"שה\" ולא מקצת שה. אלא ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003נהי נמי דקסברי\u0004 \u0005[אף שגם כן הם סבורים]\u0006 כי \u0003\"שה\" ואפילו מקצת שה\u0004חייב במתנות כהונה, רק \u0003פלגא לשקול\u0004 \u0005[חצי יקח]\u0006 הכהן במתנותיו, \u0003ו\u0004אילו \u0003אידך פלגא\u0004 \u0005[החצי השני],\u0006 \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 הבעלים לכהן: \u0003אייתי\u0004 \u0005[הבא]\u0006 \u0003ראיה\u0004 ש\u0003אין חוששין לזרע האב, ושקול\u0004 \u0005[וקח]\u0006 גם את החצי השני! \u0003אמר רב הונא בר חייא\u0004 בתשובה: \u0003מאי\u0004 \u0005[מה]\u0006 הכוונה בלשון \u0003\"חייב\" נמי דקא אמר\u0004 \u0005[גם כן שאמרו\u0006 חכמים\u0005]\u0006 — \u0003חייב בחצי מתנות.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על הסבר זה \u0003ר' זירא\u0004 ממה ששנינו כי בעל החיים הנקרא \u0003כוי\u0004 (שהוא ספק חיה ספק בהמה) \u0003יש בו\u0004 (בדינו) \u0003דרכים\u0004 (צדדים) ה\u0003שוין ל\u0004דיני \u0003בהמה, ויש בו דרכים\u0004 ה\u0003שוין ל\u0004דיני ה\u0003חיה, ויש בו דרכים\u0004 ה\u0003שוין לחיה ולבהמה.\u0004","ומפרטים: \u0003כיצד? חלבו אסור\u0004 — \u0003כחלב בהמה,\u0004 ולא כחלב חיה המותר. \u0003ודמו\u0004 (דם שחיטתו) \u0003חייב לכסות\u0004 בעפר — \u0003כדם החיה.\u0004 ויש בו \u0003דרכים שוין לבהמה ולחיה\u0004 — \u0003שדמו וגידו אסורין כבהמה וחיה, וחייב ב\u0004נתינת ה\u0003זרוע ולחיים והקבה\u0004 לכהן. \u0003ור' אליעזר פוטר\u0004 את הכוי ממתנות כהונה אלה.","\u0003ו\u0004\u0003מעתה יש לשאול:\u0004 \u0003אם איתא\u0004 \u0005[יש,\u0006 מקבלים\u0005]\u0006 את הסברו של רב הונא בר חייא, \u0003\"חייב בחצי מתנות\" מבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! ומשיבים: \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 \u0003חלבו ודמו,\u0004 \u0003דלא מתני\u0004 \u0005[שלא יכול לשנות]\u0006 בהם \u0003חצי\u0004 דמו, \u0003חצי\u0004 חלבו, שאין זה אפשרי שיהיה חצי מאלה מותר וחצי אסור, \u0003משום הכי\u0004 \u0005[כך],\u0006 גם \u0003לא קא תני\u0004 \u0005[לא שנה]\u0006 \u0003\"חצי\u0004 מתנותיו\".","ונמסר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשמו של \u0003ר' יוחנן: כוי ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003חייב בכולהו\u0004 \u0005[בכל]\u0006 ה\u0003מתנות. דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על הכתוב במתנות כהונה \"אם שור אם שה\" (דברים יח, ג): מאחר ודי היה לומר \u0003\"שור\", מה תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"אם שור\"\u0004 — \u0003לרבות את הכלאים,\u0004 שאף הם בכלל חיוב נתינה זו. וכן מאחר ודי היה לומר \u0003\"שה\", מה תלמוד לומר \"אם שה\"\u0004 — \u0003לרבות את הכוי,\u0004 שאף הוא חייב במתנות.","ושואלים: \u0003ור' אליעזר,\u0004 הפוטר את הכלאים ואת הכוי ממתנות כהונה, \u0003האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"אם\u0004 שור אם שה\" \u0003למה לי?\u0004 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 כתוב זה \u0003לחלק\u0004 בין שור לבין שה. שאלמלא כתוב זה היה מקום לחשוב שהשוחט בהמותיו חייב במתנות כהונה רק כששוחט גם שור וגם שה. ושואלים לצד האחר: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שדרשו מהמלים \"אם שור אם שה\" לענין \u0003אחר,\u0004 \u0003לחלק מנא להו\u0004 \u0005[מנין להם]?\u0006 ומשיבים: \u0003נפקא להו\u0004 \u0005[יוצא,\u0006 נלמד \u0005להם]\u0006 דין זה מן הכתוב \u0003\"מאת זובחי הזבח\"\u0004 — אפילו זבח אחד.","וחוזרים ושואלים: \u0003ור' אליעזר\u0004 שלמד דין זה מן הכתוב \"אם שור אם שה\", \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"מאת זובחי הזבח\" מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה,\u0006 דורש \u0005בו]?\u0006 ומשיבים: \u0003מבעי ליה\u0004 \u0005[נצרך לו]\u0006 כתוב זה \u0003לכ\u0004 דברי \u0003רבא,\u0004 שכן \u0003אמר רבא:\u0004 כשרוצה הכהן לתבוע את מתנותיו בבית דין, \u0003הדין עם הטבח\u0004 (הקצב), שהריהו תובע אותם מהקצב ששחט את הבהמה, אף שהבהמה עצמה \u0003של אחרים.\u0004","\u0003בכור\u0004 בהמה שהיה בעל מום, ומותר לשוחטו ולאוכלו, ואין נותנים ממנו מתנת זרוע לחיים וקיבה (כדרך ששנינו לעיל בתחילת הפרק), \u0003שנתערב במאה\u0004 בהמות של חולין, החייבות בנתינת זרוע לחיים וקיבה מהן לכשישחטו. \u0003בזמן שמאה\u0004 אנשים שונים \u0003שוחטין את כולן,\u0004 שכל אחת מהן שייכת לאדם אחר השוחטה — \u0003פוטרים את כולן\u0004 מהמתנות, שכל אחד יכול לומר שהבהמה שאותה הוא שחט היא הבכור, הפטור מן המתנות. ובזמן שאדם \u0003אחד\u0004 הוא הבעלים של כל מאה הבהמות הללו, והוא ה\u0003שוחט את כולן\u0004 — \u0003פוטרים לו\u0004 רק \u0003אחד\u0004 מהן ממתן מתנות.","\u0003השוחט\u0004 את בהמתו של הכהן \u0003לכהן ו\u0004כן השוחט את בהמתו של הגוי \u0003לגוי\u0004 — \u0003פטור מן המתנות,\u0004 שבהמת כהן ובהמת גוי פטורות מן המתנות. \u0003ו\u0004ישראל \u0003המשתתף\u0004 (השותף) \u0003עמהן,\u0004 עם הכהן או עם הגוי — \u0003צריך שירשום\u0004 (שיעשה סימן) בבהמה זו שיהא ניכר שיש בה שותפות כהן או גוי, ולכך היא פטורה מן המתנות. \u0003ואם\u0004 מכר כהן את בהמתו לישראל, ו\u0003אמר\u0004 לו שהיא מכורה לו, \u0003חוץ מן המתנות\u0004 שבה — \u0003פטור\u0004 הישראל \u0003מן המתנות,\u0004 שהרי אינן שלו, ואין הוא חייב לתת לכהן את דמיהן.","ואם \u0003אמר\u0004 הישראל לטבח: \u0003מכור לי בני מעיה של פרה\u0004 ששחטת, \u0003והיו בהן מתנות\u0004 (הקיבה) — הקונה \u0003נותנן לכהן, ואינו מנכה לו\u0004 לטבח \u0003מן\u0004 סכום \u0003הדמים\u0004 שקנה בו את בני המעיים, שהרי כשקנה ידע שהקיבה בכלל בני המעיים. ואולם אם \u0003לקחן\u0004 (קנה אותן) את בני המעיים, \u0003הימנו\u0004 (ממנו) \u0003במשקל,\u0004 שישלם לטבח עבור כל יחידת משקל של בני המעיים מחיר מסויים — הקונה אמנם \u0003נותנן\u0004 את הקיבה \u0003לכהן, ו\u0004אולם הריהו \u0003מנכה לו\u0004 לטבח \u0003מן הדמים\u0004 את משקל הקיבה.","שנינו במשנתנו כי אם התערבה בהמת בכור בתוך מאה בהמות של חולין השייכות למאה אנשים שונים, כולן פטורות ממתנות כהונה, מפני הספק. ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 כך הדין, שהרי יכול ש\u0003יבא עליו\u0004 ה\u0003כהן\u0004 על כל אחד מהשוחטים \u0003משני צדדין, ולימא ליה\u0004 \u0005[ויאמר לו]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בכור הוא\u0004 זה שאתה שוחט — \u0003כוליה דידי\u0004 \u0005[כולו שלי]\u0006 \u0003הוא, ואי לאו\u0004 \u0005[ואם לא]\u0006 \u0003בכור הוא\u0004 אלא בהמת חולין — \u0003הב לי\u0004 את \u0003מתנתאי\u0004 \u0005[מתנתי]!\u0006"],["\u0003אמר רב אושעיא\u0004 בתשובה: אכן כרגיל, יכול הכהן לטעון כך, ואולם במשנתנו מדובר \u0003ב\u0004אופן שבתחילה \u0003בא\u0004 הבכור \u0003לידי\u0004 ה\u0003כהן\u0004 כשהוא תמים, ולאחר מכן נפל בו מום קבוע, \u0003ומכרו\u0004 הכהן \u0003לישראל במומו,\u0004 ומעתה שוב אין הכהן יכול לתבוע את כל הבהמה בטענה שאם היא קדושה בקדושת בכור, שיתנו לו הבעלים את כולה, שהרי כבר קיבלה הכהן כבכור.","שנינו במשנתנו כי \u0003השוחט לכהן ו\u0004כן \u0003לגוי פטור מן המתנות.\u0004 ושואלים: \u0003וליתני\u0004 \u0005[ושישנה]\u0006 התנא באופן פשוט: \u0003כהן ו\u0004כן \u0003גוי פטורין מן המתנות! אמר רבא\u0004 בתשובה: \u0003זאת אומרת,\u0004 נוסח זה של המשנה בא להורות לנו כי \u0003הדין\u0004 (ההתדיינות) של הכהן לקבלת מתנות הכהונה, אינה עם בעלי הבהמה הנשחטת, אלא \u0003עם הטבח\u0004 (השוחט) את הבהמה. ואף טבח שהוא עצמו כהן ופטור ממתנות כהונה, כיון ששחט לישראל — הריהו חייב בהן.","וכן \u0003דרש רבא\u0004 על האמור בדין מתנות זרוע לחיים וקיבה, \"וזה יהיה משפט הכהנים מאת העם מאת זובחי הזבח אם שור אם שה ונתן לכהן הזרוע והלחיים והקיבה\" (דברים יח, ג): \u0003\"מאת העם\"\u0004 — דווקא מן הישראל ניתנות מתנות הכהונה, \u0003ולא מאת הכהנים,\u0004 ואולם \u0003כשהוא\u0004 הכתוב מוסיף ו\u0003אומר \"מאת זובחי הזבח\",\u0004 שמשמעו שניתנות המתנות מכל שוחט בהמה — \u0003הוי אומר\u0004 מכאן כי \u0003אפילו טבח כהן\u0004 השוחט בהמות לישראל \u0003במשמע,\u0004 שאף הוא חייב במתנות.","שנינו במשנתנו כי ישראל השותף עם כהן בבהמה, פטור ממתנות כהונה. ומסופר בענין זה כי \u0003אושפיזיכניה\u0004 \u0005[מארחו]\u0006 של \u0003ר' טבלא כהן הוה\u0004 \u0005[היה],\u0006 \u0003והוה דחיק ליה מלתא\u0004 \u0005[והיה דחוק לו הדבר,\u0006 שהיה נצרך מפני עוניו\u0005].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' טבלא,\u0004 להיוועץ בו מה יעשה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' טבלא: \u0003זיל אישתתף בהדי\u0004 \u0005[לך השתתף עם]\u0006 \u0003טבחי ישראל\u0004 בבהמותיהם, \u0003דמגו דמפטרי ממתנתא\u0004 \u0005[שמתוך ש\u0006בשל שותפותם אתך \u0005הם נפטרים מ\u0006חיוב \u0005מתנות\u0006 כהונה\u0005],\u0006 יסכימו \u0003משתתפי בהדך\u0004 \u0005[להשתתף אתך]\u0006 אף בלא תשלום.","הלך אותו כהן ועשה שותפות עם טבח ישראלי, ואולם לאחר שנשחטה הבהמה \u0003חייביה\u0004 \u0005[חייבו]\u0006 \u0003רב נחמן\u0004 לאותו טבח לתת מתנות כהונה, למרות שותפותו עם כהן בבהמה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו אדם לרב נחמן: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' טבלא פטרן\u0004 \u0005[פטר אותנו]\u0006 מלתת מתנות כהונה, שעשיתי כן בעצתו של ר' טבלא! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן בתשובה: \u0003זיל אפיק\u0004 \u0005[לך הוצא]\u0006 את מתנות הכהונה שתחת ידך ותן אותם לכהן, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 תעשה כן — הריני \u0003מפקינא\u0004 \u0005[מוציאני]\u0006 \u0003לך\u0004 את \u0003ר' טבלא מאונך\u0004 \u0005[מאוזנך]!\u0006","\u0003אזל\u0004 \u0005[הלך]\u0006 \u0003ר' טבלא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא עביד מר הכי\u0004 \u0005[מה טעם עשה אדוני כך],\u0006 להורות באופן זה, ושלא כדברי משנתנו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן בתשובה: משום \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 מארץ ישראל לבבל \u0003ר' אחא בר חנינא מדרומא, אמר\u0004 כי \u0003ר' יהושע בן לוי\u0004 וכל \u0003זקני דרום אמרו\u0004 ש\u0003כהן טבח\u0004 — \u0003שתים ושלש שבתות\u0004 (שבועות) ראשונים הריהו עדיין \u0003פטור מן המתנות,\u0004 משום שעדיין לא נקבע בכך כטבח, ואין הכל יודעים ומכירים אותו בתורת שכזה. ואולם \u0003מכאן ואילך\u0004 — הריהו \u0003חייב במתנות,\u0004 שכן כבר נקבע כטבח.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' טבלא לרב נחמן: \u0003ולעביד ליה מר מיהת\u0004 \u0005[ושיעשה לו אדוני לפחות]\u0006 \u0003כ\u0004הוראת \u0003ר' אחא בר חנינא,\u0004 ויהיה פטור מנתינת מתנות כהונה במשך שלושה שבועות ראשונים לשותפות! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן בתשובה: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 של ר' אחא בר חנינא נאמרו רק בזמן שהכהן הטבח \u0003לא קבע מסחתא\u0004 \u0005[איטליז],\u0006 לכך נדרשים שנים ושלושה שבועות עד שהוא נקבע בתודעת הכל כטבח, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 מדובר במי ש\u0003קבע מסחתא\u0004 \u0005[איטליז],\u0006 ולכך חייב מיד בנתינת מתנות.","ועוד בדיני מתנת כהונה בשחיטתו של כהן, \u0003אמר רב חסדא: האי כהנא דלא מפריש מתנתא\u0004 \u0005[כהן זה שאינו מפריש מתנות]\u0006 לכהן אחר — \u0003ליהוי בשמתא\u0004 \u0005[יהא בחרם]\u0006 של \u0003אלהי ישראל. אמר רבה בר רב שילא: הני טבחי\u0004 \u0005[אלה הטבחים]\u0006 של העיר \u0003הוצל\u0004 הריהם \u0003קיימי בשמתא\u0004 \u0005[עומדים בחרם]\u0006 של \u0003רב חסדא\u0004 \u0003הא עשרים ותרתי שנין\u0004 \u0005[זה עשרים ושתים שנה].\u0006 שכבר עברו עשרים ושתים שנה מאז הוחרמו על שאין הם מפרישים מתנות כהונה, ועדיין הם בחרם זה.","ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 השמיענו כן רב בר רב שילא: \u0003אילימא דתו לא משמתינן להו\u0004 \u0005[אם תאמר\u0006 כדי להשמיענו \u0005שיותר\u0006 מכך \u0005אין מחרימים אותם]\u0006 — \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 שאמנם אין מחרימים את עובר העבירה, ואולם \u0003במה דברים אמורים\u0004 — \u0003ב\u0004עובר על \u0003מצות לא תעשה,\u0004 שהרי הוא כבר עומד בעונש חמור ביותר, כמיתה וכרת. \u0003אבל ב\u0004נמנע מלקיים \u0003מצות עשה, כגון\u0004 ש\u0003אומרים לו\u0004 בית הדין \u0003\"עשה סוכה!\", ו\u0004הוא \u0003אינו עושה\u0004 כן, או שאומרים לו \"טול \u0003לולב!\", ואינו עושה\u0004 כן, או שאומרים לו \u0003\"עשה ציצית\u0004 לבגדך!\", \u0003ואינו עושה\u0004 כן — \u0003מכין אותו, עד שתצא נפשו.\u0004 ואף עם טבחי העיר הוצל יש להחמיר מעבר לעשרים ושתים השנה שעברו!","\u0003אלא\u0004 בא רבה בר רב שילא להשמיענו שמאחר שעמדו הטבחים הללו בעבירתם זמן כה רב, \u0003דקנסינן להו\u0004 \u0005[שקונסים אנו אותם]\u0006 אף \u0003בלא אתרייתא\u0004 \u0005[התראה].\u0006 \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003רבא קניס\u0004 \u0005[היה קונס]\u0006 את זה שאינו נותן מתנותיו לכהן, בלקיחת כל ה\u0003אטמא\u0004 \u0005[ירך]\u0006 הבהמה, ונתינתה לכהן. ובדומה לכך \u0003רב נחמן בר יצחק קניס\u0004 \u0005[היה קונס]\u0006 את זה שאינו נותן מתנותיו לכהן בלקיחת \u0003גלימא\u0004 \u0005[לבוש עליון]\u0006 ממנו ונתינתה לכהן.","\u0003ו\u0004עוד \u0003אמר רב חסדא\u0004 בדיני מתנות כהונה: ה\u0003זרוע\u0004 ניתנת \u0003ל\u0004כהן \u0003אחד, ו\u0004ה\u0003קבה\u0004 ניתנת \u0003ל\u0004כהן \u0003אחד,\u0004 ואילו ה\u0003לחיים\u0004 ניתנות \u0003לשניים\u0004 כהנים. ותוהים: \u0003איני\u0004 \u0005[האמנם]\u0006 כך הוא? \u0003והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003רב יצחק בר יוסף\u0004 מארץ ישראל לבבל \u0003אמר\u0004 ש\u0003במערבא פלגינן להו גרמא גרמא\u0004 \u0005[בארץ ישראל מחלקים אנו\u0006 את מתנות הכהונה \u0005עצם עצם],\u0006 שכל עצם שבהן ניתנת לשני כהנים! ומשיבים:","\u0003התם\u0004 \u0005[שם\u0006 בארץ ישראל\u0005]\u0006 \u0005מדובר\u0006 \u0003ב\u0004מתנות כהונה \u0003דתורא\u0004 \u0005[של שור],\u0006 שהוא בעל חיים גדול, וגם כאשר מחלקים כל אבר לשני כהנים, יש בכל אחד שיעור נתינה של ממש. מה שאין כן בבהמה דקה, שאם נחלק את איבריה לשני כהנים — שוב \u0003לא יהיה בכל חלק נתינה של ממש, והתורה אמרה \"ונתן לכהן\" (דברים יח, ג) —\u0004 שתהא זו נתינה יפה.","ועוד בדיני מתנות כהונה, \u0003אמר רבה בר בר חנה, אמר ר' יוחנן: אסור לאכול מבהמה\u0004 שנשחטה כל זמן \u0003שלא הורמה\u0004 (הופרשו) \u0003מתנותיה.\u0004 ועוד \u0003אמר רבה בר בר חנה, אמר ר' יוחנן\u0004 בענין זה כי \u0003כל האוכל מבהמה שלא הורמה מתנותיה\u0004 — הרי זה \u0003כאילו אוכל טבלים\u0004 (מפירות שנקבעו לתרומות ומעשרות, ולא הופרשו אלה מהם). ומסכמים: \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כשיטתו\u0006 זו של ר' יוחנן\u0005].\u0006","ועוד \u0003אמר רב חסדא\u0004 בדיני מתנות כהונה: \u0003מתנות כהונה,\u0004 אף שהן ניתנות מבהמת חולין, \u0003אין\u0004 הן \u0003נאכלות אלא צלי, ואין\u0004 הן \u0003נאכלות אלא ב\u0004תוספת תבלין ה\u0003חרדל.\u0004 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — שכן \u0003אמר קרא\u0004 \u0005[התורה]\u0006 במתנות הניתנות לכהנים \"וידבר ה' אל אהרן ואני הנה נתתי \u0003לך את משמרת תרומותי לכל קדשי בני ישראל לך נתתים למשחה\u0004 ולבניך לחק עולם\" (במדבר יח, ח), ומשמע המלה \u0003\"למשחה\"\u0004 — \u0003לגדולה,\u0004 שיאכלו הכהנים את המתנות הניתנות להם \u0003כדרך שהמלכים אוכלים,\u0004 ודרך המלכים לאכול בשר צלי ובחרדל.","\u0003ו\u0004עוד \u0003אמר רב חסדא\u0004 בדיני מתנות כהונה: כל \u0003עשרים וארבע מתנות כהונה, כל כהן שאינו בקי\u0004 (מתמצא) \u0003בהן\u0004 כיצד יש לנהוג בהן — \u0003אין נותנין לו מתנה.\u0004 ומסכמים: \u0003ולאו מילתא\u0004 \u0005[ולא דבר\u0006 הלכה\u0005]\u0006 \u0003היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' שמעון אומר: כל כהן שאינו מודה\u0004 (מאמין בלבו) \u0003בעבודה\u0004 במקדש בקרבנות שהריהי ציווי מאת ה' שניתן לנו על ידי משה — \u0003אין לו חלק ב\u0004קדשים הניתנים ל\u0003כהונה, שנאמר \"המקריב את דם השלמים ואת החלב מבני אהרן לו תהיה שוק הימין למנה\"\u0004 (ויקרא ז, לג) — שרק","המאמין בעבודת הולכת הדם (\"המקריב את דם השלמים\") זכאי במתנות הקרבן (\"לו תהיה שוק הימין למנה\"). ומוסיפים: \u0003אין לי אלא זה\u0004 (המוליך את הדם) \u0003בלבד,\u0004 שאם אינו מודה בעבודה זו, אין לו חלק במתנות כהונה, ו\u0003מנין לרבות\u0004 כן אף בשאר \u0003חמש עשרה עבודות, כגון\u0004 עבודות המנחה: \u0003היציקות\u0004 (נתינת השמן במנחה) \u0003והבלילות\u0004 של השמן, ושוב נתינת שמן על המנחה, \u0003והפתיתות\u0004 הנעשות במנחת המחבת והמרחשת ומנחת מאפה תנור, שהיו נקמצות לאחר אפיה ונפתתות וחוזרות לסולתן, \u0003והמליחות\u0004 הנעשות במנחה (ככתוב \"וכל קרבן מנחתך במלח תמלח\". ויקרא ב, יג), ה\u0003תנופות\u0004 (הולכה והבאה של המנחות החייבות בהנפה, שלא כל המנחות חייבות בה), \u0003והגשות\u0004 של המנחות בעודן בכלי קודם הקמיצה והבאתן לכדי נגיעה בקרן מערבית דרומית של המזבח, \u0005[והקמיצות], הקטרות\u0006 של הקרבנות על המזבח, \u0003(והמציות,\u0004 מיצוי הדם) [והמליקות הנעשות בקרבן העוף\u0005]\u0006"],["ו\u0003קבלות\u0004 (קבלת הדם לשם זריקתו על המזבח), ו\u0003הזאות\u0004 דם הקרבנות על המזבח, כל קרבן כדינו. \u0003והשקאת סוטה\u0004 במי סוטה לבדיקתה אם זינתה, \u0003ועריפת עגלה ערופה\u0004 בידי כהנים בנחל שלא נעבד, במקום בו נמצא גופת אדם שלא נודע מי הרגו. \u0003וטהרת מצורע\u0004 המביא צפורים ביום טהרתו, ובכלל שמזה הכהן מדם הצפור על המזבח, \u0003ונשיאות כפים\u0004 של כהנים המברכים את העם, \u0003בין\u0004 ברכת כהנים ש\u0003מבפנים\u0004 (בבית המקדש), \u0003בין\u0004 זו ש\u0003מבחוץ\u0004 למקדש, בבתי הכנסת במקומות יישובם של ישראל — לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בדינו של הכהן הזכאי למנה מן הקדשים, \u0003\"מבני אהרן\"\u0004 (ויקרא ז, לג), שלא רק בהולכה אמורים הדברים, אלא בכל \u0003עבודה האמורה לבני אהרן. ו\u0004מעתה יש לדייק בדברי הברייתא: שנינו בה כי","\u0003כל כהן שאינו מודה בה\u0004 — \u0003אין לו חלק ב\u0004מתנות \u0003כהונה.\u0004 ונדקדק: \u0003טעמא\u0004 \u0005[הטעם]\u0006 שאין לו חלק — מפני ש\u0003אינו מודה בה, הא\u0004 \u0005[הרי]\u0006 אם הוא \u0003מודה בה\u0004 — יש לו חלק, \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אינו בקי בהן,\u0004 ושלא כדברי רב חסדא שאין נותנים מתנות כהונה לכהן שאינו בקי בהן.","ועוד בענין הכהנים שאין נותנים להם מתנות כהונה, \u0003אמר ר' אבא, אמר רב הונא, אמר רב:\u0004 ה\u0003חוטין\u0004 (כלי דם) \u0003ש\u0004נמצאים \u0003בלחי\u0004 הבהמה \u0003אסורים\u0004 באכילה, \u0003ו\u0004משום כך \u0003כל כהן שאינו יודע\u0004 כיצד \u0003ליטלן\u0004 ממקומם, ויש חשש שיבוא לאוכלם — \u0003אין נותנין לו\u0004 את הלחיים ב\u0003מתנה\u0004 של כהונה.","ומעירים: \u0003ולא היא,\u0004 שאף שיש בחוטים הללו דם, אין הנותן מכשיל את הכהן באכילה אסורה. שכן בכל אופן שבו יתקין הכהן את הלחי לאכילה, לא יימצא דם בלחי. כי \u0003אי בטויא\u0004 \u0005[אם בצלי]\u0006 הוא מתקין לאכילה את הלחי — \u0003מידב דייבי\u0004 \u0005[זב]\u0006 הדם מהלחי באש הצלייה. \u0003ואי\u0004 \u0005[ואם]\u0006 הוא מתקין את הלחי \u0003ל\u0004בישול ב\u0003קדרה, אי דמיחתך להו ומלח להו\u0004 \u0005[אם\u0006 הוא \u0005חותך אותם\u0006 ומולח אותם] — \u0003מידב דייבי\u0004 \u0005[זב]\u0006 מהם הדם, ומותרת הלחי באכילה.","ובענין הדרך בה הכהן נוטל את מתנותיו מידי הבעלים, \u0003אמר רבא: בדק\u0004 (בחן) \u0003לן\u0004 \u0005[אותנו\u0006 התלמידים\u0005]\u0006 \u0003רב יוסף\u0004 בשאלה הבאה: \u0003האי כהנא דחטיף מתנתא\u0004 \u0005[כהן זה שחוטף מתנות\u0006 כהונה\u0005],\u0006 האם בכך \u0003חבובי קא מחבב\u0004 \u0005[לחבב הוא מחבב]\u0006 את ה\u0003מצוה, או זלזולי קא מזלזל\u0004 \u0005[לזלזל הוא מזלזל]\u0006 \u0003במצוה? ופשטנא ליה\u0004 \u0005[ופתרתי לו]\u0006 את שאלתו מן האמור במתנות כהונה \"ונתן לכהן הזרוע והלחיים והקבה\" (דברים יח, ג), שבאה הלשון \u0003\"ונתן\"\u0004 להורות שהבעלים הוא שיתן, \u0003ולא שיטול\u0004 הכהן \u0003מעצמו.\u0004 ומכאן שהחוטף את מתנותיו, מזלזל במצוה ולא מחבבה.","ובענין זה \u0003אמר אביי,\u0004 שכהן היה: \u0003מריש הוה חטיפנא מתנתא\u0004 \u0005[בתחילה הייתי חוטף מתנות],\u0006 שכן \u0003אמינא\u0004 \u0005[אמרתי]\u0006 לעצמי כי בכך \u0003חבובי קא מחביבנא\u0004 \u0005[לחבב הריני מחבב]\u0006 את ה\u0003מצוה.\u0004 ואולם \u0003כיון דשמענא להא\u0004 \u0005[ששמעתי את זו]\u0006 דרשת הכתוב \u0003\"ונתן\"\u0004 — \u0003ולא שיטול מעצמו, מיחטף לא חטיפנא\u0004 \u0005[לחטוף לא הייתי חוטף],\u0006 אלא \u0003מימר אמרי הבו לי\u0004 \u0005[הייתי אומר]\u0006 לבעל הבהמה שיתן לי את מתנותיו. \u0003ו\u0004אולם \u0003כיון דשמענא להא דתניא\u0004 \u0005[ששמעתי את זו ששנינו\u0006 בברייתא\u0005]\u0006 על הכתוב בבני שמואל הנביא \u0003\"ויטו אחרי הבצע\"\u0004 (שמואל א ח, ג) ובפירוש הכתוב \u0003ר' מאיר אומר: בני שמואל,\u0004 את \u0003חלקם\u0004 (מתנות לוי, כמעשר ראשון) \u0003שאלו בפיהם,\u0004 שדרשו מהבעלים שיתנו להם את מתנותיהם. מאז \u0003מימר נמי לא אמינא\u0004 \u0005[לומר\u0006 לבעלים \u0005גם כן לא הייתי אומר],\u0006 \u0003ו\u0004אולם \u0003אי יהבו\u0004 \u0005[היו נותנים]\u0006 \u0003לי, שקילנא\u0004 \u0005[הייתי לוקח]\u0006 מהם.","ואולם \u0003כיון דשמענא להא דתניא\u0004 \u0005[ששמעתי את זו ששנינו\u0006 בברייתא\u0005]\u0006 בכהנים שאכלו מלחם הפנים כי הכהנים \u0003הצנועים מושכין את ידיהם, ו\u0004אילו אלה \u0003הגרגרנים חולקים, משקל נמי לא שקילנא\u0004 \u0005[לקחת גם כן לא הייתי לוקח],\u0006 אף שנותנים לי, \u0003לבר ממעלי יומא דכיפורי\u0004 \u0005[חוץ מערב יום הכיפורים],\u0006 שמצות היום באכילה, ומרובות מאד הן הבהמות הנשחטות בו לאכילה, ולכך ניתנות ביום זה מתנות כהונה לרוב — כדי \u0003לאחזוקי נפשאי בכהני\u0004 \u0005[להחזיק עצמי,\u0006 להעמידני \u0005ב\u0006חזקת \u0005כהנים],\u0006 שאילו לא הייתי מקבל ממתנות הכהונה, עלול היה הדבר להטיל ספק בכהונתי.","ושואלים: \u0003ו\u0004\u0005הרי לצורך זה יכול היה\u0006 \u0003לפרוס ידיה\u0004 \u0005[לפרוש ידיו]\u0006 בברכת כהנים כל השנה, ובכך יודעים היו הכל כי הוא כהן? ומשיבים: \u0003אנסיה ליה עידניה\u0004 \u0005[אנסו זמנו],\u0006 שלא נמצאה לו עת לפרוש ידיו בברכת כהנים, משום שטרוד היה בכל עת בהרבצת תורה לתלמידיו, אף בעת שהציבור נאסף בבית הכנסת לתפילה.","ועוד \u0003אמר רב יוסף\u0004 בענין חלוקת מתנות כהונה: \u0003האי כהנא דאית ליה צורבא מרבנן בשבבותיה ודחיקא ליה מילתא\u0004 \u0005[כהן זה שיש לו תלמיד חכם\u0006 הגר \u0005בשכנותו ונצרך\u0006 לו הדבר, כי עני הוא\u0005]\u0006 — \u0003ליזכי ליה מתנתא\u0004 \u0005[שיזכה לו\u0006 בעל הבהמה את \u0005מתנותיו,\u0006 מתנות הכהונה שעתידים לבוא לידו מאנשי העיר\u0005]\u0006 לאותו תלמיד חכם עני, ויקחם העני לעצמו, \u0003ואף על גב דלא אתי לידיה\u0004 \u0005[ואף על פי שלא באו\u0006 מתנות הכהונה \u0005לידו\u0006 של הכהן\u0005].\u0006 וניתן לעשות כן \u0003במכרי כהונה ולויה,\u0004 באלה הרגילים ומוחזקים לתת את מתנותיהם לכהנים ולויים מסויימים. ובענין זה מסופר כי","\u0003רבא ורב ספרא איקלעו לבי\u0004 \u0005[הזדמנו לבית]\u0006 \u0003מר יוחנא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חנא בר אדא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהזדמנו \u0003לבי\u0004 \u0005[לבית]\u0006 \u0003מר יוחנא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חנא בר ביזנא. עביד להו עגלא תילתא\u0004 \u0005[עשה להם עגלה משולשת],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לשמעיה\u0004 \u0005[לשמשו]\u0006 של בעל הבית שהיה כהן, והיה בעל הבית רגיל לתת לו מתנותיו: \u0003זכי לן מתנתא\u0004 \u0005[זכה לנו מתנות],\u0006 \u0003דבעינא למיכל לישנא בחרדלא\u0004 \u0005[שרוצה אני לאכול לשון בחרדל]\u0006 והלשון עם הלחיים היא ממתנות הכהונה!","\u0003זכי ליה\u0004 \u0005[זכה לו]\u0006 השמש, ומסופר כי \u0003רבא\u0004 אמנם \u0003אכל, ו\u0004אילו \u0003רב ספרא לא אכל,\u0004 ובעקבות מעשה זה \u0003אקריוה\u0004 \u0005[הקריאו]\u0006 \u0003לרב ספרא בחלמא\u0004 \u0005[בחלום]\u0006 את הכתוב \u0003\"מעדה בגד ביום קרה חומץ על נתר ושר בשירים על לב רע\"\u0004 (משלי כה, כ), שיש במשמעו נזיפה ללומד תורה (\"שר בשירים\", וכדרך שיתבאר להלן) שאינו ראוי (\"לב רע\").","\u0003אתא לקמיה\u0004 \u0005[בא\u0006 רב ספרא \u0005לפני]\u0006 \u0003רב יוסף, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003משום דעברי אשמעתא דמר אקריין הכי\u0004 \u0005[שעברתי על דברי אדוני\u0006 שהורית כי \u0005אפשר לזכות מתנות כהונה לתלמיד חכם ואני לא נהגתי כן,\u0006 \u0005הקריאו לי כך]\u0006 להשמיעני נזיפה חמורה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לרב ספרא: אין זה כך, שכן נהגת כראוי, שהרי \u0003כי אמרי אנא\u0004 \u0005[כאשר אמרתי אני]\u0006 את הוראתי זו — היה זה דווקא \u0003ב\u0004כהן המזכה את מתנותיו לאדם \u0003אחר\u0004 מדעתו, ואולם \u0003שמעא\u0004 \u0005[\u0006ב\u0005שמש]\u0006 המזכה את מתנותיו לאורח חשוב המתארח בבית אדונו — לא אמרתי שמותר לעשות כן, שהרי \u0003בעל כרחיה מזכי\u0004 \u0005[בעל כרחו\u0006 הוא \u0005מזכה],\u0006 שחושש מאדונו. \u0003ו\u0004מלבד זאת, \u0003כי אמרי אנא\u0004 \u0005[כאשר אמרתי אני]\u0006 את הוראתי זו — היה זה דווקא \u0003למאן דלא אפשר ליה\u0004 \u0005[למי שאי אפשר לו]\u0006 לאכול אלא בדרך זו, שתלמיד חכם עני הוא, ואולם \u0003הא\u0004 \u0005[זה]\u0006 המקרה שהיה אצלך עם רבא — הרי \u0003אפשר ליה\u0004 \u0005[לו]\u0006 לרבא לאכול בשר משלו בחרדל, שהרי אין הוא עני ונזקק. ולכך נהגת \u0003כראוי בכך שלא אכלת.\u0004","שאל רב ספרא את רב יוסף: \u0003ואלא\u0004 אם כך הוא, \u0003מאי טעמא אקריין הכי\u0004 \u0005[מה טעם הקריאו לי כך]?\u0006 השיב לו רב יוסף: לא הקריאו כן כלפיך אלא \u0003כלפי רבא\u0004 שאכל, ושלא כהוראתי. ושואלים: \u0003ולקריין\u0004 \u0005[ושיקריאו]\u0006 \u0003לרבא\u0004 עצמו? ומשיבים: \u0003רבא נזוף הוה\u0004 \u0005[היה]\u0006 באותו זמן בשל מעשה זה, ולכך הקריאוהו לרב ספרא.","למעלה הובא שהוקרא לרב ספרא בחלום הפסוק \"מעדה בגד ביום קרה חומץ על נתר ושר בשירים על לב רע\", כרמז להנהגה הראויה באותו מעשה, ועל כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב דימי: ופשטיה דקרא במאי כתיב\u0004 \u0005[ופשוטו של מקרא\u0006 זה במשלי \u0005במה\u0006 הוא \u0005אמור]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ב\u0004רב ה\u0003שונה לתלמיד שאינו הגון.\u0004 שבדומה לבגד בלוי שאינו ראוי עוד ללבישה ויש להסירו (\"מעדה בגד\") ביום קרה, שאין בו כל תועלת, ובדומה לחומץ הניתן על החומר הנקרא \"נתר\" שהחומץ מקלקלו לבלי תועלת, כן אין תועלת בללמד תורה (\"שר בשירים\") לתלמיד שאינו הגון, שאין בלבו לקיימה (\"על לב רע\").","שכן \u0003אמר רב יהודה, אמר רב: כל השונה לתלמיד שאינו הגון\u0004 — \u0003נופל בגיהנם, ש\u0004כן \u0003נאמר \"כל חושך טמון לצפוניו תאכלהו אש לא נופח ירע שריד באהלו\"\u0004 (איוב כ, כו), \u0003ואין \"שריד\" אלא תלמיד חכם, ש\u0004כן \u0003נאמר \"ובשרידים אשר ה' קורא\"\u0004 (יואל ג, ה).","ועוד בענין זה מדברי רב, שכך \u0003אמר ר' זירא, אמר רב: כל השונה לתלמיד שאינו הגון\u0004 — הריהו \u0003כזורק אבן למרקוליס, ש\u0004כן \u0003נאמר \"כצרור אבן במרגמה כן נותן לכסיל כבוד\"\u0004 (משלי כו, ח), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"לא נאוה לכסיל תענוג\"\u0004 (שם יט, י).","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003המשתתף עמהן צריך לרשום. ו\u0004מקשים: מלשון הדברים עולה כי כך הדין \u0003אפילו\u0004 במשתתף \u0003עם הגוי, ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו כי \u0003המשתתף עם כהן\u0004 — \u0003צריך לרשום, והמשתתף עם הגוי ופסולי המוקדשים\u0004 — \u0003אין צריך לרשום!\u0004"],["ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 בברייתא זו, \u0005במה אנו עוסקים]\u0006 — \u0003דיתיב\u0004 \u0005[שיושב]\u0006 ה\u0003גוי אמסחתא\u0004 \u0005[באטליז,\u0006 בחנות למכירת בשר\u0005]\u0006 של הטבח הישראל, שבכך ניכר לכל שהגוי הוא שותפו של הישראלי, ולכן אין צריך לסמן שותפות זו. ואילו משנתנו מדברת בגוי שאינו יושב בחנות.","ושואלים על כך: אם כן מסתבר \u0003דכותה\u0004 \u0005[בדומה לכך]\u0006 גם זה ששנינו באותה ברייתא \u0003גבי\u0004 \u0005[אצל]\u0006 המשתתף עם ה\u0003כהן\u0004 שצריך לרשום, שמדובר גם כן באופן \u0003דיתיב אמסחתא\u0004 \u0005[שיושב\u0006 הכהן \u0005באטליז],\u0006 ו\u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003צריך לרשום\u0004 שיש לו בה שותפות עם הכהן? ומשיבים: בזה שהכהן יושב בחנות הבשר, אין היכר שהריהו שותף במכירת הבשר, \u0003דאמרי בשרא קא זבין\u0004 \u0005[ש\u0006כן \u0005אומרים\u0006 האנשים כי \u0005הוא קונה בשר],\u0006 ולכן הוא נמצא שם. ותוהים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 על \u0003גוי נמי\u0004 \u0005[גם כן]\u0006 \u0003אמרי בשרא קא זבין\u0004 \u0005[אומרים\u0006 האנשים כי \u0005בשר הוא קונה]!\u0006","\u0003אלא הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003דיתיב\u0004 \u0005[שיושב]\u0006 ה\u0003גוי אכספתא\u0004 \u0005[על הכספת,\u0006 בצד הקופה בה ניתן הכסף מאת הלקוחות\u0005],\u0006 והרי זו הוכחה ברורה שהגוי שותף במכירת הבשר, ולכך אין צריך לציין את שותפותו. ותוהים גם על הסבר זה: אם כן מסתבר \u0003דכותה\u0004 \u0005[בדומה לכך]\u0006 גם זה ששנינו באותה ברייתא \u0003גבי\u0004 \u0005[אצל]\u0006 המשתתף עם ה\u0003כהן\u0004 שמדובר באופן \u0003דיתיב אכספתא\u0004 \u0005[שיושב\u0006 הכהן \u0005על הכספת],\u0006 ומעתה \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003צריך לרשום\u0004 שותפות עם הכהן, והרי ניכר לכל שהכהן הוא שותפו? ומשיבים: גם כשהכהן יושב בצד הקופה, אין בכך הוכחה כי הוא שותף במכירת הבשר, שכן \u0003אמרי המוני הימניה\u0004 \u0005[אומרים\u0006 האנשים שמניח לו בעל החנות לשבת שם כי הוא \u0005מאמינו]\u0006 שיכול הוא להפקידו על הקופה לשומרה מפני גנבים. ומקשים על הסבר זה: והרי ב\u0003גוי נמי גם כן]\u0004 היושב בצד הקופה \u0005[אומרים\u0006 האנשים כי \u0005מאמינו]\u0006 בעל החנות שלא יקח כסף לעצמו!","ומשיבים: \u0003אין\u0004 זה דבר רגיל בישראל שתהא \u0003אמונה בגוי.\u0004 ומוסיפים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הסבר אחר: אמנם מדובר (כפי שהוסבר בתחילה) בברייתא הן בכהן והן בגוי היושבים בחנות (ולא בצד הקופה), וניכר שהגוי שותף במכירת הבשר, שכן \u0003סתם גוי\u0004 השותף בחנות הריהו \u0003מפעא פעי\u0004 \u0005[צועק]\u0006 על המוכר בהערות ובהוראות, וכגון \"אל תמכור במחיר זה אלא במחיר אחר\". ואילו הכהן, אף שהוא יושב בחנות, אינו מתערב בעבודתו של המוכר, שהריהו צנוע וסומך על המוכר שיודע מלאכתו נאמנה, ואין זה ניכר שהריהו שותף, ולכך צריך לסמן שהוא שותף.","ועוד באותו ענין שנינו ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ופסולי המוקדשין\u0004 לאחר שנפדו ויצאו לחולין כדינם, ונשחטו, והרי הם פטורים ממתנות כהונה — \u0003אין צריך לרשום\u0004 שאלה פסולי מוקדשים. ושואלים: \u0003אלמא\u0004 \u0005[מכאן נסיק]\u0006 כי בפסולי המוקדשים \u0003מוכחא מלתא\u0004 \u0005[מוכח הדבר]\u0006 מצד עצמם שהריהם פסולי מוקדשים, ולכן אין צורך ברישום. \u0003ו\u0004אולם \u0003הא אנן תנן\u0004 \u0005[הרי שונים אנו]\u0006 בדרך מכירת \u0003פסולי המוקדשין\u0004 שהם \u0003נמכרים באיטליז\u0004 (מקום ממכר בשר), כשאר בשר בהמות חולין, \u0003ו\u0004בדומה לכך הם \u0003נשחטים באיטליז, ונשקלים ב\u0004יחידות משקל שונות כ\u0003ליטרא,\u0004 ונמצא אם כן שנוהגים בהם כבבשר בהמות חולין, ואין היכר לבשר פסולי המוקדשים!","ומשיבים: אכן \u0003תרגמא\u0004 \u0005[פירש]\u0006 \u0003רב אדא בר אהבה קמיה\u0004 \u0005[לפני]\u0006 \u0003רב פפא\u0004 את דברי משנתנו שמדובר בה רק \u0003באותן\u0004 פסולי המוקדשים \u0003הנמכרים בתוך הבית,\u0004 בהמת בכור ובהמת מעשר, שדמי פדיונן ניתן לבעליהן, שכן אין קדושה לדמיהן. ולא התירו \u0003חכמים למוכרן בשוק, אלא רק בתוך הבית, אף שיש בדבר הפסד מסויים (שכן במכירה בשוק מרובים הם הקונים, והמחיר גבוה יותר). ומעתה ניכר בהם שהריהם פסולי המוקדשים, ואין צורך לרשום כן.\u0004","ועוד בדין מתנות כהונה בשותפים, \u0003אמר רב הונא:\u0004 אם היה הישראל בעל הבהמה \u0003שותף\u0004 עם הכהן או הגוי רק \u0003בראש\u0004 הבהמה, ולא בשאר גופה — הריהו \u0003פטור\u0004 רק \u0003מן\u0004 מתנת \u0003הלחי\u0004 שהוא חלק מראש הבהמה, ואולם הריהו חייב בנתינת הזרוע והקיבה. וכיוצא בזה אם היה הישראל \u0003שותף\u0004 עם הכהן רק \u0003ביד\u0004 הבהמה — הריהו \u0003פטור\u0004 רק \u0003מן הזרוע,\u0004 שהיא חלק מיד הבהמה. וכן הוא אם היה \u0003שותף\u0004 רק \u0003בבני\u0004 ה\u0003מעיין\u0004 — הריהו \u0003פטור\u0004 רק \u0003מן הקבה,\u0004 שהיא חלק מבני המעיים של הבהמה. \u0003ו\u0004אילו \u0003חייא בר רב אמר\u0004 כי \u0003אפילו\u0004 היה הכהן \u0003שותף\u0004 רק \u0003באחת מהן\u0004 — הריהו \u0003פטור מ\u0004כל המתנות \u0003כולן. מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת חייא","בר רב ממה ששנינו: כהן המציע לטבח שותפות בבהמה באופן ש\"רק \u0003הראש\u0004 של הבהמה הוא \u0003שלי, ו\u0004שאר כל הבהמה \u0003כולה שלך\", ואפילו\u0004 אם הציע לו שותפות בבהמה באופן שרק חלק \u0003אחד ממאה בראש\u0004 הבהמה הינו שלו, והשאר של חבירו — הריהו \u0003פטור.\u0004 וכן אם הציע לו שותפות באופן ש\"רק \u0003היד\u0004 של הבהמה הינה \u0003שלי ו\u0004שאר כל הבהמה \u0003כולה שלך\".\u0004 ו\u0003אפילו\u0004 הוא מותיר לעצמו רק \u0003אחד ממאה ביד\u0004 — הריהו \u0003פטור.\u0004 ובדומה לכך בשותפות וכן אם אמר כי \"רק \u0003בני\u0004 ה\u0003מעיין\u0004 של הבהמה הם \u0003שלי, ו\u0004שאר כל הבהמה \u0003כולה\u0004 הוא \u0003שלך\",\u0004 ו\u0003אפילו\u0004 כשאמר שרק חלק \u0003אחד ממאה בהן,\u0004 מבני המעיים הוא שלו, ושאר כל הבהמה של חבירו — \u0003פטור.\u0004","ומציעים: \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שהריהו \u0003פטור מן הלחי\u0004 (בשותפות בראש בלבד), \u0003ו\u0004אולם הריהו \u0003חייב בכולן\u0004 (זרוע וקיבה), וכן הריהו \u0003פטור מן הזרוע\u0004 (בשותפות ביד בלבד), \u0003ו\u0004אולם \u0003הוא\u0004 \u0003חייב בכולן\u0004 (לחיים וקיבה). וכן הריהו \u0003פטור מן הקבה\u0004 (בשותפות בבני המעיים בלבד), \u0003ו\u0004אולם \u0003הוא\u0004 \u0003חייב בכולן\u0004 (לחיים וזרוע), ושלא כדעת חייא בר רב! ודוחים: \u0003לא,\u0004 כוונת הדברים שהריהו \u0003פטור מכולן.\u0004","ושואלים: אם כך הוא, \u0003ליתני\u0004 \u0005[שישנה]\u0006 התנא במפורש \u0003פטור מכולן\u0004 (במקום הלשון \"פטור\" שאינה מבוררת דיה)! \u0003ועוד\u0004 מקשים על דעת חייא בר רב: שכן \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 מפורשת בדין שותפות שאם אומר הכהן לטבח הישראל \"רק \u0003הראש\u0004 של הבהמה הוא \u0003שלי ו\u0004שאר כל הבהמה \u0003כולה\u0004 הוא \u0003שלך\",\u0004 ו\u0003אפילו\u0004 לא היה לו אלא חלק \u0003אחד ממאה בראש\u0004 הבהמה — הריהו \u0003פטור מן הלחי\u0004 בלבד, \u0003ו\u0004אולם הריהו \u0003חייב ב\u0004שאר המתנות \u0003כולן,\u0004 שלא כדברי חייא בר רב! ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 זו שעל דעת \u0003חייא בר רב\u0004 היא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 שאין עליה מענה, ונדחו דבריו.","\u0003אמר רב חסדא\u0004 בהסבר דבריו של חייא בר רב (שנדחו דבריו למעלה מפני דברי ברייתא): \u0003הא מתניתא אטעיתיה\u0004 \u0005[ברייתא זו\u0006 שתובא בהמשך היא ש\u0005הטעתו]\u0006 \u0003לחייא בר רב,\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003עשרים וארבע מתנות כהונה הן,\u0004 הניתנות לכהנים, \u0003וכולן ניתנו\u0004 (ציוותה התורה על נתינתן) \u0003לאהרן ולבניו ב\u0004לשון \u0003כלל\u0004 (שבתחילת פרשת מתנות הכהונה נאמר \"וידבר ה' אל אהרן ואני הנה נתתי לך את משמרת תרומותי לכל קדשי בני ישראל לך נתתים למשחה ולבניך לחק עולם\", במדבר יח, ח). \u0003ו\u0004חזרו וניתנו בלשון \u0003פרט\u0004 שבהמשך הפרשה באה רשימה מפורטת של מתנות הכהונה. \u0003ו\u0004בסוף פרשת מתנות הכהונה נאמר \u0003\"ברית מלח\u0004 עולם היא\" (שם פסוק יט), שהבטחה היא: כשם שברית מלח אינה שובתת, כן מתנות כהונה לא תשבותנה.","ולכך \u0003כל המקיימן,\u0004 שנותן מתנות כהונה — \u0003כאילו קיים\u0004 את מצוותן ש\u0003ב\u0004לשון \u0003כלל ו\u0004שבלשון \u0003פרט ו\u0004קיום הבטחת \u0003ברית מלח, וכל העובר עליהן,\u0004 שאינו נותנן \u0003—\u0004 \u0003כאילו עובר על בכלל ופרט וברית מלח.\u0004","\u0003ואלו\u0004 עשרים וארבע המתנות, מתחלקות \u0003הן\u0004 לקבוצות: \u0003עשר\u0004 מהן נאכלות בעזרה ש\u0003במקדש, וארבע\u0004 מהן נאכלות \u0003בירושלים, ועשר\u0004 מהן נאכלות \u0003בגבולים,\u0004 בארץ ישראל מחוץ לירושלים. ומפרטים: \u0003אלו הן\u0004 \u0003עשר\u0004 \u0003מתנות כהונה שנאכלות\u0004 \u0003במקדש:\u0004 בשר קרבן ה\u0003חטאת, וחטאת העוף\u0004 ו\u0003אשם ודאי, ואשם תלוי, וזבחי שלמי צבור\u0004 (כבשי עצרת, שהינם קדשי קדשים הנאכלים רק בעזרה), \u0003ולוג שמן\u0004 הנשאר לאחר נתינת השמן \u0003של מצורע\u0004 עליו לטהרו, שהריהו נאכל לכהנים בעזרה. \u0003ו\u0004קרבן \u0003שתי הלחם, ולחם הפנים, ושירי מנחות, ומנחת העומר. ו\u0004אלו הן","\u0003ארבע\u0004 מתנות כהונה שנאכלות \u0003ב\u0004כל \u0003ירושלים: הבכורה\u0004 (בהמה הקדושה בקדושת בכור שאין בה מום), \u0003והבכורים, ו\u0004ה\u0003מורם מן\u0004 קרבן \u0003התודה\u0004 (חזה ושוק וארבע חלות הבאות מארבעת מיני החלה שבמנחת התודה: חלות, רקיקים, רבוכה וחמץ). \u0003ומאיל נזיר\u0004 (הזרוע בשלה וחלה ורקיק, שכל אלה נמנים כדבר אחד, ובכלל אלה אף חזה ושוק של שאר שלמים), \u0003ועורות קדשים\u0004 של קרבן עולה וחטאת ואשם, שניתנים לכהנים.","\u0003ו\u0004אלו הן \u0003עשר\u0004 מתנות כהונה שניתנות \u0003בגבולים: תרומה, ותרומת מעשר, וחלה, וראשית הגז, ומתנות\u0004 כהונה (זרוע, לחיים וקיבה), \u0003ו\u0004חמש סלעים דמי \u0003פדיון הבן, ו\u0004שה הניתן \u0003ב\u0004\u0003פדיון פטר חמור,\u0004","\u0003ושדה אחוזה\u0004 שהקדיש אדם ולא גאלה ומכרה הגזבר לאחר, והריהי יוצאת ביובל ומתחלקת לכהנים של המשמר העובד במקדש בעת שאירע בו היובל, \u0003ושדה\u0004 וקרקע שאמר בהן אדם שהריהן \u0003חרמים,\u0004 שהן ניתנות לכהנים, \u0003וגזל הגר\u0004 שאין לו יורשים, ונשבע הגזלן שלא גזלו, ולאחר שמת הגר הודה הגזלן שנשבע לשקר, שחייב בנתינת קרן (שווי הגזילה) ועוד חמישית, ואלו ניתנים לכהנים.","ועתה מסביר רב חסדא כיצד הוטעה חייא בר רב מדברי ברייתא זו, שכן \u0003הוא\u0004 (חייא בר רב) \u0003סבר: מדקא חשיב להו\u0004 \u0005[מתוך שהוא\u0006 התנא בברייתא \u0005חושב,\u0006 מונה \u0005אותן]\u0006 ה\u0003מתנות\u0004 (זרוע לחיים וקיבה) לא כשלש מתנות אלא \u0003בחדא\u0004 \u0005[באחת]\u0006 — מכאן שכל השלוש מתנה \u0003חדא נינהו\u0004 \u0005[אחת הן],\u0006 ואם נפטר אדם מאחת מהן, הריהו פטור מכולן. \u0003ו\u0004אולם, מסכם רב חסדא \u0003כי\u0004 \u0003לא היא\u0004 המסקנה הנכונה. וראיה לדבר: \u0003אטו\u0004 \u0005[וכי]\u0006 ה\u0003מורם מ\u0004קרבן \u0003תודה ואיל נזיר דקא חשיב להו כחדא\u0004 \u0005[שהוא\u0006 התנא בברייתא \u0005מונה אותם כאחד],\u0006 האם \u0003משום דחדא נינהו\u0004 \u0005[שאחד הם]?!\u0006 והרי אלה מתנות נפרדות לחלוטין! \u0003אלא כיון דדמיין להדדי\u0004 \u0005[ש\u0006הם \u0005דומים זה לזה]\u0006 — \u0003חשיב להו כחדא\u0004 \u0005[מנה אותם כאחד],\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 לענין זרוע לחיים וקיבה, \u0003כיון דדמיין להדדי\u0004 \u0005[שדומות זו לזו]\u0006 — \u0003חשיב להו כחדא\u0004 \u0005[מנה אותן כאחד].\u0006","ועוד בדין שותפות כהן וטבח ישראל לענין מתנות כהונה, \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]:\u0006 אם אמר הכהן לטבח הישראלי קודם שנשחטה הבהמה (שהוא זמן חיובה במתנות כהונה) שישתתפו בבהמה באופן ש\u0003הראש\u0004 של הבהמה הוא \u0003שלך ו\u0004שאר כל הבהמה \u0003כולה\u0004 הוא \u0003שלי, מהו\u0004 הדין, האם חייב בנתינת הלחיים לכהן? וצדדי השאלה: האם \u0003בתר חיובא אזלינן\u0004 \u0005[אחר\u0006 איברי הבהמה שיש בהם \u0005חיוב\u0006 מתנות \u0005אנו הולכים],\u0006 \u0003ו\u0004הרי \u0003חיובא גבי\u0004 \u0005[חיוב\u0006 מתנת לחיים \u0005אצל]\u0006 \u0003ישראל הוא, או דלמא בתר\u0004 \u0005[שמא אחר]\u0006 \u0003עיקר\u0004 ה\u0003בהמה אזלינן\u0004 \u0005[הולכים אנו],\u0006 \u0003ועיקר\u0004 גוף ה\u0003בהמה\u0004 של ה\u0003כהן הוא?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה ממה ששנינו: \u0003גוי ו\u0004כן \u0003כהן שמסרו צאנם לישראל\u0004 שיהיה שליחם \u0003לגזוז\u0004 אותו — \u0003פטור\u0004 הגוזז מנתינת ראשית הגז. וכמו כן \u0003הלוקח\u0004 (הקונה) את \u0003גז צאנו של גוי,\u0004 עוד בטרם נגזז הצאן — הריהו \u0003פטור מראשית הגז. ו\u0004מוסיפים כי בנושא","\u0003זה\u0004 של הקונה דבר טרם התחייבותו במתנות כהונה יש צד \u0003חומר\u0004 (חומרה) שיש \u0003ב\u0004מתנת \u0003זרוע ובלחיים ובקבה יותר מראשית הגז.\u0004 שכן הקונה מן הכהן קודם שחיטת הבהמה את חלקי הבהמה החייבים במתנות, הריהו חייב במתנות כהונה, ואילו הקונה מן הגוי קודם גזיזת הצאן את גז צאנו, הריהו פטור ממתנות כהונה. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003בתר חיובא אזלינן\u0004 \u0005[אחר החיוב אנחנו הולכים],\u0006 ומסיקים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכך הוא, ונפתרה בעייתם של חכמים.","שנינו במשנתנו ש\u0003אם אמר לו\u0004 הכהן לישראל שהוא מוכר לו את בהמתו \u0003חוץ מן המתנות\u0004 שבה — הישראלי \u0003פטור מן המתנות,\u0004 שכן אינן שלו, ואינו חייב לתת לכהן את דמיהן."]]};
